// Correcciones Simulia — tanda 3 — parte 5 de 7: protocolos y escalas (preguntas propias) (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9e") }, {"long_answer": "La transposición ovárica consiste en desplazar los ovarios fuera del campo de irradiación para preservar su función, y según la guía es preferible plantearla en pacientes jóvenes con riesgo intermedio que vayan a recibir radioterapia pélvica, en quienes se espera conservar la función ovárica. No está indicada en todas las pacientes, ni tiene sentido si no van a recibir radioterapia. En el adenocarcinoma no relacionado con el VPH se desaconseja conservar los ovarios por el riesgo de metástasis ováricas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca1") }, {"long_answer": "La guía recomienda evaluar la respuesta al tratamiento con radioquimioterapia y braquiterapia a los tres meses de finalizarlo, mediante exploración física y las mismas pruebas de imagen utilizadas en el diagnóstico, generalmente resonancia magnética pélvica y, si procede, PET-TC, lo que permite comparar con la situación inicial. Una biopsia sistemática al mes resulta precoz, ya que el tumor sigue regresando tras la radioterapia. La citología mensual no es útil en el seguimiento inmediato, y esperar un año retrasaría la detección de una enfermedad persistente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca4") }, {"long_answer": "Ante la sospecha de cáncer de cuello uterino durante el embarazo, el diagnóstico histológico debe confirmarse mediante biopsia dirigida por colposcopia, y si es necesario valorar la profundidad de la invasión puede realizarse una conización, preferentemente en el primer trimestre o al inicio del segundo para limitar riesgos obstétricos. El legrado endocervical está contraindicado en la gestación por el riesgo de rotura de membranas y hemorragia. Esperar al parto para la biopsia retrasaría el diagnóstico, y la citología es una prueba de cribado, no de confirmación histológica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cae") }, {"long_answer": "El test de Apgar valora al recién nacido al minuto y a los cinco minutos de vida mediante cinco parámetros puntuados de 0 a 2: frecuencia cardíaca, esfuerzo respiratorio, tono muscular, irritabilidad refleja y color de la piel, con una puntuación máxima de 10. El peso al nacer, la temperatura, el tamaño o los pulsos femorales no forman parte de la escala. El llanto se tiene en cuenta dentro del esfuerzo respiratorio y la respuesta refleja, pero no constituye un parámetro independiente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cba") }, {"long_answer": "La valoración del dolor mediante PQRST es una regla mnemotécnica que recoge sus características principales: P se refiere a los factores que provocan o alivian el dolor, Q a su calidad, R a la región y la irradiación, S a la severidad o intensidad y T al tiempo, es decir, inicio, duración y frecuencia. No registra el tipo de analgesia utilizada, aunque esta influya en el dolor. Las opciones que se limitan a la intensidad o a la duración y frecuencia recogen solo una parte de la valoración.", "option_2": "Factores provocadores o paliativos, calidad, región e irradiación, severidad y tiempo del dolor"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cbf") }, {"long_answer": "El índice de comorbilidad de Charlson asigna puntos a distintas enfermedades crónicas en función de su impacto pronóstico, y en algunas versiones se ajusta por edad; una puntuación elevada indica mayor carga de comorbilidad, peor pronóstico y mayor riesgo de mortalidad a medio plazo. Por ello no se asocia a mejor pronóstico ni a menor riesgo de complicaciones. Tampoco mide la independencia funcional, que se valora con escalas como Barthel o Katz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc1") }, {"long_answer": "La escala de coma de Glasgow valora la apertura ocular, de 1 a 4 puntos, la respuesta verbal, de 1 a 5, y la respuesta motora, de 1 a 6, por lo que su puntuación oscila entre 3 y 15. La puntuación de 15 indica el mejor nivel de conciencia, propio de un paciente consciente y orientado. Una puntuación de 0 no es posible en esta escala, ya que el mínimo es 3. Un valor de 5 indica coma profundo y uno de 10 una alteración moderada del nivel de conciencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc4") }, {"long_answer": "La escala NIHSS (National Institutes of Health Stroke Scale) cuantifica la gravedad del déficit neurológico en el ictus mediante la valoración del nivel de conciencia, la mirada, los campos visuales, la paresia facial, la fuerza de los miembros, la ataxia, la sensibilidad, el lenguaje, la disartria y la extinción o negligencia. Se utiliza para la toma de decisiones como la indicación de trombólisis y el seguimiento. No incluye antecedentes familiares ni presión arterial, ni la función renal o hepática, ni las frecuencias cardíaca y respiratoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc9") }, {"long_answer": "El Inventario de Depresión de Beck-II consta de 21 ítems puntuados de 0 a 3, con un total de 0 a 63. Sus puntos de corte establecen depresión mínima entre 0 y 13 puntos, leve entre 14 y 19, moderada entre 20 y 28 y grave entre 29 y 63. Por tanto, el rango de 20 a 28 corresponde a la depresión moderada. El intervalo de 14 a 19 indica depresión leve, el de 0 a 13 depresión mínima y el de 29 a 63 depresión grave.", "option_1": "14-19", "option_2": "20-28", "option_4": "29-63"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cce") }, {"long_answer": "La escala de Framingham estima el riesgo de desarrollar enfermedad cardiovascular a 10 años a partir de factores como la edad, el sexo, el colesterol total y HDL, la presión arterial, el tabaquismo y la diabetes, y se utiliza para orientar las medidas de prevención primaria. No estima el riesgo de insuficiencia cardíaca a un año. Tampoco es una herramienta diagnóstica de hipertensión arterial, que se basa en mediciones repetidas de la presión, ni sirve para calcular la presión arterial media."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd0") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas recuerda que el consumo de alcohol en la adolescencia, a cualquier dosis, interfiere en la maduración del sistema nervioso central, que continúa desarrollándose hasta pasados los veinte años, y puede afectar a funciones cognitivas como la memoria, la atención y el aprendizaje. Por ello no existe una dosis segura en menores. Es falso que mejore la concentración o que carezca de efecto a dosis bajas, y su impacto no se limita al desarrollo físico, sino que afecta también al intelectual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd3") }, {"long_answer": "Según el Boletín de indicadores clave del Plan Nacional sobre Drogas, con datos de la encuesta ESTUDES, en 2023 el 5,1% de los estudiantes de 14 a 18 años presentaba un posible trastorno por uso de videojuegos, valorado con criterios basados en el DSM-5. Los porcentajes del 7,1%, el 6,1% y el 4,5% son valores próximos que no corresponden al dato de 2023 recogido en el documento, por lo que deben descartarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd8") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas recoge que en 2024 el 16% de la población adulta declaró haber realizado consumo intensivo de alcohol o binge drinking en el último mes, es decir, haber tomado cinco o más bebidas en unas dos horas. Los porcentajes del 15,4% y el 15,5% son valores muy próximos que no corresponden al dato de 2024, y el 18,2% lo sobrestima, por lo que ninguno es correcto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce3") }, {"long_answer": "Para estimar la proporción de adultos con trastorno por consumo de heroína, el Plan Nacional sobre Drogas utiliza un modelo multiplicativo que combina los datos de la encuesta EDADES con los registros de admisiones a tratamiento, ya que el consumo de heroína es poco frecuente y está infrarrepresentado en las encuestas poblacionales. No se basa en encuestas exclusivas a población encarcelada, que no representa al conjunto de la población. Tampoco se utilizan solo registros de urgencias ni datos de venta de opioides, que no permiten estimar este trastorno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce5") }, {"long_answer": "Según el Boletín de indicadores clave del Plan Nacional sobre Drogas, en 2023 aproximadamente el 42% de las personas atendidas por trastorno por uso de sustancias llegaron a tratamiento derivadas desde otros dispositivos o servicios, dato que refleja la coordinación entre recursos sanitarios, sociales y judiciales. Los porcentajes del 39,8%, el 45,9% y el 50,2% son cifras próximas que no corresponden al dato de 2023 recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf3") }, {"long_answer": "Las Guías de Práctica Clínica tienen como objetivo principal ayudar a profesionales y pacientes a tomar decisiones clínicas adecuadas, eficientes y seguras, basadas en la mejor evidencia científica disponible, reduciendo la variabilidad injustificada en la atención al parto normal. No son protocolos de aplicación obligatoria, ya que no sustituyen el juicio clínico. No pretenden reducir la intervención del personal sanitario, sino evitar las intervenciones innecesarias, y no priorizan la tecnología sobre la participación de la mujer, sino que promueven su implicación en las decisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf9") }, {"long_answer": "La implantación de la Guía de Práctica Clínica sobre la atención al parto normal pretende mejorar la calidad de la atención y la satisfacción de los profesionales, de las mujeres y de sus familias, promoviendo prácticas basadas en la evidencia, menos intervencionistas y más respetuosas con la fisiología del parto. No busca mejorar la infraestructura hospitalaria o tecnológica. Reducir prácticas sin evidencia es un medio para alcanzar ese objetivo, no su finalidad principal, y la guía no propone que el parto sea atendido exclusivamente por obstetras, ya que reconoce el papel de las matronas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cfb") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal promueve la participación activa de la mujer en su propio parto, mediante información, respeto a sus preferencias y plan de parto, porque mejora su experiencia y su satisfacción y respeta su autonomía. No pretende impedir que los profesionales tomen decisiones clínicas, sino que estas se compartan. El objetivo no es reducir costes, y aunque la guía aborda el manejo de la tercera etapa del parto, la participación de la mujer no se plantea para disminuir el uso de oxitocina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cfc") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal se elaboró en el marco del programa de Guías de Práctica Clínica del Plan de Calidad para el SNS, con financiación procedente del Ministerio de Sanidad canalizada a través del Instituto de Salud Carlos III, en colaboración con la agencia de evaluación OSTEBA. Ni el Banco Mundial ni la Organización Mundial de la Salud financiaron su elaboración, aunque la OMS sea un referente en recomendaciones sobre el parto. La «Fundación para la Innovación Clínica» no figura entre las entidades financiadoras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d02") }, {"long_answer": "La guía señala que el impulso al uso de Guías de Práctica Clínica en el SNS se remonta a 2003 con el proyecto GuíaSalud, organismo del Consejo Interterritorial que actúa como catálogo y centro de referencia para la elaboración, difusión y uso de guías en España. La publicación de la guía de parto normal en 2010 es un resultado de ese programa, no su inicio. Las fechas de 1990 y 2015 no corresponden al origen de este proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d04") }, {"long_answer": "Tras la implantación de la Guía de Práctica Clínica sobre la atención al parto normal se espera una mejora de la atención en los servicios obstétricos, con prácticas basadas en la evidencia y una mayor participación activa de la mujer en las decisiones sobre su parto. No persigue exclusivamente reducir costes y personal, sino mejorar la calidad asistencial. No se busca automatizar el parto, y la guía desaconseja precisamente las intervenciones rutinarias sin indicación, por lo que no espera un incremento de intervenciones quirúrgicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d09") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal recomienda el uso del partograma, preferiblemente con líneas de alerta y acción, como herramienta para registrar de forma gráfica la evolución del trabajo de parto, incluyendo la dilatación, el descenso de la presentación, la dinámica uterina y el estado materno y fetal. El algoritmo sobre la prolongación de la primera etapa orienta decisiones, pero no es un instrumento de registro. El registro bibliográfico identifica la publicación, y el glosario define términos, por lo que ninguno sirve para seguir el parto.", "question": "¿Qué herramienta recomienda la Guía para el registro gráfico de la evolución del trabajo de parto?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0b") }, {"long_answer": "Las Guías de Práctica Clínica no sustituyen el juicio clínico porque cada paciente y cada situación son únicos, y el profesional debe adaptar las recomendaciones a las circunstancias, valores y preferencias de la mujer, pudiendo decidir de forma individualizada. Las guías son herramientas de ayuda a la decisión basadas en la evidencia, no normas de obligado cumplimiento sin excepciones ni documentos con carácter legal vinculante. Tampoco es cierto que los profesionales solo estén capacitados para decidir según las guías, ya que su formación y experiencia son esenciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0d") }, {"long_answer": "La inclusión de la asociación «El parto es nuestro» en el grupo de trabajo de la Guía de Práctica Clínica sobre la atención al parto normal incorpora la perspectiva de las usuarias, centrada en sus derechos, su bienestar y su experiencia del parto, lo que favorece recomendaciones más respetuosas y centradas en la mujer. No implica una visión de medicalización total, sino lo contrario. Tampoco supone la exclusión de los métodos farmacológicos de analgesia ni la limitación de la tecnología, que la guía contempla cuando están indicados y la mujer los elige."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0f") }, {"long_answer": "La versión resumida de la Guía de Práctica Clínica sobre la atención al parto normal es un documento editado para facilitar la difusión de las recomendaciones y la formación de los profesionales del SNS que atienden el parto, de forma que su aplicación en la práctica resulte más sencilla. No es una monografía dirigida solo a matronas, ya que está destinada a todos los profesionales implicados. Tampoco es un informe técnico para la industria farmacéutica ni un manual de procedimientos de urgencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d13") }, {"long_answer": "La higiene de manos debe realizarse antes y después de la extracción de cada pareja de hemocultivos, también cuando se obtienen varias del mismo paciente, porque cada extracción es un procedimiento aséptico independiente y la contaminación de las manos o de los guantes es una causa frecuente de falsos positivos. No basta con hacerla antes de la primera extracción. El uso de guantes no sustituye la higiene de manos, que no depende de que los guantes se contaminen visiblemente, y la recomendación se aplica sea cual sea la vía de extracción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d19") }, {"long_answer": "Se recomienda obtener los hemocultivos mediante venopunción periférica en dos sitios anatómicos distintos, porque las muestras extraídas a través de catéteres ya insertados tienen más riesgo de contaminación. Solo se extraen de un catéter venoso central cuando se sospecha bacteriemia asociada a él, y en ese caso deben acompañarse de hemocultivos periféricos simultáneos para comparar los resultados. No está prohibido extraer de catéteres centrales, ni hacerlo depende de que el catéter tenga una única luz. Desechar sistemáticamente el primer volumen no es la recomendación clave en este contexto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d28") }, {"long_answer": "Cuando se inoculan hemocultivos con un sistema de vacío y palomilla, se debe llenar primero el frasco aerobio, porque el aire contenido en el tubo de la palomilla pasa al primer frasco y, si fuera el anaerobio, comprometería el crecimiento de bacterias anaerobias. Por ello el orden no es indiferente y no debe empezarse por el frasco anaerobio. Los sistemas de vacío están aceptados y son útiles, ya que reducen la manipulación y el riesgo de pinchazo accidental.", "option_3": "Da igual el orden"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2b") }, {"long_answer": "La extracción de hemocultivos aprovechando la canalización de una vía periférica solo se acepta cuando el catéter acaba de insertarse con técnica aséptica y no existe otra alternativa, como en pacientes con accesos venosos difíciles, ya que la venopunción directa sigue siendo la técnica de elección por su menor tasa de contaminación. Por tanto no está prohibido en todos los casos, pero tampoco debe hacerse siempre por comodidad del paciente o del profesional. Esta posibilidad no se limita a los pacientes pediátricos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2e") }, {"long_answer": "Un registro enfermero correcto tras la extracción de hemocultivos debe permitir identificar sin ambigüedad cada muestra y su contexto: nombre completo del paciente, número de historia clínica, fecha, hora de extracción y número de secuencia de la muestra (primer, segundo set...). Estos datos garantizan la trazabilidad, evitan errores de identificación y permiten al laboratorio interpretar si un microorganismo aparece en una o varias tandas, lo que ayuda a distinguir bacteriemia real de contaminación. Registrar solo nombre e historia es insuficiente, el médico solicitante no sustituye a la hora y la secuencia, y el antibiótico es relevante pero no basta por sí solo para identificar la muestra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d35") }, {"long_answer": "Galicia es la comunidad con mayor exposición al radón residencial en España por su sustrato geológico, dominado por rocas graníticas ricas en uranio. Los estudios de medición en viviendas muestran que una proporción elevada de hogares gallegos supera los niveles de referencia, por lo que se considera zona de riesgo alto y concentra buena parte de los municipios de actuación prioritaria. Cantabria, Cataluña y Madrid tienen áreas con concentraciones moderadas o puntualmente elevadas (por ejemplo, la sierra madrileña), pero no alcanzan globalmente el porcentaje de viviendas con niveles altos que caracteriza a Galicia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d37") }, {"long_answer": "El radón-222 procede de la cadena de desintegración del uranio-238 presente en el terreno. La principal fuente de radón en el interior de los edificios es el suelo y las rocas subyacentes, especialmente granitos y otras rocas ricas en uranio, desde donde el gas asciende y penetra por grietas, juntas, conducciones y soleras por diferencias de presión. Los materiales de construcción contribuyen, pero en una proporción pequeña. Las aguas residuales urbanas no son una fuente relevante y la radiación cósmica es un componente distinto de la radiación natural que no genera radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3a") }, {"long_answer": "Según el Plan Nacional contra el Radón y la normativa de protección radiológica, el Consejo de Seguridad Nuclear (CSN), como organismo competente en seguridad nuclear y protección radiológica, es quien elabora el mapa de potencial de radón y, a partir de él, el listado de términos municipales de actuación prioritaria, es decir, aquellos en los que una proporción significativa de edificios puede superar el nivel de referencia. El Ministerio de Sanidad participa en el plan desde la vertiente de salud, el CSIC es un organismo investigador y el IGME aporta información geológica, pero ninguno es el responsable de publicar dicho listado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3c") }, {"long_answer": "El daño pulmonar atribuido al radón se debe sobre todo a sus descendientes de vida corta: polonio-218, plomo-214, bismuto-214 y polonio-214. Son partículas sólidas que se adhieren al aerosol ambiental, se depositan en el epitelio bronquial al respirar y emiten radiación alfa (Po-218 y Po-214) a muy corta distancia de las células basales, produciendo lesiones en el ADN. El uranio-238 y el radio-226 son precursores del radón en la cadena de desintegración, no sus descendientes. El 'torón-230' no existe como tal y neutrones y protones no son productos de desintegración del radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3d") }, {"long_answer": "La OMS estima que entre el 3% y el 14% de los cánceres de pulmón en el mundo son atribuibles a la exposición al radón en las viviendas, dependiendo de la concentración media de radón de cada país y de la prevalencia de tabaquismo. Esto convierte al radón en la segunda causa de cáncer de pulmón tras el tabaco y la primera en personas que nunca han fumado. Un 2-5% infraestima la carga en países con niveles altos, mientras que 15-20% o más del 25% sobrestiman las cifras recogidas por la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3f") }, {"long_answer": "Para que una medición de radón en el lugar de trabajo sea representativa de la concentración media anual, el protocolo establece medir durante al menos 3 meses y preferentemente fuera de la época estival. En verano las ventanas permanecen más abiertas y la diferencia de temperatura entre interior y exterior es menor, por lo que la entrada de radón disminuye y se infravaloraría la exposición. Un mes en verano o una semana son periodos demasiado cortos y sensibles a las variaciones diarias y estacionales. Cuatro meses continuos sería válido, pero no es la duración mínima que define el protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d41") }, {"long_answer": "El Plan Nacional contra el Radón establece que sus actuaciones deben evaluarse de forma periódica y que el plan se revise y actualice cada 5 años, de modo que pueda incorporar nuevos datos de medición, avances en el conocimiento científico y cambios normativos derivados de la Directiva 2013/59/Euratom. Un periodo de 3 años resulta demasiado corto para valorar el impacto de medidas como la mejora de edificios o la vigilancia de trabajadores, mientras que 7 o 10 años retrasarían en exceso la corrección de las estrategias que no estén funcionando."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d45") }, {"long_answer": "Los estudios caso-control realizados en España, especialmente en Galicia, han mostrado que en personas que nunca han fumado el riesgo de cáncer de pulmón aumenta de forma significativa con concentraciones de radón residencial superiores a 200 Bq/m³ en comparación con los expuestos a menos de 100 Bq/m³. Este hallazgo refuerza la importancia del radón como primera causa de cáncer de pulmón en no fumadores. Aunque el riesgo es lineal y sin umbral, por debajo de 100 o 50 Bq/m³ no se alcanzaba significación estadística, y fijar el corte en 300 Bq/m³ ignoraría el exceso de riesgo ya demostrado a niveles inferiores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d46") }, {"long_answer": "El consumo de tabaco es el principal factor extrínseco que potencia el efecto del radón sobre el cáncer de pulmón. Ambos agentes interactúan de forma sinérgica, más que aditiva: a igual concentración de radón, el riesgo absoluto de morir por cáncer de pulmón es muy superior en fumadores que en no fumadores. Por eso las estrategias preventivas insisten en la cesación tabáquica en personas expuestas. La edad avanzada y el sexo masculino son características propias del individuo, no factores extrínsecos modificables, y el tipo de vivienda influye en la concentración de radón, pero no es el factor que multiplica la mortalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d47") }, {"long_answer": "El mapa del potencial de radón de España ha sido elaborado y coordinado por el Consejo de Seguridad Nuclear (CSN), organismo independiente competente en protección radiológica, con la colaboración de universidades y otros centros. Este mapa clasifica el territorio según la probabilidad de que los edificios superen el nivel de referencia y es la base para definir los municipios de actuación prioritaria. El Ministerio para la Transición Ecológica tiene competencias en energía y medio ambiente, el IGME aporta información geológica y el CIEMAT es un centro de investigación, pero ninguno de ellos coordina el mapa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d57") }, {"long_answer": "El plan de ampliación de la cartera de salud bucodental establece que los fondos se repartan entre las comunidades autónomas según el número de personas que integran los colectivos priorizados en cada territorio (población infantojuvenil, embarazadas, personas con discapacidad o con determinadas patologías) y una ponderación del gasto por persona de las prestaciones a incluir. Así, la financiación se ajusta a la necesidad real de cada comunidad. Repartir según la población total, el número de dentistas o el presupuesto histórico no reflejaría el volumen de población diana ni el coste de los servicios que deben implantarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5a") }, {"long_answer": "En la asistencia bucodental infantil las comunidades autónomas españolas utilizan mayoritariamente un modelo mixto, que combina la atención en unidades de salud bucodental públicas de atención primaria con la provisión a través de dentistas privados concertados, como ocurre en los programas tipo PADI financiados por capitación. Este modelo permite ampliar la cobertura aprovechando la red privada. Hay comunidades con modelo exclusivamente público, pero no son mayoría; ninguna utiliza un modelo exclusivamente privado sin financiación pública, y la atención domiciliaria no es la forma de provisión de la salud bucodental infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5b") }, {"long_answer": "La encuesta realizada en el SNS sobre las prestaciones bucodentales mostró que la exploración preventiva de la cavidad oral en mujeres embarazadas se ofrece en todas las comunidades autónomas excepto en una. Es la prestación más extendida porque permite detectar caries y enfermedad periodontal, que se agravan durante la gestación, y dar consejo sobre higiene oral. La aplicación de flúor tópico y las tartrectomías tienen una implantación menos homogénea, y los tratamientos pulpares no forman parte de la cartera habitual para embarazadas en la mayoría de comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5c") }, {"long_answer": "Según los datos de la OCDE recogidos en el plan, en 2017 alrededor del 6,7% del gasto sanitario privado en España se destinaba a atención bucodental. Esta cifra refleja que la salud dental se financia en gran parte de forma privada por las familias, ya que la cartera pública es limitada en adultos, y justifica la necesidad de ampliar la cobertura del SNS para reducir las desigualdades en el acceso. Los valores de 2,5%, 10% o 15% no corresponden a los datos de la OCDE citados en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5d") }, {"long_answer": "Según los datos del INE de 2019 recogidos en el plan, Extremadura es la comunidad autónoma con menor gasto sanitario privado por persona en servicios dentales. Este dato se relaciona con un menor nivel de renta y pone de manifiesto que, cuando la atención dental depende del bolsillo del paciente, el acceso se ve condicionado por la situación socioeconómica, lo que genera desigualdades territoriales. Madrid se sitúa entre las comunidades con mayor gasto por persona, y Cantabria y Canarias no presentan el valor más bajo de la serie."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d60") }, {"long_answer": "La propuesta de ampliación de la cartera común del SNS para mujeres embarazadas incluye información y consejos sobre salud oral, tanto propia como para preservar la salud oral del bebé, exploración clínica de la cavidad oral, tartrectomía (eliminación del sarro) cuando esté indicada y aplicación de sustancias remineralizantes o antisépticas. Son actuaciones preventivas y de bajo riesgo, adecuadas al aumento de la gingivitis y de la caries durante la gestación. La ortodoncia, la cirugía compleja, los implantes y las prótesis quedan fuera de la cartera, y los tratamientos pulpares en dentición temporal corresponden a la población infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d64") }, {"long_answer": "El plan de ampliación de la cartera de salud bucodental fija un plazo máximo de 3 años, a contar desde la transferencia de fondos, para que las comunidades autónomas implanten de forma efectiva las nuevas prestaciones en los colectivos priorizados. Este plazo permite adaptar los recursos humanos, los equipamientos y los convenios necesarios. Seis meses o un año serían insuficientes para desplegar los servicios en todo el territorio, y cinco años excede el horizonte previsto en el plan para la ejecución de los fondos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d67") }, {"long_answer": "La cartera común de servicios de salud bucodental del SNS excluye expresamente los implantes dentarios y las prótesis dentales, salvo los casos contemplados en la cartera de prestación ortoprotésica (por ejemplo, pacientes con malformaciones congénitas o procesos oncológicos que afectan a la cavidad oral). Esta exclusión explica buena parte del elevado gasto privado en salud dental. Las exodoncias, incluidas las quirúrgicas, sí forman parte de la cartera; la aplicación de flúor tópico en población infantil es una prestación preventiva incluida, y los tratamientos pulpares en dentición definitiva están incluidos en la población infantojuvenil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d68") }, {"long_answer": "La OMS y el plan nacional señalan que las enfermedades bucodentales comparten factores de riesgo modificables con otras enfermedades no transmisibles, principalmente la ingesta elevada de azúcares libres, el consumo de tabaco y el consumo nocivo de alcohol. Por ello recomiendan abordarlos de forma integrada con las estrategias de prevención de cáncer, diabetes o enfermedad cardiovascular. Las grasas saturadas y el estrés, el café o la deficiencia vitamínica no se consideran los factores de riesgo principales de la caries y la enfermedad periodontal, y la higiene es una medida de prevención más que el factor común destacado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6b") }, {"long_answer": "En la priorización de la ampliación de la cartera bucodental, las mujeres embarazadas constituyen el primer colectivo que recibe prestaciones preventivas, diagnósticas y terapéuticas similares a las de la población infantojuvenil. Se priorizan porque los cambios hormonales del embarazo favorecen la gingivitis y la caries, y porque la salud oral materna influye en la del recién nacido. Las personas con discapacidad o con determinadas enfermedades son colectivos incluidos en fases o líneas posteriores, y la población general adulta no se prioriza en esta ampliación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6e") }, {"long_answer": "El análisis comparativo europeo muestra que, en la mayoría de los países, la atención dental se financia predominantemente mediante gasto privado directo de los pacientes, a diferencia de otras áreas de la asistencia sanitaria con cobertura pública amplia. La financiación pública suele concentrarse en la población infantil y en colectivos vulnerables. La cobertura pública universal completa es la excepción, los seguros voluntarios complementan pero no financian de forma exclusiva la atención, y las donaciones no son una fuente relevante de financiación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d76") }, {"long_answer": "El análisis conjunto (pooling) de los estudios caso-control europeos, liderado por Darby, demostró que el riesgo de cáncer de pulmón aumenta aproximadamente un 16% por cada 100 Bq/m³ de incremento en la concentración de radón residencial, con una relación lineal y sin umbral. Esta cifra se corrige al 8% si no se ajusta por la incertidumbre de las mediciones, pero el valor de referencia citado es el 16%. Los porcentajes del 30% o del 50% sobreestiman el efecto y el 5% lo infravalora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d78") }, {"long_answer": "Galicia es la comunidad autónoma española con mayor proporción de viviendas que superan los 300 Bq/m³ de radón, debido a su predominio de rocas graníticas ricas en uranio. Por eso concentra una gran parte de los municipios de actuación prioritaria y es donde se han realizado los principales estudios sobre radón y cáncer de pulmón en España. Madrid (zona de la sierra), Extremadura y Castilla y León tienen áreas con niveles elevados, pero globalmente su porcentaje de viviendas por encima de 300 Bq/m³ es inferior al gallego."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7a") }, {"long_answer": "La Directiva 2013/59/Euratom, transpuesta en España, establece un nivel de referencia de 300 Bq/m³ en los lugares de trabajo. Si se supera, el empleador debe adoptar medidas para reducir la concentración de radón o la exposición (mejorar la ventilación, sellar vías de entrada, reorganizar tiempos de permanencia) y repetir las mediciones para comprobar su eficacia; si pese a ello persiste, la situación se gestiona como exposición planificada con control de dosis. No se exige suspender la actividad, la protección respiratoria individual no es la medida de elección y no existe un umbral de actuación de 500 Bq/m³."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d83") }, {"long_answer": "Los descendientes del radón emiten partículas alfa, que tienen una alta transferencia lineal de energía (LET): depositan mucha energía en un recorrido muy corto, de unas pocas decenas de micras, justo en las células del epitelio bronquial. Esto les confiere una alta eficacia biológica relativa, con roturas dobles del ADN difíciles de reparar. La radiación alfa tiene muy escasa capacidad de penetración, por lo que no alcanza el tejido muscular y su recorrido es corto, no largo. Además es radiación ionizante, no no ionizante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d86") }, {"long_answer": "Una de las principales limitaciones de los estudios en mineros es la coexposición a otros agentes carcinógenos del ambiente de trabajo, como el polvo de sílice, el arsénico, los humos diésel y la radiación gamma, que dificulta atribuir el exceso de cáncer de pulmón exclusivamente al radón. Además, sus exposiciones eran muy superiores a las residenciales y la información sobre el tabaco era a menudo incompleta. Las cohortes de mineros no tienen tamaños excesivos, el tabaquismo en ellas solía ser alto y existe consenso científico sobre la presencia y la carcinogenicidad del radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d87") }, {"long_answer": "El Plan Nacional contra el Radón organiza sus actuaciones en cinco ejes estratégicos, que abarcan, entre otros, el conocimiento de la exposición, la protección en viviendas y edificios, la protección de los trabajadores, la comunicación y sensibilización de la población y la coordinación entre administraciones. Esta estructura permite abordar el radón como un riesgo para la salud pública de forma integral. Tres, siete o diez ejes no corresponden a la organización recogida en el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d88") }, {"long_answer": "Los expertos franceses proponen identificar como trabajadores de alto riesgo, candidatos a cribado de cáncer de pulmón, a personas de 55 a 74 años con exposición laboral al radón durante al menos 10 años y un consumo acumulado de tabaco de 30 o más paquetes-año. Estos criterios combinan edad, tabaquismo y exposición, porque el riesgo absoluto se concentra en fumadores expuestos de mayor edad, en los que el cribado con TC de baja dosis tiene un balance beneficio-riesgo favorable. Incluir a todos los trabajadores, a menores de 50 años o a exposiciones inferiores a un año no se ajusta a esta recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d93") }, {"long_answer": "En el estudio español con más de 3.000 mediciones en lugares de trabajo, aproximadamente un 10% de los puestos del sector turístico presentaban concentraciones de radón superiores al nivel de referencia de 300 Bq/m³. Este dato pone de relieve que el radón no es solo un problema de minas o cuevas, sino también de establecimientos abiertos al público situados en zonas de alto potencial, y justifica medir en estos centros. Los porcentajes del 22% o del 37% sobrestiman la proporción observada en ese sector y el 5% la infravalora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da0") }, {"long_answer": "Durante la desfibrilación de doble secuencia se aplican dos descargas casi simultáneas, por lo que el procedimiento insiste en la seguridad eléctrica: el paciente no debe estar sobre superficies metálicas no aisladas ni en contacto con agua o humedad, que podrían conducir la corriente hacia los reanimadores o desviar la energía. Colocar al paciente de pie es inviable en una parada cardiaca, el colchón de agua aumentaría el riesgo eléctrico y la RCP se realiza con el paciente en decúbito supino sobre superficie firme, no en decúbito lateral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da3") }, {"long_answer": "En la técnica de doble secuencia es imprescindible un buen contacto de los parches con la piel, ya que se utilizan cuatro electrodos y la impedancia influye en la energía que llega al miocardio. Por eso se emplea la rasuradora para eliminar el vello en las zonas de colocación, lo que mejora la adherencia y la conductividad. El alcohol puede reducir la adhesión y es inflamable, la cinta adhesiva no mejora la conducción y los parches autoadhesivos ya llevan gel conductor incorporado, por lo que no se añade gel ECG adicional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977daa") }, {"long_answer": "Según el protocolo, la desfibrilación de doble secuencia se plantea en la parada cardiaca con ritmo desfibrilable (fibrilación ventricular o taquicardia ventricular sin pulso) que persiste tras tres desfibrilaciones estándar, es decir, en la fibrilación ventricular refractaria. En ese caso se prepara un segundo desfibrilador para modificar el vector de la descarga. El fallo de la ventilación avanzada o la dificultad para administrar fármacos no son criterios de indicación, y una parada sin ritmo analizado no permite saber si existe un ritmo desfibrilable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dad") }, {"long_answer": "Para que la doble secuencia sea segura y eficaz, el protocolo indica que una misma persona maneje los dos monitores desfibriladores y anuncie en voz alta cada descarga. Así se consigue la secuencia correcta, con las dos descargas lo más próximas posible en el tiempo, y se evita que alguien esté en contacto con el paciente. Que dos operadores distintos disparen cada monitor aumenta el riesgo de descoordinación. Separar RCP y desfibrilación es la organización habitual del equipo, pero no lo que define la coordinación de la DDS, y un solo monitor no permite esta técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dae") }, {"long_answer": "La característica que define la desfibrilación de doble secuencia es el uso de dos desfibriladores con dos juegos de electrodos, colocados habitualmente en posición anterolateral y anteroposterior, que descargan de forma secuencial y muy próxima en el tiempo. Así se despolariza una mayor masa miocárdica desde dos vectores distintos. No se emplea menos energía, sino la máxima en cada equipo; los electrodos no se colocan solo en la línea media anterior y puede realizarse con desfibriladores manuales o en modo manual, pero ese no es el rasgo que la diferencia de la técnica estándar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db9") }, {"long_answer": "Las recomendaciones de nirsevimab establecen una dosis en función del peso para los lactantes en su primera temporada de VRS: 50 mg por vía intramuscular en una única inyección si pesan menos de 5 kg y 100 mg si pesan 5 kg o más. Un lactante de 4,5 kg debe recibir por tanto 50 mg en dosis única. La dosis de 100 mg se administra en una sola inyección y se reserva para los de 5 kg o más, por lo que nunca se divide en dos. La de 200 mg, en dos inyecciones de 100 mg, corresponde a los niños vulnerables de 10 kg o más en su segunda temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dbc") }, {"long_answer": "Los estudios de efectividad realizados en España tras la primera campaña de inmunización con nirsevimab (temporada 2023-2024) mostraron una reducción del riesgo de hospitalización por VRS de entre el 81% y el 84% en los lactantes que recibieron el anticuerpo frente a los no inmunizados. La lactancia materna es protectora frente a infecciones respiratorias, pero no se asoció a esa reducción concreta. La vacuna antigripal no protege frente al VRS y la profilaxis antibiótica no tiene ningún papel en la prevención de una infección vírica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc1") }, {"long_answer": "El asma leve no figura entre las condiciones de alto riesgo para enfermedad grave por VRS en las que se recomienda nirsevimab hasta los 24 meses. Las recomendaciones incluyen, entre otras, la cardiopatía congénita con repercusión hemodinámica significativa, la displasia broncopulmonar, la fibrosis quística, la inmunodepresión grave, determinados errores congénitos del metabolismo, enfermedades neuromusculares, síndrome de Down, cuidados paliativos o enfermedad pulmonar grave. Displasia broncopulmonar, fibrosis quística e inmunodepresión grave son, por tanto, indicaciones reconocidas, mientras que el asma leve no implica un riesgo comparable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc4") }, {"long_answer": "Para la temporada 2024-2025 se recomendó iniciar la campaña de inmunización con nirsevimab a principios de octubre de 2024 (en general a partir del 1 de octubre), de forma que los lactantes estén protegidos antes del aumento de la circulación del VRS, que en España suele producirse entre noviembre y febrero. Los nacidos durante la temporada se inmunizan precozmente, preferiblemente en las primeras 24-48 horas. Abril de 2024 es previo a la temporada, y enero o marzo de 2025 serían demasiado tardíos, cuando ya ha pasado el pico epidémico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc6") }, {"long_answer": "El registro de cada dosis de nirsevimab en el sistema de información de vacunaciones de la comunidad autónoma tiene varias funciones: garantizar la continuidad asistencial, ya que cualquier profesional puede comprobar si el lactante está inmunizado, evitar dobles administraciones y permitir evaluar la cobertura, la efectividad y el impacto del programa. No es un mero dato estadístico ni opcional, puesto que de él depende la seguridad del niño y la evaluación de la campaña, y no tiene relación con autorizar la prescripción ni la venta privada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dca") }, {"long_answer": "Tras la amplia utilización de nirsevimab en la temporada 2023-2024, la farmacovigilancia no identificó señales de seguridad ni nuevos riesgos respecto a lo conocido en los ensayos clínicos. Las reacciones notificadas fueron en general leves, como dolor o reacción local en el punto de inyección, fiebre o exantema. Por ello se mantiene la recomendación de uso. No se ha detectado un riesgo elevado de reacciones graves ni existe contraindicación derivada de eventos adversos, y su uso no se limita a ensayos clínicos, pues se ha administrado de forma sistemática en el calendario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dcc") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal frente a la proteína F del VRS que incorpora una modificación en su fragmento Fc que le confiere una vida media prolongada. Gracias a ello, una única dosis intramuscular protege durante al menos cinco meses, lo que cubre toda la temporada de VRS. Por eso no requiere dosis repetidas, a diferencia del palivizumab, que se administraba mensualmente. No se administra por vía oral, ya que es una proteína que se degradaría en el tubo digestivo, y está indicado en lactantes y niños pequeños, no en adultos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dcd") }, {"long_answer": "La edad cronológica es el tiempo transcurrido desde el nacimiento, sin aplicar ninguna corrección por la edad gestacional. Es la referencia que utilizan las recomendaciones de nirsevimab para definir la población diana, por ejemplo los menores de 6 meses o los niños de alto riesgo hasta los 24 meses al inicio de la temporada, también en los prematuros. La edad corregida es la que se calcula restando las semanas de prematuridad hasta las 40 semanas, la edad gestacional se refiere al tiempo de embarazo en el parto y la edad desde el ingreso no es un concepto utilizado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dcf") }, {"long_answer": "Los lactantes nacidos fuera de la temporada de VRS (entre abril y septiembre) que forman parte de la población diana deben inmunizarse con nirsevimab al inicio de la siguiente temporada, idealmente en octubre, antes de que aumente la circulación del virus. Así se aprovecha su vida media prolongada para cubrir el periodo de mayor riesgo. No vacunarlos los dejaría desprotegidos en su primera temporada, la inmunización es preventiva y no se espera a que haya síntomas, y a los 12 meses la mayoría ya no pertenecen a la población diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd0") }, {"question": "¿Qué dosis de nirsevimab deben registrarse en los sistemas de información de vacunaciones autonómicos?", "option_2": "Solo las administradas en atención primaria", "long_answer": "Todas las dosis de nirsevimab administradas deben registrarse en el sistema de información de vacunaciones de la comunidad autónoma, tanto las de atención primaria como las administradas en el hospital, por ejemplo en las maternidades a los recién nacidos durante la temporada. Esto permite conocer el estado de inmunización de cada niño, evitar duplicidades y calcular coberturas reales. Registrar solo las dosis de prematuros o de un tipo concreto dejaría fuera a gran parte de los lactantes inmunizados, y no registrar las dosis impediría la evaluación del programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd1") }, {"question": "En un lactante en su primera temporada de VRS sometido a cirugía cardíaca con bypass cardiopulmonar, ¿qué dosis adicional de nirsevimab se recomienda si han pasado más de 90 días desde la primera dosis?", "long_answer": "En los lactantes sometidos a cirugía cardiaca con bypass cardiopulmonar se elimina parte del anticuerpo circulante, por lo que se recomienda una dosis adicional de nirsevimab en cuanto el paciente esté estable. Si en la primera temporada han pasado más de 90 días desde la dosis inicial, la dosis adicional es una dosis única de 50 mg, independientemente del peso. Si han pasado 90 días o menos, se ajusta al peso: 50 mg si pesa menos de 5 kg, 100 mg si pesa 5 kg o más y 200 mg si pesa 10 kg o más. La dosis de 100 mg con independencia del peso corresponde a la segunda temporada pasados 90 días. No administrar dosis adicional dejaría al niño con niveles insuficientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd2") }, {"long_answer": "Las cardiopatías congénitas con afectación hemodinámica significativa son una de las condiciones de alto riesgo de enfermedad grave por VRS en las que se recomienda nirsevimab, incluida la segunda temporada hasta los 24 meses. En estos niños la infección puede descompensar la función cardiorrespiratoria y causar hospitalización prolongada o ingreso en UCI. El asma ocasional sin hospitalización, las infecciones respiratorias leves recurrentes y la dermatitis atópica no se consideran condiciones de alto riesgo en las recomendaciones, por lo que no justifican la administración del anticuerpo fuera de la población general diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd6") }, {"long_answer": "El artículo 7 de la Ley 44/2003, de Ordenación de las Profesiones Sanitarias, atribuye a las enfermeras la dirección, evaluación y prestación de los cuidados de enfermería orientados a la promoción, mantenimiento y recuperación de la salud, así como a la prevención de enfermedades y discapacidades. Esta definición reconoce la autonomía profesional en el ámbito de los cuidados. La administración de medicamentos sujetos a prescripción requiere la correspondiente orden o el marco de la indicación enfermera, la gestión de recursos humanos no es exclusiva de la enfermera y la planificación de las políticas nacionales corresponde a las administraciones públicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd7") }, {"long_answer": "El Real Decreto 546/1995, que establece el título de Técnico en Cuidados Auxiliares de Enfermería, define como su competencia general proporcionar cuidados auxiliares al paciente y actuar sobre las condiciones sanitarias de su entorno como miembro de un equipo de enfermería, bajo la dependencia del diplomado en enfermería. Las TCAE no toman decisiones clínicas autónomas sobre prevención, no realizan diagnósticos médicos ni enfermeros y no tienen capacidad para prescribir tratamientos, funciones que corresponden a otros profesionales con titulación universitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dda") }, {"long_answer": "El Marco Estratégico subraya que la dotación de enfermeras debe calcularse teniendo en cuenta la complejidad de los pacientes y sus necesidades reales de cuidados, no solo el número de camas o de habitantes. Las plantillas ajustadas a la carga de trabajo se asocian a menor mortalidad, menos eventos adversos y mayor calidad asistencial. Un aumento indiscriminado sin planificación no garantiza que los recursos se ubiquen donde se necesitan, las ratios por habitante no reflejan la complejidad asistencial y concentrar recursos en el hospital descuidaría la atención primaria y comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de0") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería atribuye al Comité de Cuidados en Salud, órgano colegiado del Ministerio de Sanidad, la responsabilidad de elaborar, hacer el seguimiento, evaluar e impulsar la implementación del Marco en coordinación con las comunidades autónomas, que son las que gestionan los servicios de salud. Es, por tanto, un órgano de gobernanza de las políticas de cuidados. No se limita a la formación de enfermeras en zonas rurales ni a supervisar tareas administrativas de las TCAE, y la contratación y formación de médicos especialistas queda fuera de su ámbito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de3") }, {"long_answer": "El análisis demográfico y epidemiológico del Marco Estratégico identifica como uno de los grandes retos el envejecimiento progresivo de la población, unido al predominio de las enfermedades crónicas no transmisibles, la multimorbilidad y la dependencia. Esto incrementa la demanda de cuidados de larga duración y exige reforzar la atención primaria, comunitaria y sociosanitaria. Las enfermedades transmisibles siguen siendo relevantes, pero no son el reto exclusivo; la esperanza de vida en España es de las más altas del mundo y la natalidad está en descenso, no en aumento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de4") }, {"long_answer": "Según la encuesta sobre la situación laboral de las enfermeras recogida en el Marco Estratégico, alrededor del 39,4% se plantea abandonar la profesión en los próximos 10 años. Esta cifra refleja el impacto de la sobrecarga, la precariedad contractual, las dificultades de conciliación y el escaso reconocimiento, y justifica las líneas de retención y fidelización del talento del Marco. Un 10% infravalora el problema, y el 70% o el 80% no corresponden al dato publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de8") }, {"long_answer": "Para fomentar que la evidencia generada por la investigación en cuidados se traslade a la práctica clínica y a las políticas sanitarias, el Marco prevé crear un observatorio de investigación en cuidados en colaboración con la Acción Estratégica en Salud, el instrumento de financiación de la investigación biomédica del Estado. Así se pretende visibilizar, coordinar y priorizar la investigación enfermera. Eliminar las estructuras existentes iría en contra de este objetivo, limitarse a estudios internacionales impediría generar evidencia del propio contexto y la investigación en cuidados no se reduce a la farmacología."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977deb") }, {"long_answer": "La estrategia estatal de cuidados impulsa un modelo de desinstitucionalización, centrado en la persona, que prioriza que las personas con dependencia puedan vivir en su domicilio y en su comunidad con los apoyos necesarios (servicios de proximidad, ayuda a domicilio, viviendas con apoyos) frente a la atención en grandes instituciones. Este enfoque respeta la autonomía y los derechos de las personas. Aumentar la institucionalización o centralizar los cuidados en hospitales generales va en sentido contrario, y eliminar los cuidados formales trasladaría toda la carga a las cuidadoras familiares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ded") }, {"long_answer": "El Marco Español de Cualificaciones para el Aprendizaje Permanente (MECU) es una estructura que ordena las cualificaciones por niveles de aprendizaje y permite compararlas con el Marco Europeo de Cualificaciones. En el ámbito de los cuidados sirve para alinear la formación con las competencias de los profesionales, ordenando de forma coherente los distintos niveles formativos. No es un sistema educativo independiente de la formación profesional, sino que la integra; tampoco es un protocolo de administración de medicamentos ni un reglamento de contratación de personal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df0") }, {"long_answer": "El Marco Estratégico reconoce a las Técnicas en Cuidados Auxiliares de Enfermería como parte esencial del equipo de cuidados en el SNS y en el sector sociosanitario, donde, junto con las enfermeras, contribuyen a la continuidad y longitudinalidad de los cuidados en ámbitos como la hospitalización, la atención primaria, las residencias o el domicilio. Sus funciones no se limitan a la hospitalización quirúrgica, no realizan diagnósticos y su papel es asistencial, no meramente administrativo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df6") }, {"long_answer": "En la clasificación FIGO 2018 del cáncer de cuello uterino, el estadio IB3 (T1b3 N0 M0) corresponde a un carcinoma invasor limitado al cuello uterino con un diámetro tumoral mayor de 4 cm. El estadio IB se divide según el tamaño: IB1 hasta 2 cm, IB2 de más de 2 hasta 4 cm e IB3 de más de 4 cm. La invasión parametrial sin llegar a la pared pélvica define el estadio IIB, la extensión a la mucosa vesical o rectal el IVA, y la invasión de 5 mm o menos diagnosticada microscópicamente el estadio IA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df9") }, {"long_answer": "En la biopsia selectiva del ganglio centinela en cáncer de cuello uterino, la guía recomienda preferentemente el verde de indocianina (ICG), detectado mediante fluorescencia con luz infrarroja, porque ofrece mayores tasas de detección global y bilateral que los colorantes azules y una técnica sencilla. El azul de metileno aislado presenta una tasa de detección inferior. El radiotrazador con tecnecio-99m es una alternativa válida, sobre todo combinado con azul, pero no es el de elección preferente. El rojo fenol no se utiliza como trazador ganglionar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dfc") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado con ganglios pélvicos positivos, el tratamiento de elección es la radioquimioterapia concomitante, con radioterapia externa y cisplatino semanal, seguida de braquiterapia guiada por imagen. Esta combinación consigue los mejores resultados de control local y supervivencia. La cirugía radical seguida de quimioterapia no es el estándar en este escenario y suma la morbilidad de ambos tratamientos. La radioterapia exclusiva sin quimioterapia es inferior, y la inmunoterapia aislada no constituye el tratamiento primario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e03") }, {"long_answer": "La guía considera adecuada la conservación ovárica en pacientes menores de 45 años con carcinoma escamoso o adenocarcinoma VPH-dependiente en estadios precoces (pT1a-pT2a1), ya que el riesgo de metástasis ováricas es muy bajo y así se evita la menopausia quirúrgica. No puede ofrecerse a cualquier paciente con independencia de edad y estadio. Los adenocarcinomas VPH-independientes, como el de células claras, tienen mayor riesgo de afectación ovárica, y la presencia de metástasis ganglionares implica enfermedad más avanzada que desaconseja preservar los ovarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0c") }, {"long_answer": "La guía recomienda realizar estudio intraoperatorio del ganglio centinela mediante sección por congelación, de modo que, si se detecta afectación ganglionar, se abandone la histerectomía radical y se derive a la paciente a radioquimioterapia, evitando la suma de morbilidades. Posteriormente se completa el estudio diferido con ultraestadificación. Esperar solo al estudio postoperatorio impediría modificar la cirugía. Las improntas citológicas aisladas son menos fiables y la PET-TC es una prueba de imagen que no se realiza durante la intervención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e15") }, {"long_answer": "La radioterapia corporal estereotáctica (SBRT) permite administrar dosis muy altas por fracción, con efecto ablativo, en un número reducido de sesiones y con gran precisión, de modo que se protegen los tejidos sanos y la toxicidad es mínima. En cáncer de cuello uterino se emplea sobre todo en enfermedad oligometastásica o recidivas seleccionadas. La radioterapia tridimensional convencional usa fracciones pequeñas y muchas sesiones. La braquiterapia de baja tasa es una técnica antigua, superada por la de alta tasa, y la radioterapia intraoperatoria es una dosis única durante la cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1a") }, {"long_answer": "El test de O'Sullivan es la prueba de cribado de diabetes gestacional: se administran 50 g de glucosa por vía oral sin necesidad de ayuno y se mide la glucemia a los 60 minutos. Un valor igual o superior a 140 mg/dL se considera positivo y obliga a realizar la prueba diagnóstica confirmatoria, la sobrecarga oral con 100 g de glucosa. Los valores de 110 o 120 mg/dL están por debajo del punto de corte, y fijarlo en 160 mg/dL dejaría sin diagnosticar a muchas gestantes con diabetes gestacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1c") }, {"long_answer": "El índice de Bishop valora la madurez cervical (dilatación, borramiento, consistencia, posición del cuello y altura de la presentación) con una puntuación de 0 a 13. Una puntuación de 7 o más indica un cuello favorable, con buenas condiciones para el parto y alta probabilidad de éxito de una inducción con oxitocina. Las puntuaciones bajas, de 0 a 3 o inferiores a 4, indican un cuello desfavorable que suele requerir maduración cervical previa con prostaglandinas o métodos mecánicos, y entre 4 y 6 se considera una situación intermedia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1d") }, {"long_answer": "El índice de severidad de Sandvik valora la gravedad de la incontinencia urinaria mediante dos preguntas: la frecuencia con que se producen las pérdidas de orina y la cantidad de orina que se pierde en cada episodio. El producto de ambas puntuaciones clasifica la incontinencia en leve, moderada, grave o muy grave. Es una herramienta sencilla, útil en atención primaria y en el seguimiento. No mide la capacidad vesical ni el volumen residual, que requieren pruebas urodinámicas o ecográficas, y no valora la duración, la causa neurológica ni el dolor asociado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1e") }, {"long_answer": "La escala de Waterlow estima el riesgo de úlceras por presión a partir de varios factores, entre ellos la complexión y el peso respecto a la talla, la edad y el sexo, el aspecto de la piel en las zonas de riesgo, la movilidad, la continencia, el apetito y factores especiales como la malnutrición tisular, el déficit neurológico, la cirugía mayor o la medicación. La glucemia, la hemoglobina o la presión arterial no son parámetros de la escala, tampoco la duración de la cirugía o el tipo de anestesia, ni las constantes respiratorias y la temperatura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e20") }, {"long_answer": "En la escala NEWS (National Early Warning Score), una puntuación total de 7 o más indica un alto riesgo de deterioro clínico grave y obliga a una respuesta urgente, con valoración inmediata por un equipo con competencias en paciente crítico y monitorización continua. La escala suma puntos por frecuencia respiratoria, saturación, oxigenoterapia, presión arterial sistólica, frecuencia cardíaca, nivel de conciencia y temperatura. Por eso un NEWS de 7 o más es incompatible con considerar al paciente estable, sin alteración de constantes o subsidiario solo de monitorización rutinaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e24") }, {"long_answer": "La escala NIHSS (National Institutes of Health Stroke Scale) cuantifica el déficit neurológico en el ictus agudo valorando el nivel de conciencia, la mirada, los campos visuales, la paresia facial, la función motora de brazos y piernas, la ataxia o coordinación, la sensibilidad, el lenguaje, la disartria y la extinción o negligencia. Su puntuación orienta la gravedad y la indicación de tratamientos de reperfusión. No incluye constantes vitales ni parámetros analíticos, y aunque valora la respuesta motora, no incluye la dilatación pupilar ni el reflejo corneal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e26") }, {"long_answer": "La clasificación ASA de la American Society of Anesthesiologists estratifica el estado físico preoperatorio del paciente. Entre las opciones, ASA V es la de mayor riesgo: paciente moribundo que no se espera que sobreviva sin la intervención. ASA I corresponde a un paciente sano, ASA II a enfermedad sistémica leve y ASA III a enfermedad sistémica grave no incapacitante. La clase ASA VI se reserva para el paciente en muerte encefálica cuyos órganos se extraen para donación, por lo que no se aplica a la valoración del riesgo quirúrgico de un paciente vivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2a") }, {"long_answer": "El AUDIT (Alcohol Use Disorders Identification Test) de la OMS consta de 10 preguntas que exploran tres dominios: el consumo de riesgo (frecuencia y cantidad de alcohol, consumo intensivo), los síntomas de dependencia y el consumo perjudicial, es decir, los problemas y efectos derivados del alcohol. Por eso permite detectar desde el consumo de riesgo hasta la probable dependencia. No se limita a la cantidad consumida, y aunque recoge consecuencias del consumo y la preocupación de allegados, no se centra en las consecuencias laborales ni en la relación social con el alcohol."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2d") }, {"long_answer": "La escala de Tinetti valora la marcha y el equilibrio en personas mayores con una puntuación máxima de 28 puntos. Una puntuación de 18 o menos indica un riesgo alto de caídas, entre 19 y 23 un riesgo moderado y de 24 o más un riesgo bajo. Por tanto, 24 o más o el intervalo de 23 a 27 no corresponden a riesgo alto, y la franja de 19 a 23 señala un riesgo moderado que también requiere intervención preventiva, pero no es la categoría de mayor riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2e") }, {"long_answer": "En la escala de depresión geriátrica de Yesavage en su versión abreviada de 15 ítems, una puntuación de 0 a 5 se considera normal, de 6 a 9 indica probable depresión y de 10 o más depresión establecida. Por ello, una puntuación de 10 o más sugiere depresión establecida. Una puntuación de 6 o más marca ya la sospecha de depresión, pero no la depresión establecida; 15 es la puntuación máxima de la escala y no un punto de corte, y 3 está dentro del rango de normalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e33") }, {"question": "En la Escala Hospitalaria de Ansiedad y Depresión (HADS), ¿qué indica una puntuación de 8 a 10 en la subescala de ansiedad o en la de depresión?", "option_1": "Caso clínico probable", "option_2": "Posible caso clínico (caso dudoso)", "option_3": "Puntuación inválida", "option_4": "Normalidad, ausencia de casos", "long_answer": "La Escala Hospitalaria de Ansiedad y Depresión (HADS) consta de dos subescalas, de ansiedad y de depresión, con 7 ítems cada una y una puntuación de 0 a 21. En cada subescala, de 0 a 7 puntos se considera normalidad, de 8 a 10 un caso dudoso o posible caso clínico, y 11 o más un caso clínico probable. Una puntuación de 8 a 10 indica, por tanto, un posible caso que requiere seguimiento y valoración más detallada. No corresponde todavía a un caso probable, no es una puntuación inválida y supera el rango de normalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e38") }, {"long_answer": "El índice de Barthel mide el grado de independencia de la persona en las actividades básicas de la vida diaria: alimentación, baño, aseo personal, vestido, control de heces y orina, uso del retrete, traslado cama-sillón, deambulación y subir y bajar escaleras. Su puntuación de 0 a 100 clasifica la dependencia en total, grave, moderada, leve o independencia. La fuerza muscular se valora con la escala de Daniels o del MRC, la disnea con escalas como la mMRC o la de Borg y el delirium en UCI con el CAM-ICU."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3a") }, {"long_answer": "La escala de disnea modificada del Medical Research Council (mMRC) clasifica la disnea en cinco grados, de 0 a 4: grado 0, disnea solo con ejercicio intenso; grado 1, al andar deprisa o subir una pendiente; grado 2, obliga a andar más despacio que personas de la misma edad o a parar; grado 3, tiene que parar tras unos 100 metros o pocos minutos en llano; y grado 4, impide salir de casa o aparece con actividades como vestirse. Los rangos de 0 a 10 corresponden a la escala de Borg modificada, y los de 1 a 5 o 1 a 10 no se aplican a la mMRC."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3f") }, {"long_answer": "El qSOFA valora tres criterios en pacientes con sospecha de infección: frecuencia respiratoria de 22 o más, alteración del estado mental y presión arterial sistólica de 100 mmHg o menos. Una puntuación de 2 o más identifica a pacientes con alto riesgo de mala evolución, de progresión a sepsis o shock séptico y con mayor mortalidad, por lo que requieren valoración urgente y monitorización estrecha. No es compatible con un bajo riesgo ni con una simple vigilancia estándar, y no puede interpretarse como ausencia de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e42") }, {"long_answer": "El documento subraya que en la adolescencia el sistema nervioso central sigue madurando, especialmente la corteza prefrontal, y que el consumo de alcohol a cualquier dosis interfiere en ese desarrollo, produciendo déficits de atención, concentración, memoria y capacidad para resolver tareas, con repercusión en el rendimiento escolar. Por eso el objetivo es retrasar al máximo la edad de inicio y no se habla de un consumo seguro. El alcohol no estimula las capacidades intelectuales, no existe una dosis baja sin efecto y su daño no se limita al hígado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e43") }, {"long_answer": "En el documento, el posible trastorno por uso de videojuegos se define cuando el adolescente cumple cinco o más de los nueve criterios propuestos para el Internet Gaming Disorder en el DSM-5, como preocupación constante por el juego, síntomas de abstinencia, tolerancia, pérdida de control, abandono de otras actividades o engaño sobre el tiempo dedicado. El número de horas aislado no define el trastorno, tres criterios es un umbral inferior al establecido y el uso diario sin impacto en la vida social no constituye un uso problemático."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e45") }, {"long_answer": "En las encuestas EStuDES, la categoría de drogas ilegales agrupa los inhalables volátiles, el cannabis, la cocaína (polvo y base), la heroína, las anfetaminas, el éxtasis, los alucinógenos y el GHB, entre otras sustancias de uso ilícito. Esta agrupación permite estimar la prevalencia global de consumo de sustancias ilegales en estudiantes de 14 a 18 años. No se limita al cannabis y la cocaína ni a los derivados del opio, y el alcohol y el tabaco son drogas legales que se analizan por separado, aunque su venta a menores esté prohibida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e46") }, {"long_answer": "Según los datos de EStuDES recogidos en el boletín, la proporción de estudiantes de 14 a 18 años que ha consumido drogas ilegales se ha mantenido relativamente estable entre 2014 y 2023, con ligeras oscilaciones entre ediciones, en buena medida porque el cannabis, que concentra la mayor parte del consumo, no ha sufrido grandes cambios. No se ha producido una duplicación ni un aumento progresivo cada año, y tampoco el descenso tan marcado que propone la opción del 19,5% al 10%."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4e") }, {"long_answer": "Según la serie histórica de la encuesta EDADES, el mayor consumo de cocaína en el último año en población de 15 a 64 años se registró en 2005, con una prevalencia del 3,0%. A partir de ese año la prevalencia descendió y se ha mantenido en niveles inferiores, en torno al 2-2,5% en las ediciones más recientes. Los valores de 2013 y 2024 son inferiores al máximo de 2005, y en 1995 la prevalencia era claramente más baja que la observada en el pico de mediados de la década de 2000."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d70") }, {"long_answer": "El radón-222 tiene un periodo de semidesintegración de unos 3,8 días. Al ser un gas noble químicamente inerte, cuando se inhala se exhala casi en su totalidad sin depositarse en el pulmón, por lo que su efecto directo es pequeño. El peligro procede de sus descendientes de vida corta (polonio, plomo y bismuto), partículas sólidas que se depositan en el epitelio bronquial y emiten radiación alfa. El periodo de 1.600 años corresponde al radio-226, el radón sí es emisor alfa y 3 minutos es aproximadamente el periodo del polonio-218."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d77") }, {"long_answer": "La OMS recomienda un nivel de referencia de 100 Bq/m³ para la concentración media anual de radón en viviendas y lugares de trabajo, con el fin de minimizar el riesgo para la salud. Cuando por condiciones del país no sea posible, el nivel elegido no debería superar en ningún caso los 300 Bq/m³, que es el valor adoptado por la Directiva 2013/59/Euratom y por la normativa española. Por tanto, 300 Bq/m³ no es la recomendación preferente de la OMS, y los valores de 150 o 250 Bq/m³ en función de la antigüedad del edificio no figuran en sus recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7b") }, {"long_answer": "La normativa española de protección frente a las radiaciones ionizantes considera trabajadores expuestos a radón a aquellos que pueden recibir una dosis efectiva anual superior a 6 mSv por la exposición en su puesto de trabajo. En ese caso, la situación se gestiona como exposición planificada, con vigilancia dosimétrica y sanitaria. El valor de 1 mSv por año es el límite de dosis para el público, 20 mSv es el límite anual para trabajadores expuestos y 10 mSv no constituye el criterio de clasificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7c") }, {"long_answer": "Según el enfoque de la publicación 137 de la ICRP, la dosis efectiva anual por radón se estima multiplicando la concentración media de radón (Bq/m³) por las horas de exposición y por un coeficiente de dosis, que integra el factor de equilibrio y la conversión de exposición a dosis efectiva. Así se obtiene una dosis en mSv que se compara con el umbral de 6 mSv. La edad del trabajador o el nivel de ventilación no forman parte de la fórmula, y dividir la concentración entre el coeficiente no es dimensionalmente correcto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d80") }, {"long_answer": "El pooling europeo muestra que el radón y el tabaco interactúan de forma multiplicativa. Tomando como referencia a un no fumador con exposición mínima al radón, el riesgo relativo de cáncer de pulmón en un fumador expuesto a 400 Bq/m³ en el hogar se multiplica aproximadamente por 42, al combinar el riesgo atribuible al tabaco (en torno a 25 veces) con el exceso debido al radón. Por eso el beneficio absoluto de reducir el radón y dejar de fumar es mucho mayor en fumadores. Los factores 16 y 8 infravaloran esta interacción y afirmar que no cambia contradice la evidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d81") }, {"long_answer": "En la mayoría de las viviendas, el radón interior procede fundamentalmente del terreno sobre el que se asienta el edificio, mientras que los materiales de construcción aportan habitualmente una fracción pequeña, en torno al 10-20% o menos. Solo materiales muy específicos, con alto contenido en radio, pueden tener una contribución mayor. Afirmar que más del 50%, alrededor del 40% o casi el 100% procede de los materiales sobrestima su papel y desviaría las medidas de protección, que deben centrarse en impedir la entrada de gas desde el suelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d82") }, {"long_answer": "Dado que el tabaco y el radón actúan de forma sinérgica, la primera medida preventiva recomendada para los fumadores expuestos a concentraciones elevadas de radón es abandonar por completo el hábito tabáquico, ya que es la intervención que más reduce su riesgo absoluto de cáncer de pulmón. Además se deben adoptar medidas para reducir la concentración de radón. Cambiar de trabajo y seguir fumando mantiene el principal factor de riesgo, no modificar el consumo ignora la interacción y la simple reducción del número de cigarrillos no tiene el mismo beneficio que la cesación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d84") }, {"long_answer": "El Libro del Radón señala que el protocolo de vigilancia sanitaria diseñado para trabajadores expuestos a radiaciones ionizantes en instalaciones nucleares y radiactivas resulta insuficiente cuando se aplica a la exposición al radón, porque no está adaptado a sus particularidades: exposición crónica por inhalación, el pulmón como órgano diana, la interacción con el tabaco y la necesidad de valorar también la exposición residencial. No es más restrictivo que lo necesario para el radón, sí exige control de dosis y no está pensado para la industria química."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d85") }, {"long_answer": "Para conocer la concentración media anual de radón en un lugar de trabajo se utilizan detectores pasivos de trazas nucleares, que registran las partículas alfa emitidas, colocados durante un periodo prolongado, de al menos 2 a 3 meses y preferentemente en la estación fría, para minimizar el efecto de las variaciones diarias y estacionales. Los medidores de temperatura, humedad relativa o presión atmosférica recogen variables ambientales que pueden influir en la concentración de radón, pero no la miden."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8b") }, {"long_answer": "En los trabajadores fumadores expuestos a radón, la principal medida de prevención primaria es promover y facilitar la cesación tabáquica desde los servicios de prevención y de salud laboral, ofreciendo consejo, apoyo y tratamiento. La interacción sinérgica entre tabaco y radón hace que dejar de fumar sea la intervención con mayor impacto en la reducción del riesgo de cáncer de pulmón, junto con la reducción de la exposición en el lugar de trabajo. Ventilar sin dejar de fumar es insuficiente, sí existen recomendaciones específicas para fumadores y evitar medir el radón impediría la protección de los trabajadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8d") }, {"long_answer": "La exposición total al radón de una persona es la suma de la que recibe en su vivienda y en su lugar de trabajo. Como muchas personas trabajan cerca de donde viven, en zonas de alto potencial de radón es probable que ambas exposiciones sean elevadas, de modo que valorar solo la laboral infraestimaría el riesgo acumulado de cáncer de pulmón. Por eso se recomienda considerar ambas en la evaluación del riesgo y en la vigilancia de la salud. La exposición residencial no anula la laboral, ambas contribuyen al riesgo, y la residencial sí influye en la valoración del trabajador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d92") }, {"long_answer": "El Real Decreto 732/2019 modificó el Código Técnico de la Edificación e introdujo la sección HS 6 de protección frente a la exposición al radón. Sus exigencias se aplican a los edificios de nueva construcción y a las intervenciones en edificios existentes, como ampliaciones, cambios de uso o reformas relevantes en zonas de riesgo, pero no obligan a actuar en edificios ya construidos que no vayan a ser reformados. No impone mediciones anuales en todos los edificios antiguos, no prohíbe el uso de sótanos y sí establece medidas para las reformas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d95") }, {"long_answer": "En los trabajadores expuestos a radón que nunca han fumado no se recomienda el cribado de cáncer de pulmón con TC de baja dosis, porque su riesgo absoluto es bajo y el balance entre beneficios y daños (falsos positivos, pruebas invasivas, radiación, sobrediagnóstico) no está demostrado como favorable en este grupo. El cribado se plantea en personas de alto riesgo, fundamentalmente fumadores o exfumadores de edad avanzada con exposición acumulada. No procede aplicarlo a todos los trabajadores, cada 6 meses ni a menores de 40 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d98") }, {"long_answer": "La desfibrilación de doble secuencia está indicada en la parada cardiorrespiratoria con ritmo desfibrilable (fibrilación ventricular o taquicardia ventricular sin pulso) que persiste tras tres desfibrilaciones estándar, situación conocida como fibrilación ventricular refractaria. No se aplica en cualquier parada, ya que en asistolia o actividad eléctrica sin pulso la desfibrilación no está indicada. Un ritmo con pulso no requiere desfibrilación, y la fibrilación auricular se trata, si es necesario, con cardioversión sincronizada, no con desfibrilación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9b") }, {"long_answer": "En las tres primeras desfibrilaciones estándar se utiliza la posición anterolateral: el electrodo marcado como 'bajo la clavícula derecha' se coloca en posición horizontal debajo de la clavícula derecha, junto al esternón, y el otro en la línea axilar media izquierda, a la altura de V6, por debajo de la mamila. Colocarlo vertical en la espalda bajo la escápula izquierda corresponde a la posición posterior que se utiliza para el segundo monitor en la DDS, la línea axilar izquierda es la del otro electrodo y no se coloca sobre el esternón porque el hueso aumenta la impedancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9d") }, {"long_answer": "Tras las tres primeras descargas, durante el ciclo de RCP, se colocan los electrodos del segundo desfibrilador en posición anteroposterior: el electrodo que en la posición estándar iría bajo la clavícula derecha se sitúa en la espalda, bajo la escápula izquierda y en posición vertical, mientras que el otro se sitúa en la cara anterior del tórax. Así la segunda descarga sigue un vector diferente al de la primera. Colocar ambos en el tórax en horizontal o mantenerlo bajo la clavícula reproduciría el mismo vector, y llevar el electrodo a la axila derecha no es la configuración descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da1") }, {"long_answer": "En la desfibrilación de doble secuencia, el segundo monitor se configura con la misma energía que el primero, habitualmente la máxima disponible en cada equipo, de modo que ambas descargas sean igualmente eficaces y solo cambie el vector. No se programa el doble de energía, porque los equipos ya trabajan a su máximo y lo que se busca es sumar dos descargas, no aumentar una. Usar menos energía en el segundo equipo reduciría la eficacia, y la energía configurada sí influye en el resultado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dac") }, {"long_answer": "El segundo desfibrilador se enciende y se colocan sus electrodos durante el intervalo de 2 minutos de RCP que sigue a la tercera desfibrilación estándar, sin interrumpir las compresiones, para que esté preparado si en el siguiente análisis persiste el ritmo desfibrilable. Prepararlo antes del primer análisis no está indicado, porque la DDS solo se plantea tras tres descargas ineficaces, y esperar 10 minutos retrasaría la técnica. El número de intervinientes facilita la organización, pero no es lo que determina el momento de preparar el segundo equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977daf") }, {"long_answer": "Durante la desfibrilación de doble secuencia, los electrodos del primer monitor se mantienen en su posición inicial anterolateral, uno bajo la clavícula derecha y otro bajo la mamila izquierda en la línea axilar media, mientras que los del segundo monitor se colocan en posición anteroposterior. Así se combinan dos vectores distintos de descarga. Retirarlos eliminaría uno de los vectores y retrasaría la técnica; moverlos a la espalda coincidiría con la posición del segundo equipo, y colocarlos en las extremidades no permitiría que la corriente atravesara el corazón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db1") }, {"long_answer": "Las recomendaciones del protocolo se apoyan principalmente en el ensayo DOSE-VF, publicado en 2022 en el New England Journal of Medicine con el título 'Defibrillation strategies for refractory ventricular fibrillation'. En él, la desfibrilación de doble secuencia y el cambio de vector de los electrodos se asociaron a mayor supervivencia al alta hospitalaria que la desfibrilación estándar en la fibrilación ventricular refractaria. Las guías de la AHA de 2015, las europeas de 2010 y los manuales de primeros auxilios de la OMS son anteriores a esta evidencia y no recogen la técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db2") }, {"long_answer": "Al iniciar la atención a una parada cardiaca, comunicar la situación a la Central de Comunicaciones permite activar los recursos necesarios, por ejemplo una unidad de soporte vital avanzado, y conseguir un segundo desfibrilador, imprescindible si la fibrilación ventricular resulta refractaria y se plantea la doble secuencia. El traslado en ambulancia no es el objetivo inicial, ya que la reanimación se realiza in situ, el apoyo psicológico no es prioritario en el paciente en parada, y la administración de fármacos se rige por el protocolo de soporte vital avanzado, no por instrucciones de la central."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db4") }, {"long_answer": "Inmediatamente antes de cada descarga en la doble secuencia, el operador debe advertir en voz alta al equipo y a cualquier persona presente que se va a descargar y comprobar que nadie está en contacto con el paciente ni con la camilla. Con dos equipos y cuatro electrodos el riesgo eléctrico aumenta, por lo que este aviso es esencial para la seguridad. No se espera a que el paciente recupere el pulso, ya que la descarga se aplica precisamente porque no lo tiene; las pausas en la RCP deben ser mínimas, y la adrenalina se administra según su pauta, no antes de cada descarga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db8") }, {"long_answer": "En los niños con condiciones de alto riesgo de enfermedad grave por VRS, como cardiopatías congénitas significativas, displasia broncopulmonar o inmunodepresión grave, se recomienda nirsevimab antes del inicio de su segunda temporada siempre que tengan menos de 24 meses de edad cronológica en ese momento. Así se cubre el periodo en que el riesgo de hospitalización sigue siendo relevante. El límite de 6 meses corresponde a la población general en su primera temporada, y los límites de 12 meses o 36 meses de edad corregida no figuran en las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dbb") }, {"long_answer": "La cirugía cardíaca con bypass cardiopulmonar reduce de forma importante los niveles del anticuerpo circulante, por lo que se recomienda administrar una dosis adicional de nirsevimab lo antes posible una vez que el paciente esté estable tras la intervención, ajustando la dosis según el tiempo transcurrido desde la primera dosis y el peso o la temporada. No administrar dosis adicional dejaría al niño desprotegido, dar doble dosis antes de la cirugía no evita la pérdida durante el bypass y esperar 30 días prolongaría innecesariamente el periodo de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dce") }, {"long_answer": "El virus respiratorio sincitial (VRS) es el principal agente causal de bronquiolitis y neumonía en lactantes y la primera causa de hospitalización por infección respiratoria en menores de 12 meses durante los meses de otoño e invierno, con mayor gravedad en los primeros meses de vida y en prematuros. Por ello se ha incorporado la inmunización universal con nirsevimab. La gripe, los coronavirus y los adenovirus también causan infecciones respiratorias en lactantes, pero ocasionan un número de hospitalizaciones claramente inferior en este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd3") }, {"long_answer": "Los estudios realizados en España tras la primera temporada de uso de nirsevimab (2023-2024) mostraron una efectividad aproximada del 80% (en torno al 81-84%) para prevenir hospitalizaciones por VRS en los lactantes inmunizados, resultado coherente con los ensayos clínicos. Una eficacia inferior al 50% no se corresponde con los datos, ya que la protección observada fue muy alta; una cifra cercana al 95% la sobrestima, y afirmar que no se ha demostrado eficacia contradice la evidencia que sustenta la recomendación de inmunización universal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd8") }, {"long_answer": "Según los datos sociodemográficos que recoge el Marco Estratégico, alrededor del 50,5% de la población residente en España tiene más de 45 años, reflejo del progresivo envejecimiento y de la baja natalidad. La población española ronda los 48-49 millones de habitantes, lejos de los 60 millones; la esperanza de vida al nacer supera los 85 años en las mujeres, pero no en los hombres, que se sitúan en torno a los 81 años, y el número de nacimientos en 2023 disminuyó en lugar de aumentar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd9") }, {"long_answer": "Según los datos que recoge el Marco Estratégico, las enfermedades del sistema circulatorio fueron la primera causa de muerte en España en el primer semestre de 2024, seguidas muy de cerca por los tumores. Esta situación es coherente con el envejecimiento de la población y con el peso de las enfermedades crónicas no transmisibles. Los tumores son la segunda causa y en algunos grupos de edad la primera, las enfermedades respiratorias ocupan el tercer lugar, y los accidentes y traumatismos son causas externas, no naturales, con un peso mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ddb") }, {"long_answer": "El informe de 2024 sobre la situación de las enfermeras especialistas que recoge el Marco Estratégico pone de manifiesto la falta de reconocimiento laboral de la especialización: solo alrededor del 34,5% de las enfermeras que han realizado la formación sanitaria especializada trabajan con un contrato específico de especialista. El resto desempeña puestos de enfermera generalista. Un 90% no se corresponde con la realidad descrita, el reconocimiento salarial no es uniforme entre especialidades y las especialidades de enfermería sí están reguladas por el Real Decreto 450/2005."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ddc") }, {"long_answer": "El Marco Estratégico distingue entre profesiones del cuidado, que son aquellas con una titulación reglada orientada a cuidar, y profesionales del cuidado, concepto más amplio que incluye a cualquier persona que cuida aplicando conocimientos y habilidades, con independencia de su nivel de cualificación. Así se reconoce el papel de todas las personas que prestan cuidados. Limitarlo a profesionales altamente titulados restringe el concepto, el personal administrativo no forma parte de las profesiones del cuidado y el documento sí establece una diferencia entre ambos términos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ddd") }, {"long_answer": "El Marco Estratégico se basa en principios transversales que deben guiar todas las políticas de cuidados: la perspectiva de equidad en salud, el enfoque One Health (salud humana, animal y ambiental interrelacionadas), la igualdad de género, la participación ciudadana y la gobernanza para la salud. Estos principios orientan las acciones hacia la justicia social y la sostenibilidad. La alta tecnología con reducción de personal, la priorización hospitalaria sobre la atención primaria y la centralización de la formación en grandes ciudades son contrarias a la orientación comunitaria y equitativa del Marco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de6") }, {"long_answer": "Según el Marco Estratégico, el cuidado informal es el que prestan de forma no remunerada personas de la red social de quien recibe los cuidados, habitualmente familiares, amistades o vecinos, sin una relación contractual ni formación reglada como cuidadores. Recae mayoritariamente en mujeres y tiene un importante impacto en su salud y su vida laboral. La atención remunerada por profesionales, la que se presta en instituciones públicas o la realizada por enfermeras y médicos constituyen cuidado formal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dee") }, {"long_answer": "El Marco Estratégico propone reforzar el liderazgo enfermero asegurando la presencia de enfermeras en los comités de dirección, en los órganos de gobernanza de las instituciones sanitarias y en las sociedades científicas, con una representación igualitaria respecto a otras profesiones. Su participación en la toma de decisiones es clave para que las políticas sanitarias incorporen la perspectiva de los cuidados. Reducir su presencia, centralizar las decisiones en médicos y gestores o limitar su liderazgo a la gestión interna de sus unidades contradice este objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977def") }, {"long_answer": "En el ámbito de la colaboración internacional, el Marco Estratégico promueve que las enfermeras españolas participen activamente en los foros internacionales sobre políticas de cuidados y salud, como los de la OMS o las organizaciones europeas e internacionales de enfermería. Así se comparten buenas prácticas, se incorporan experiencias de otros países y se contribuye a la agenda global de cuidados. Aislarse de esos foros, limitarse a enviar informes escritos o desconocer las políticas globales es contrario a esta línea de acción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df3") }, {"long_answer": "El Marco Estratégico concibe el autocuidado como un pilar fundamental del modelo de práctica profesional enfermera, orientado a promover la autonomía de las personas en la gestión de su salud y de sus procesos crónicos. Para ello requiere recursos y apoyo institucional, como educación para la salud, programas de paciente activo y seguimiento por parte de las enfermeras. No es una responsabilidad exclusiva del paciente sin apoyo, no debe limitarse para evitar sobrecarga, ya que contribuye a la sostenibilidad del sistema, y no es un concepto obsoleto sustituible por la tecnología."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df5") }, {"long_answer": "La infección persistente por genotipos de alto riesgo del virus del papiloma humano (VPH), sobre todo los tipos 16 y 18, es la causa necesaria de la gran mayoría de los cánceres de cuello uterino, tanto escamosos como adenocarcinomas VPH-dependientes. Por eso la prevención se basa en la vacunación frente al VPH y en el cribado mediante prueba de VPH. El VIH no causa directamente el cáncer de cérvix, aunque la inmunodepresión favorece la persistencia del VPH; el herpes simple y el virus de Epstein-Barr no son agentes etiológicos de este tumor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df8") }, {"long_answer": "En los tumores de cérvix en estadio T1a1 (invasión estromal de 3 mm o menos) sin invasión del espacio linfovascular, el riesgo de afectación ganglionar es muy bajo, inferior al 1%, por lo que la guía recomienda no realizar estudio ganglionar. El tratamiento suele limitarse a la conización con márgenes libres o a la histerectomía simple si no se desea fertilidad. La biopsia del ganglio centinela se plantea si hay invasión linfovascular, la linfadenectomía pélvica completa sería un sobretratamiento y la PET-TC no está indicada en estadios tan iniciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dfe") }, {"long_answer": "Tras finalizar la radioquimioterapia y la braquiterapia, la primera evaluación de respuesta mediante exploración física y prueba de imagen, habitualmente resonancia magnética y, según el caso, PET-TC, se realiza aproximadamente a los 3 meses. Este intervalo permite que se resuelvan los cambios inflamatorios inducidos por la radiación y que el tumor alcance su máxima respuesta. Evaluar inmediatamente o a las 6 semanas podría dar falsos positivos por la inflamación residual, y esperar un año retrasaría la detección de enfermedad persistente susceptible de tratamiento de rescate."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e04") }, {"long_answer": "En las pacientes histerectomizadas tras el tratamiento de un cáncer de cuello uterino que presentan síntomas de deprivación estrogénica o menopausia precoz, la guía recomienda la terapia hormonal con estrógenos solos, como el valerato de estradiol por vía oral o el estradiol transdérmico a dosis adecuadas. Al no haber útero, no es necesario añadir gestágenos para proteger el endometrio. La terapia exclusiva con gestágenos no trata adecuadamente los síntomas, la tibolona no es la opción de elección y el cáncer de cérvix escamoso no contraindica la terapia hormonal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e06") }, {"long_answer": "Tras la cirugía radical del cáncer de cuello uterino, la paciente se considera de riesgo intermedio de recidiva, según los criterios de Sedlis, cuando presenta al menos dos de estos tres factores: tamaño tumoral mayor de 4 cm, invasión del espacio linfovascular e infiltración estromal profunda. En estas pacientes se valora la radioterapia adyuvante. Un tumor menor de 2 cm sin invasión linfovascular es de bajo riesgo, mientras que la afectación ganglionar y los márgenes quirúrgicos positivos son factores de alto riesgo que indican radioquimioterapia adyuvante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e07") }, {"long_answer": "Cuando el estudio de la pieza quirúrgica muestra márgenes vaginales o parametriales afectos, existe un alto riesgo de recidiva local, por lo que la guía indica radioterapia adyuvante con quimioterapia concomitante y braquiterapia secuencial sobre la cúpula vaginal para intensificar la dosis en la zona de riesgo. Los tumores T1a1 sin factores de riesgo o los menores de 2 cm sin afectación ganglionar tienen bajo riesgo y no requieren tratamiento adyuvante, y administrarlo en todos los casos supondría un sobretratamiento con toxicidad innecesaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0a") }, {"long_answer": "En los tumores de cuello uterino en estadios T1b1, T1b2 y T2a1 candidatos a cirugía, la biopsia selectiva del ganglio centinela es el estándar para la valoración ganglionar, ya que permite detectar la afectación con menor morbilidad que la linfadenectomía y realizar ultraestadificación. Si no se detecta el centinela en algún lado, se completa la linfadenectomía en ese hemipelvis. La linfadenectomía completa sin estudio selectivo aumenta las complicaciones como el linfedema, la PET-TC no sustituye al estudio quirúrgico y la ecografía transvaginal no valora adecuadamente los ganglios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0b") }, {"option_3": "Carcinoma escamoso microinvasivo (T1a1)", "long_answer": "Entre los tumores infrecuentes de cérvix, el adenocarcinoma de tipo gástrico, VPH-independiente, se caracteriza por un comportamiento agresivo, diagnóstico frecuentemente tardío, diseminación peritoneal y ovárica, peor pronóstico y escasa sensibilidad a la radioquimioterapia y a la quimioterapia. Además, no se detecta mediante el cribado basado en la prueba de VPH. El carcinoma escamoso VPH-dependiente es el más frecuente y el más radiosensible, el carcinoma escamoso microinvasivo tiene un pronóstico excelente y el adenocarcinoma de células claras, aunque también VPH-independiente, no se describe como el de peor pronóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0d") }, {"long_answer": "En las pacientes con deseo genésico y tumor escamoso menor de 2 cm en estadio T1a2 sin invasión del espacio linfovascular, el tratamiento preservador de la fertilidad adecuado es la conización o la traquelectomía simple con márgenes libres, junto con la valoración ganglionar indicada. Ofrece buenos resultados oncológicos con mínima morbilidad. La histerectomía radical tipo C2 y la radioquimioterapia no preservan la fertilidad y suponen un sobretratamiento, y renunciar al deseo reproductivo no es necesario en este estadio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0e") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado, la braquiterapia permite administrar dosis muy altas en la pelvis central, sobre el cuello y el volumen tumoral residual, respetando al mismo tiempo los órganos de riesgo, como vejiga, recto y sigma, gracias a la rápida caída de dosis alrededor de la fuente. Es un componente imprescindible del tratamiento radical y mejora el control local y la supervivencia. No sustituye a la radioterapia externa, sino que la complementa; no tiene una finalidad meramente sintomática y suele administrarse fraccionada en varias sesiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e13") }, {"long_answer": "La sobreexpresión difusa en bloque de p16 en estudio inmunohistoquímico se considera un marcador subrogado de infección por VPH de alto riesgo transcripcionalmente activa, ya que la oncoproteína E7 del virus inactiva la proteína del retinoblastoma y provoca su acúmulo. Es útil para diagnosticar las lesiones escamosas intraepiteliales de alto grado y clasificar los carcinomas como VPH-dependientes. El CA-125 es un marcador sérico usado sobre todo en cáncer de ovario, HER2/neu se relaciona con cáncer de mama y gástrico, y S-100 es un marcador de melanoma y tumores neurales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e17") }, {"long_answer": "El drenaje linfático parametrial alto del cuello uterino discurre a lo largo de los vasos uterinos hacia la arteria ilíaca interna, alcanzando los ganglios obturadores, ilíacos externos e ilíacos comunes, que constituyen la primera estación ganglionar del tumor. Por eso la valoración ganglionar se centra en la pelvis y, en segundo lugar, en los ganglios paraaórticos. Los ganglios inguinales superficiales drenan sobre todo la vulva y el tercio inferior de la vagina, el drenaje a paraaórticos no es directo y los ganglios supraclaviculares representan una afectación a distancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e25") }, {"long_answer": "En la escala de Rankin modificada, la puntuación 3 corresponde a una discapacidad moderada: la persona necesita cierta ayuda en algunas actividades, pero es capaz de caminar sin asistencia de otra persona. La puntuación 2 indica discapacidad leve, con incapacidad para realizar todas las actividades previas pero autonomía para el cuidado personal sin ayuda. La puntuación 4 indica discapacidad moderadamente grave, sin capacidad para caminar sin ayuda ni atender sus necesidades corporales, y la 5 discapacidad grave, con encamamiento, incontinencia y necesidad de cuidados constantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2c") }, {"long_answer": "El índice HOMA-IR estima la resistencia a la insulina a partir de la glucemia y la insulinemia en ayunas. Habitualmente se consideran normales los valores inferiores a 2,5, mientras que cifras superiores sugieren resistencia a la insulina, aunque el punto de corte puede variar según la población estudiada. Valores entre 3,0 y 4,5 o iguales o superiores a 5 o a 7 indican resistencia insulínica creciente y no corresponden a la normalidad, por lo que se asocian a síndrome metabólico y mayor riesgo de diabetes tipo 2."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3b") }, {"long_answer": "En la escala de Framingham clásica, un riesgo cardiovascular a 10 años superior al 20% se considera alto y justifica una intervención intensiva sobre los factores de riesgo, incluido el tratamiento farmacológico de la hipercolesterolemia según el contexto clínico. Un riesgo inferior al 10% se considera bajo, y entre el 10% y el 20% se considera moderado o intermedio. Por tanto, los intervalos menores del 5%, entre el 5% y el 10% o entre el 10% y el 20% no corresponden a la categoría de riesgo alto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3d") }, {"long_answer": "La clasificación KDIGO se utiliza para estadificar la enfermedad renal crónica combinando el filtrado glomerular estimado (categorías G1 a G5) y la albuminuria, medida como cociente albúmina/creatinina (categorías A1 a A3). Esta combinación permite estimar el pronóstico, el riesgo de progresión y de eventos cardiovasculares y orientar la frecuencia de seguimiento y la derivación a nefrología. No se usa para estratificar la hipertensión arterial, la gravedad del infarto de miocardio ni el riesgo de malnutrición, que disponen de clasificaciones propias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4a") }, {"long_answer": "Según la serie de EDADES recogida en el boletín, el consumo de hipnosedantes sin receta en la población de 15 a 64 años ha disminuido desde valores en torno al 3,1% al inicio de la serie hasta cifras cercanas al 1,3% en 2024. Este descenso contrasta con el consumo de hipnosedantes en general, con o sin receta, que se ha mantenido elevado en España. No ha aumentado de forma continua, no se ha mantenido estable durante todo el periodo y los picos en 2018 y 2020 no describen la tendencia observada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4c") }, {"long_answer": "Según la encuesta EDADES 2024 recogida en el boletín, alrededor del 9,2% de las personas de 15 a 64 años consumieron alguna droga ilegal en el último mes. La mayor parte de ese consumo corresponde al cannabis, que es con diferencia la droga ilegal más consumida, mientras que cocaína y otras sustancias aportan porcentajes mucho menores. Las cifras de 7,7%, 8,7% y 11,8% no corresponden al dato publicado para el consumo de drogas ilegales en el último mes en 2024."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4d") }, {"long_answer": "Según la encuesta EDADES 2024, aproximadamente el 2,1% de la población de 15 a 64 años consumió cannabis a diario o casi a diario en los últimos 30 días. Este patrón de consumo intensivo es el que se asocia con mayor riesgo de dependencia, problemas de salud mental y deterioro cognitivo, por lo que es un indicador clave del boletín. Los valores de 0,8%, 1,5% y 2,8% no corresponden a la prevalencia de consumo diario publicada para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4f") }, {"long_answer": "En la encuesta EDADES, el consumo de riesgo de alcohol se define mediante el cuestionario AUDIT con una puntuación de 8 o más en hombres y de 6 o más en mujeres. El punto de corte es más bajo en mujeres porque, a igual cantidad de alcohol, alcanzan concentraciones en sangre más elevadas y presentan mayor vulnerabilidad a sus efectos. La opción que invierte los puntos de corte es incorrecta, y los valores de 10 y 8 o de 6 y 4 no son los utilizados en el boletín."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e55") }, {"long_answer": "Según los datos de siniestralidad vial del boletín, en 2021 aproximadamente el 30,7% de los conductores fallecidos en siniestros de tráfico dieron positivo en alcohol en los análisis toxicológicos. Esta cifra confirma que el alcohol es uno de los principales factores de riesgo en la mortalidad por tráfico, sobre todo en combinación con otras drogas o psicofármacos. Los porcentajes del 24,8%, 26,1% y 28,7% no corresponden al dato publicado para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e56") }, {"long_answer": "La mortalidad por cirrosis y otras enfermedades crónicas del hígado, fuertemente relacionada con el consumo de alcohol, es claramente mayor en hombres que en mujeres en número de defunciones anuales, en consonancia con el mayor consumo de alcohol, y especialmente de consumo intensivo, en la población masculina. Las mujeres presentan cifras inferiores, aunque su vulnerabilidad al alcohol es mayor. En menores de 25 años estas muertes son excepcionales porque la cirrosis requiere años de exposición, y el informe sí especifica la diferencia por sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5a") }, {"long_answer": "Según los datos de vigilancia recogidos en el boletín, los nuevos diagnósticos de VIH en personas que se inyectan drogas han disminuido de forma notable entre 2013 y 2023, pasando de 189 a 55 casos. Este descenso refleja la reducción del consumo por vía inyectada y el éxito de los programas de reducción de daños, como el intercambio de jeringuillas y el tratamiento con agonistas opioides. No se ha observado un aumento progresivo, ni estabilidad alrededor de 150 casos, ni picos en 2019."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5e") }, {"long_answer": "Las Guías de Práctica Clínica son recomendaciones elaboradas de forma sistemática a partir de la mejor evidencia científica disponible para ayudar a profesionales y pacientes a tomar decisiones sobre la atención más adecuada. En el parto normal su objetivo principal es mejorar la toma de decisiones clínicas basadas en la evidencia, reduciendo la variabilidad injustificada y las intervenciones innecesarias. No pretenden acortar el parto en todas las mujeres, no promueven el uso exclusivo de analgesia farmacológica, ya que contemplan también métodos no farmacológicos, ni limitan la atención a un solo profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e51") }, {"long_answer": "El CAST (Cannabis Abuse Screening Test) es un cuestionario de 6 preguntas que se utiliza en las encuestas EStuDES y EDADES para detectar el consumo problemático de cannabis entre las personas que lo han consumido en el último año. Una puntuación de 4 o más se considera indicativa de consumo problemático, con riesgo de dependencia y de consecuencias negativas para la salud. Por tanto, no indica ausencia de problemas, consumo experimental u ocasional ni un consumo sin riesgos para la salud."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5b") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5d") }, {"long_answer": "El indicador de mortalidad por reacción aguda a sustancias psicoactivas del Plan Nacional sobre Drogas se basa en un registro específico de los institutos de medicina legal y, para sus estimaciones, incluye las muertes de personas de 10 a 64 años. Este rango concentra la gran mayoría de los fallecimientos relacionados con el consumo de drogas ilegales y facilita la comparación entre años y territorios. Los intervalos de 10 a 49 años o de 15 a 65 años no corresponden al criterio del registro, que sí establece un límite de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5f") }, {"long_answer": "GuíaSalud es un organismo del Sistema Nacional de Salud creado en 2002 por el Consejo Interterritorial del SNS para promover la elaboración, difusión y uso de Guías de Práctica Clínica y otras herramientas basadas en la evidencia en España. A través de él se coordina el programa de GPC del SNS, en el que participan las agencias de evaluación de tecnologías sanitarias. La agencia vasca y otras agencias colaboran en la elaboración de guías, pero no crearon el proyecto; el Ministerio de Ciencia e Innovación y la SEGO tampoco son sus promotores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c71") }, {"long_answer": "Para retener y fidelizar el talento enfermero, el Marco Estratégico recomienda mejorar las condiciones laborales (estabilidad, dotaciones adecuadas, retribución), promover el liderazgo enfermero, facilitar la conciliación de la vida personal, familiar y laboral y ofrecer oportunidades de desarrollo profesional y carrera. Estas medidas reducen el agotamiento y el abandono de la profesión. Incrementar las cargas de trabajo aumentaría el desgaste y el abandono, eliminar la formación continuada frenaría el desarrollo profesional y reducir las plazas públicas agravaría el déficit de enfermeras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c72") }, {"long_answer": "Según el informe de 2024 recogido en el Marco Estratégico, solo alrededor del 34,5% de las enfermeras que han completado la formación sanitaria especializada trabajan con un contrato de especialista. Este dato evidencia que muchas especialistas desempeñan puestos de enfermera generalista porque no se han creado suficientes plazas específicas, lo que desaprovecha su formación. Por eso el Marco plantea el desarrollo de las especialidades y la creación de puestos. Los porcentajes del 12,8%, el 75,2% y el 98,3% no corresponden al dato del informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7a") }, {"long_answer": "El Comité de Cuidados en Salud del Ministerio de Sanidad es el órgano colegiado estable encargado de la toma de decisiones, el seguimiento y la implantación del Marco Estratégico para los Cuidados, en coordinación con las comunidades autónomas y los agentes implicados. Su carácter estable garantiza la continuidad de las políticas de cuidados más allá de iniciativas puntuales. No se limita a analizar cuestiones financieras, ni a gestionar recursos humanos hospitalarios, ni a supervisar la formación de las TCAE, que serían funciones parciales y ajenas a su cometido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7b") }, {"long_answer": "El Marco Estratégico propone un modelo de clasificación y estratificación de pacientes según sus necesidades de atención y su complejidad para ajustar la dotación y la distribución de los recursos humanos de cuidados a las necesidades reales de la población. Así se personaliza la atención, se promueve la equidad, al destinar más recursos a quien más los necesita, y se contribuye a la sostenibilidad del SNS. No busca modelos homogéneos que ignoren el contexto social, ni simplificar trámites administrativos, ni aumentar la burocracia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7d") }, {"long_answer": "El concepto de Safe Nurse Staffing o dotación segura de enfermeras, recogido en el Marco Estratégico, se refiere a disponer del número suficiente de profesionales con la cualificación adecuada, en el lugar y en el momento adecuados, para prestar cuidados seguros, efectivos y de calidad según las necesidades de los pacientes. Las dotaciones inadecuadas se asocian a mayor mortalidad y eventos adversos. Contar con el mínimo personal para reducir gastos es justo lo contrario, el concepto no se limita a especialistas en unidades críticas y exige formación adecuada, no personal sin cualificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c80") }, {"long_answer": "Los indicadores sensibles a la complejidad y la carga de cuidados permiten medir de forma objetiva la actividad enfermera y relacionarla con la calidad, la seguridad del paciente y la eficiencia, de modo que la dotación de enfermeras se ajuste a las necesidades reales de cuidados y no solo al número de camas o pacientes. El Marco Estratégico para los Cuidados los plantea como herramienta de gestión y de planificación. No son un mero instrumento presupuestario sin aplicación práctica, no se centran en aspectos administrativos ajenos a la atención directa y sí tienen un impacto relevante en la gestión sanitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c83") }, {"long_answer": "La Ley 55/2003, del Estatuto Marco del personal estatutario de los servicios de salud, regula la relación funcionarial especial que vincula a este personal con los servicios de salud del SNS, adaptada a las características específicas del ejercicio de las profesiones sanitarias y a la organización de dichos servicios. No limita a este personal a la docencia, no lo exime del cumplimiento de la normativa sanitaria general, a la que sigue sometido, y tampoco establece ninguna dependencia de empresas privadas, ya que se trata de personal al servicio de la administración sanitaria pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8f") }, {"long_answer": "En el cáncer de cuello uterino en estadios precoces, sobre todo en el carcinoma escamoso, la afectación metastásica del ovario es muy poco frecuente, por lo que puede conservarse la función ovárica en mujeres jóvenes premenopáusicas, evitando la menopausia quirúrgica precoz y sus consecuencias cardiovasculares, óseas y sobre la calidad de vida. La preservación ovárica no tiene como finalidad reducir la recidiva local, mejorar el control ganglionar pélvico ni disminuir las metástasis a distancia; su beneficio es funcional y hormonal, siempre que la seguridad oncológica esté garantizada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca6") }, {"long_answer": "La histerectomía radical consiste en extirpar el útero junto con la porción craneal de la vagina y el tejido parametrial, y la clasificación de Querleu-Morrow describe distintos grados de radicalidad (tipos A, B, C1, C2 y D) según la extensión de la resección parametrial. La histerectomía simple no incluye parametrios ni manguito vaginal, la conización con asa de diatermia extirpa únicamente una parte del cérvix y la traquelectomía simple elimina el cuello uterino conservando el cuerpo del útero, por lo que ninguna de ellas encaja con la descripción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca7") }, {"long_answer": "Tras la cirugía del cáncer de cuello uterino, los factores de riesgo intermedio (criterios de Sedlis) que pueden indicar radioterapia adyuvante son el tamaño tumoral grande (mayor de 4 cm), la invasión linfovascular y la invasión estromal profunda (más de un tercio del estroma). Por eso el tamaño tumoral mayor de 4 cm es la respuesta correcta. Un margen quirúrgico negativo, la ausencia de invasión linfovascular o una invasión estromal superficial son, por el contrario, hallazgos favorables que no suponen factor de riesgo ni justifican por sí mismos el tratamiento adyuvante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977caa") }, {"long_answer": "En las recidivas centropélvicas de cáncer de cuello uterino en pacientes que ya recibieron radioterapia, la opción con intención curativa es la exenteración pélvica, siempre que no exista enfermedad a distancia ni afectación de la pared pélvica y la paciente tenga un estado general adecuado. La reirradiación exclusiva tiene un papel limitado por la toxicidad acumulada, la cirugía conservadora simple no consigue márgenes libres en un campo previamente irradiado y la quimioterapia exclusiva se reserva para enfermedad no rescatable o metastásica, con intención paliativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb4") }, {"long_answer": "La Escala de Oxford (modificada) gradúa de 0 a 5 la fuerza de contracción voluntaria de la musculatura del suelo pélvico, especialmente del músculo pubococcígeo, mediante palpación vaginal: 0 ausencia de contracción y 5 contracción fuerte que eleva el dedo explorador. Valora por tanto la fuerza, no la resistencia (que se mide con otras herramientas como el test PERFECT), ni la coordinación neuromuscular, ni el volumen o tamaño muscular, que requerirían pruebas de imagen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb5") }, {"long_answer": "El test PERFECT valora de forma completa la musculatura del suelo pélvico mediante palpación: P (power, potencia o fuerza según Oxford), E (endurance, resistencia en segundos), R (repetitions, número de repeticiones), F (fast, contracciones rápidas) y ECT (every contraction timed), lo que incluye también aspectos de coordinación y control. Por ello no mide solo la potencia, no es una herramienta para valorar dolor o sensibilidad y tampoco diagnostica la presencia de incontinencia urinaria, aunque resulte útil en su valoración y seguimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb6") }, {"long_answer": "El Test de Sandvik es un índice de severidad de la incontinencia urinaria que se obtiene a partir de dos preguntas: la frecuencia de los escapes y la cantidad de orina perdida. Multiplicando ambas puntuaciones se clasifica la incontinencia en leve, moderada, grave o muy grave. No mide de forma objetiva el volumen perdido durante la fisioterapia (eso lo hace el pad-test), no detecta infecciones urinarias, para lo que se usan tira reactiva o urocultivo, y no mide la capacidad vesical funcional, que se valora con diario miccional o urodinamia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cbc") }, {"answer": 1, "option_2": "Riesgo ligeramente elevado", "long_answer": "En el cuestionario FINDRISC, una puntuación inferior a 7 puntos corresponde a un riesgo bajo de desarrollar diabetes tipo 2 en los próximos 10 años (aproximadamente 1 de cada 100 personas). Las categorías siguientes son riesgo ligeramente elevado (7-11), moderado (12-14), alto (15-20) y muy alto (más de 20 puntos). Por tanto, una puntuación de 0 a 6 no indica riesgo ligeramente elevado, moderado ni alto, sino la categoría de menor riesgo de la escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cbe") }, {"long_answer": "El AUDIT (Alcohol Use Disorders Identification Test), desarrollado por la OMS, es un cuestionario de 10 preguntas para la detección del consumo de alcohol de riesgo, del consumo perjudicial y de la posible dependencia, muy utilizado en Atención Primaria. No se emplea para el tabaco, cuya dependencia se valora con el test de Fagerström, ni para la sobrecarga del cuidador, que se mide con la escala de Zarit, ni para la calidad del sueño, que se valora con instrumentos como el índice de Pittsburgh."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc0") }, {"long_answer": "La escala PUSH (Pressure Ulcer Scale for Healing) permite monitorizar la evolución de una úlcera por presión puntuando tres parámetros: superficie (longitud por anchura), cantidad de exudado y tipo de tejido del lecho. La suma de puntos, de 0 a 17, permite comparar la herida a lo largo del tiempo y valorar si cicatriza o empeora. No mide el dolor, ni la perfusión sanguínea de la zona, ni la presión aplicada sobre la úlcera; la valoración del riesgo de aparición se hace con otras escalas como Braden o Norton."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc3") }, {"long_answer": "En el Mini-Mental State Examination de Folstein, con puntuación máxima de 30, una puntuación inferior a 24 sugiere deterioro cognitivo, ajustándose siempre por edad y nivel de escolaridad. Puntuaciones iguales o superiores a 28, mayores de 26 o comprendidas entre 24 y 30 se consideran dentro de la normalidad o, como mucho, en el límite, por lo que no orientan a deterioro cognitivo. En la versión española adaptada (MEC de Lobo, sobre 35 puntos) los puntos de corte son distintos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ccd") }, {"long_answer": "La clasificación CEAP de la enfermedad venosa crónica describe la clínica en categorías de C0 a C6: C0 sin signos visibles, C1 telangiectasias o venas reticulares, C2 venas varicosas, C3 edema, C4 alteraciones cutáneas (pigmentación, eccema, lipodermatoesclerosis), C5 úlcera cicatrizada y C6 úlcera activa. Por tanto, el edema corresponde a C3, mientras que C1 y C2 reflejan alteraciones venosas visibles sin edema y C4 implica ya cambios tróficos en la piel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd2") }, {"long_answer": "Según la encuesta ESTUDES 2023 recogida en el boletín de indicadores clave del Plan Nacional sobre Drogas, el 56,6% de los estudiantes de 14 a 18 años había consumido alcohol en los últimos 30 días, lo que mantiene al alcohol como la sustancia psicoactiva más consumida por los adolescentes en España. Las cifras de 58,5%, 53,6% y 67% no corresponden al dato de 2023 que recoge el informe para el consumo en el último mes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd5") }, {"long_answer": "Los datos de la encuesta ESTUDES recogidos en el boletín de indicadores clave muestran que la proporción de adolescentes de 14 a 18 años que consumieron alguna droga ilegal en el último mes descendió del 19,9% en 2019 al 16,5% en 2023, un cambio favorable en el que pesa sobre todo el descenso del cannabis. No hubo un aumento hasta el 25%, el indicador no se mantuvo estable en torno al 19% y existen datos comparables de ambas ediciones de la encuesta, que se realiza de forma bienal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd6") }, {"long_answer": "Según la serie de la encuesta ESTUDES recogida en el boletín de indicadores clave, la percepción de riesgo asociada al consumo habitual de cannabis entre los adolescentes se ha mantenido aproximadamente estable entre 2006 y 2023, en torno al 50-55%. El informe no describe un descenso desde más del 80% hasta el 50%, ni un incremento hasta el 90%, y sí dispone de datos de este indicador en todas las ediciones de la serie, por lo que las demás opciones no se ajustan a la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd9") }, {"long_answer": "Según la encuesta EDADES recogida en el boletín de indicadores clave, el consumo de hipnosedantes sin receta en la población adulta ha descendido desde el 3,1% en 2003 hasta el 1,3% en 2024. No se ha producido un aumento progresivo hasta el 5%, ni un aumento brusco a partir de 2018, y la cifra nunca se ha situado en torno al 10%. Conviene diferenciar este indicador del consumo de hipnosedantes con o sin receta, que es mucho más elevado y ha mostrado una tendencia distinta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cdd") }, {"long_answer": "Según la encuesta EDADES 2024 recogida en el boletín de indicadores clave, el 2,3% de la población adulta de 15 a 64 años consumió cocaína (en polvo o base) en el último año, lo que la sitúa como la segunda droga ilegal más consumida tras el cannabis. Las cifras de 1,9%, 3% y 0,5% no corresponden al dato publicado para ese año y ese indicador, y conviene no confundir la prevalencia anual con la prevalencia alguna vez en la vida, que es muy superior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cdf") }, {"long_answer": "Según el boletín de indicadores clave, en 2024 el 6% de la población adulta presentó un consumo de riesgo de alcohol según el cuestionario AUDIT, con puntuaciones de 8 o más en hombres y 6 o más en mujeres. Las cifras de 5,2%, 7,5% y 4,5% no corresponden al valor publicado. El AUDIT, desarrollado por la OMS, permite identificar a las personas con consumo de riesgo o perjudicial en las que está indicada una intervención breve."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce4") }, {"long_answer": "El boletín de indicadores clave estima que la proporción de adultos con trastorno por consumo de heroína disminuyó desde el 0,25% en 2009 hasta el 0,16% en 2023, en consonancia con el envejecimiento de esta población y la menor incorporación de nuevos consumidores. No se produjo un aumento de 0,16% a 0,25%, que sería la tendencia inversa, ni una estabilidad en el 0,22%, y el informe sí ofrece información de la serie temporal para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce7") }, {"long_answer": "El boletín de indicadores clave advierte de que los datos sobre conductores implicados en siniestros mortales con resultado positivo en alcohol, procedentes del Instituto Nacional de Toxicología y Ciencias Forenses, no incluyen Cataluña ni el País Vasco, que tienen competencias propias, y no recogen a todos los conductores fallecidos, ya que quedan fuera los que fallecen en el momento del accidente según el criterio de recogida descrito, lo que limita su representatividad. No se trata de excluir a conductores sin licencia, ni de recoger solo siniestros no mortales, ni de excluir a menores de 30 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce8") }, {"long_answer": "Según los datos de mortalidad recogidos en el boletín de indicadores clave sobre drogas y adicciones, en hombres se registraron 5.916 muertes anuales por cirrosis y otras enfermedades crónicas del hígado, una causa en la que el consumo de alcohol tiene un peso muy importante y que es claramente más frecuente en varones que en mujeres. Las cifras de 3.309, 2.490 y 1.150 no corresponden al dato publicado para los hombres en el informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cec") }, {"long_answer": "El Cannabis Abuse Screening Test (CAST) consta de 6 preguntas sobre problemas asociados al consumo de cannabis; en las encuestas del Plan Nacional sobre Drogas se considera consumo problemático una puntuación de 4 o más sobre 6 en su versión dicotómica. El consumo diario no equivale por sí mismo a consumo problemático según este instrumento, el AUDIT valora el alcohol y no el cannabis, y un aviso de un profesional no es el criterio que utiliza el cuestionario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cef") }, {"long_answer": "El boletín de indicadores clave se nutre de diversas fuentes, entre ellas los centros de tratamiento de drogas, que aportan los datos de admisiones a tratamiento, y los laboratorios de toxicología, que informan de los resultados en fallecidos y conductores, además de las encuestas realizadas en centros de educación secundaria (ESTUDES). No se citan como fuentes específicas los médicos generales y enfermeras, los farmacéuticos y nutricionistas ni los policías y bomberos, aunque puedan intervenir indirectamente en algunos sistemas de información."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf1") }, {"long_answer": "El informe señala que estimar el consumo problemático y la adicción a drogas y a conductas es difícil porque se trata de fenómenos complejos, rodeados de estigma, que tienden a ocultarse, y porque no existen registros poblacionales que permitan cuantificarlos directamente, por lo que se recurre a encuestas y métodos indirectos. La alta precisión de las encuestas, el rápido acceso a tratamiento o el número de centros educativos no son limitaciones; al contrario, las encuestas tienden a infraestimar estos problemas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf5") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal del SNS va dirigida a los profesionales implicados directamente en la asistencia al parto: matronas, obstetras, pediatras y profesionales de enfermería, además de a las propias mujeres y sus familias. No se dirige principalmente a cirujanos generales y anestesiólogos, al personal administrativo y de gestión ni a internistas y médicos de familia, aunque algunos de estos profesionales puedan consultarla puntualmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf6") }, {"long_answer": "Uno de los rasgos más destacables de la elaboración de la GPC sobre la atención al parto normal es que contó con la colaboración conjunta de profesionales de distintas disciplinas y de mujeres pertenecientes a asociaciones, que aportaron la perspectiva de las usuarias a las recomendaciones. Las asociaciones de mujeres no fueron excluidas, la guía no se desarrolló en un solo hospital, aunque su elaboración se coordinó desde la agencia vasca OSTEBA, y no fue obra exclusiva del Ministerio de Ciencia e Innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf7") }, {"long_answer": "Dentro del Plan de Calidad para el SNS, la Agencia de Calidad del Sistema Nacional de Salud tiene como función promover la elaboración y el uso de Guías de Práctica Clínica basadas en la evidencia, con el fin de disminuir la variabilidad no justificada y mejorar los resultados en salud. Las GPC no tienen carácter legal obligatorio, sino que son recomendaciones para apoyar la toma de decisiones; la Agencia no concede licencias de uso de material clínico ni financia exclusivamente investigación obstétrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf8") }, {"long_answer": "El documento explica que fue en 2006 cuando, en el marco del Plan de Calidad para el SNS y con la participación de sociedades científicas y asociaciones, se comenzó a abordar el proceso de mejora de la atención al parto normal, que dio lugar a la Estrategia de Atención al Parto Normal (aprobada en 2007) y, posteriormente, a esta Guía de Práctica Clínica, publicada en 2010. Los años 2003, 2008 y 2010 no corresponden al inicio de este proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cfa") }, {"long_answer": "La guía señala que el volumen de información científica disponible es tan grande que los profesionales necesitan herramientas que sinteticen la evidencia y apoyen una toma de decisiones clínicas eficiente y segura; las Guías de Práctica Clínica cumplen precisamente esa función. No se plantea excluir a profesionales no especializados, automatizar por completo la asistencia ni eliminar la participación de la mujer, que la guía considera esencial en la toma de decisiones sobre su parto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d00") }, {"long_answer": "El trabajo de un grupo multidisciplinar y la inclusión de mujeres asociadas aportan un enfoque integrador, que permite que las recomendaciones tengan en cuenta tanto la evidencia científica como las distintas perspectivas profesionales y las necesidades y preferencias de las usuarias. Esta participación no es una complicación sin beneficio práctico, ni se plantea como una limitación para actualizar la guía, ni es un simple requisito formal sin impacto en el contenido final."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d01") }, {"long_answer": "La estrategia décima del Plan de Calidad para el SNS se orienta a mejorar la práctica clínica, y uno de sus objetivos es disminuir la variabilidad no justificada en la práctica mediante la elaboración y el uso de Guías de Práctica Clínica basadas en la evidencia. Esta estrategia no persigue desarrollar infraestructura tecnológica exclusiva, aumentar el personal administrativo en las consultas obstétricas ni extender la anestesia general en el parto, práctica que no se recomienda de forma rutinaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d03") }, {"long_answer": "En las Guías de Práctica Clínica, las recomendaciones se gradúan según la calidad de los estudios que las respaldan, lo que facilita al profesional interpretar la fuerza de la evidencia y aplicarla de forma prudente junto con su juicio clínico y las preferencias de la paciente. No todas las recomendaciones pueden tener el nivel máximo de evidencia, las guías no son protocolos rígidos de obligado cumplimiento y la gradación no sirve para diferenciar recomendaciones entre países desarrollados y en desarrollo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d07") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal forma parte del programa de GPC del Sistema Nacional de Salud, por lo que su ámbito de aplicación es todo el SNS español. Aunque su elaboración se coordinó desde la agencia de evaluación de tecnologías del País Vasco (OSTEBA), no se limita a esa comunidad, no es una guía de ámbito europeo y no está dirigida exclusivamente a hospitales privados, sino a la atención al parto en los centros del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d08") }, {"long_answer": "La GPC sobre la atención al parto normal se publicó en 2010 por el Ministerio de Sanidad y Política Social, dentro de la colección de Guías de Práctica Clínica en el SNS del Plan de Calidad, en colaboración con el Ministerio de Ciencia e Innovación y la agencia vasca OSTEBA. La Agencia Europea del Medicamento, la Organización Panamericana de la Salud y el Ministerio de Educación y Ciencia no fueron responsables de su edición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0a") }, {"long_answer": "La Estrategia de Atención al Parto Normal en el SNS tiene como objetivo principal favorecer que el parto sea una experiencia satisfactoria para las mujeres y sus recién nacidos, con atención de calidad y calidez, basada en la evidencia y respetuosa con la fisiología y las preferencias de la mujer. No pretende aumentar las cesáreas electivas, sino evitar intervenciones innecesarias, promueve el acompañamiento durante el parto en lugar de eliminarlo y no fija una duración máxima del parto de cuatro horas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0e") }, {"long_answer": "La GPC sobre la atención al parto normal se financió mediante el convenio suscrito entre el Instituto de Salud Carlos III, organismo dependiente entonces del Ministerio de Ciencia e Innovación, y la Agencia de Evaluación de Tecnologías Sanitarias del País Vasco (OSTEBA), en el marco del Plan de Calidad para el SNS. No intervinieron como financiadores el Ministerio de Educación con el Consejo Interterritorial, la OMS con la Unión Europea ni el Ministerio de Trabajo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d11") }, {"long_answer": "En la extracción de hemocultivos, el primer momento de higiene de manos es antes del contacto con el paciente, de acuerdo con los cinco momentos de la OMS, y debe repetirse antes de la tarea aséptica, después del riesgo de exposición a fluidos y tras el contacto con el paciente. Realizarla solo al terminar o después del contacto no protege al paciente de la contaminación de la muestra, y la opción de asearse las manos antes de asearse las manos carece de sentido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d12") }, {"long_answer": "La guía recomienda como método preferente de higiene de manos antes de la extracción la fricción con solución hidroalcohólica durante 20-30 segundos, salvo que las manos estén visiblemente sucias, en cuyo caso se lavarán con agua y jabón durante 40-60 segundos. Un lavado de solo 15 segundos es insuficiente, el lavado quirúrgico no está indicado para este procedimiento y el uso de guantes estériles no exime en ningún caso de la higiene de manos previa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d15") }, {"long_answer": "La guía no recomienda el uso rutinario de mascarilla quirúrgica en la extracción de hemocultivos, pero sí cuando el profesional presenta una infección respiratoria, con el fin de proteger al paciente y evitar contaminar la muestra con flora de las vías respiratorias. Por tanto, no debe usarse siempre, no es correcto decir que nunca sea recomendable y su indicación no depende de que el paciente tenga una infección respiratoria, situación en la que se aplicarían las precauciones de transmisión correspondientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d16") }, {"long_answer": "Para la antisepsia cutánea previa a la extracción de hemocultivos en pacientes mayores de 2 meses se recomienda la clorhexidina al 2% en solución alcohólica, porque reduce la tasa de contaminación frente a la povidona yodada y actúa con mayor rapidez y efecto residual. La povidona yodada al 10% y el alcohol de 70% son alternativas menos eficaces, y la clorhexidina acuosa al 0,5% no es la concentración recomendada; en menores de 2 meses deben seguirse las indicaciones específicas para neonatos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d17") }, {"long_answer": "La guía recomienda aplicar el antiséptico frotando la piel con aplicadores estériles monodosis durante unos 30 segundos y dejarlo secar completamente antes de la punción, respetando el tiempo de secado indicado, ya que es entonces cuando ejerce su máximo efecto. Los movimientos concéntricos con secado inmediato no permiten la acción del antiséptico, una sola pasada con algodón es insuficiente y el lavado previo con agua y jabón no sustituye a la antisepsia ni forma parte de la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d18") }, {"long_answer": "Una vez realizada la antisepsia, no se debe palpar el punto de punción con el guante utilizado previamente, porque se contamina la zona desinfectada; si es imprescindible palpar, hay que ponerse un guante estéril nuevo. Palpar sin cambio de guante, aunque sea necesario, o desinfectar el dedo con antiséptico no garantizan la ausencia de contaminación y aumentan el riesgo de falsos positivos, que conllevan tratamientos antibióticos innecesarios y estancias más largas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1a") }, {"long_answer": "La guía desaconseja extraer hemocultivos a través de catéteres venosos periféricos ya insertados, porque se asocian a mayores tasas de contaminación; solo se acepta la extracción en el momento mismo de la inserción del catéter, con técnica aséptica. No es la técnica preferida, la venopunción periférica directa sigue siendo la de elección, y desechar 5 ml de sangre no resuelve el problema de la colonización del catéter. Decir que no se haga bajo ninguna circunstancia ignora la excepción de la inserción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1f") }, {"long_answer": "En adultos se recomienda inocular entre 10 y 15 ml de sangre por frasco de hemocultivo, ya que la rentabilidad diagnóstica aumenta con el volumen de sangre cultivado y volúmenes bajos favorecen los falsos negativos. Un volumen inferior a 5 ml es insuficiente en el adulto, mientras que 20-30 ml corresponde al volumen total por pareja de frascos y no por frasco individual. El volumen no es indiferente, y excederse también puede alterar la proporción sangre-medio del frasco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d22") }, {"long_answer": "Se recomienda obtener cada pareja de hemocultivos de un punto de punción diferente, porque así se reduce el riesgo de contaminación y se facilita la interpretación de los resultados: un microorganismo de la flora cutánea que crece en un solo set suele indicar contaminación, mientras que si crece en sets de distintos puntos sugiere bacteriemia verdadera. Usar siempre el mismo punto dificulta esta interpretación, y la recomendación no se limita a la población pediátrica ni a pacientes con catéter central."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d23") }, {"long_answer": "Los hemocultivos deben obtenerse antes de iniciar el tratamiento antibiótico, porque la administración previa de antimicrobianos reduce de forma importante la probabilidad de aislar el microorganismo causal. Extraerlos después de una dosis o simultáneamente a la administración disminuye la rentabilidad diagnóstica, y esperar a que el paciente esté estable retrasaría tanto el diagnóstico como el tratamiento. En la sepsis la extracción no debe demorar el inicio del antibiótico, pero idealmente se realiza antes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d24") }, {"long_answer": "No debe introducirse aire en el frasco para anaerobios, ya que el oxígeno dificulta o impide el crecimiento de los microorganismos anaerobios estrictos; por eso, cuando se utiliza jeringa, se eliminan las burbujas y se inocula primero este frasco. La entrada de aire no favorece el crecimiento en este medio, la opción de que el frasco no sea anaeróbico no tiene sentido en este contexto y sí existe una recomendación clara de evitar el aire en el frasco anaerobio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d25") }, {"long_answer": "La guía recomienda no cambiar la aguja entre la venopunción y la inoculación de los frascos, porque el cambio aumenta el riesgo de pinchazo accidental del profesional y apenas reduce la tasa de contaminación. Cambiarla siempre por higiene no está justificado por la evidencia, y no se establecen excepciones ligadas a que la aguja esté dañada o a la duración del procedimiento, aunque una aguja visiblemente deteriorada o contaminada obviamente no debe reutilizarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d26") }, {"long_answer": "Antes de inocular la sangre es necesario desinfectar el tapón de goma de cada frasco, ya que la tapa protectora no garantiza la esterilidad de su superficie; la guía recomienda hacerlo con clorhexidina al 2% en solución alcohólica durante unos 15 segundos y dejarla secar antes de pinchar. El uso de guantes no evita la contaminación del tapón, limitar la desinfección al alcohol de 70% no es lo recomendado en la guía y la tapa del frasco no se cambia antes de inocular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d29") }, {"long_answer": "Cuando la sangre se extrae con jeringa y aguja, se inocula primero el frasco anaerobio, para evitar que entre en él el aire que pueda quedar en la jeringa y comprometa el crecimiento de los anaerobios; después se inocula el aerobio. En cambio, cuando se usa un sistema de palomilla con adaptador, se llena primero el aerobio porque el aire del tubo de la palomilla iría al primer frasco. Los hemocultivos se inoculan antes que los tubos de analítica y los frascos no se llenan simultáneamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2a") }, {"long_answer": "Colocar una gasa u otro material no estéril sobre la aguja en el momento de retirarla puede contaminarla, y con ella la muestra si aún no se han inoculado los frascos, por lo que la guía sugiere no hacerlo y comprimir el punto de punción una vez retirada la aguja. No es una medida recomendada para prevenir hemorragias, y el riesgo de contaminación no depende de que se usen guantes no estériles ni se limita a pacientes inmunodeprimidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2c") }, {"long_answer": "Si los hemocultivos no pueden enviarse de inmediato al laboratorio, deben mantenerse a temperatura ambiente y no más de 18 horas hasta su incubación, porque las bajas temperaturas pueden inhibir el crecimiento de microorganismos exigentes. Refrigerarlos o congelarlos reduce la viabilidad de las bacterias y aumenta los falsos negativos, y dejarlos a temperatura variable según disponibilidad es inadecuado. Lo ideal es enviarlos cuanto antes, preferiblemente en menos de 2 horas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2f") }, {"long_answer": "Explicar al paciente en qué consiste la técnica y para qué se realiza el hemocultivo favorece su colaboración, reduce la ansiedad y aumenta la seguridad del procedimiento, además de respetar su derecho a la información y facilitar su consentimiento. Por tanto, sí aporta beneficios, no es una medida reservada a pacientes pediátricos y debe realizarse en todas las extracciones, no solo cuando los hemocultivos se repiten."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d31") }, {"long_answer": "El Plan Nacional contra el Radón establece un Comité de coordinación presidido por el Ministerio de Sanidad, encargado de impulsar y hacer el seguimiento de las actuaciones del Plan, en el que participan además otros departamentos ministeriales, como el Ministerio para la Transición Ecológica y el Reto Demográfico o el de Vivienda, el Consejo de Seguridad Nuclear y representantes de las comunidades autónomas y de la Federación Española de Municipios y Provincias, que no ostentan la presidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d32") }, {"long_answer": "La principal vía de entrada del radón en los edificios es su paso desde el terreno, por difusión y sobre todo por advección (diferencia de presión), a través de grietas, juntas, poros y pasos de instalaciones en soleras y muros en contacto con el suelo. El aporte por desgasificación del agua corriente y la exhalación desde los materiales de construcción son, en general, fuentes secundarias, y las ventanas herméticas no son una vía de infiltración, sino que pueden favorecer la acumulación al reducir la ventilación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d49") }, {"long_answer": "El Real Decreto 1029/2022 obliga a los titulares de lugares de trabajo afectados por el radón a medir su concentración y, cuando se supera el nivel de referencia de 300 Bq/m³ de media anual, a adoptar medidas para reducirla y a volver a medir para comprobar su eficacia, manteniendo un control periódico. No se exige cesar la actividad de forma inmediata, la condición de fumador no permite exposiciones sin restricciones y el número de trabajadores afectados no exime de actuar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d50") }, {"long_answer": "Según el análisis de situación del plan de ampliación de la cartera de salud bucodental, la revisión anual de la salud bucodental en la población infantil es la prestación básica cubierta por el 100% de las comunidades autónomas. Otras prestaciones, como la aplicación de flúor tópico, los tratamientos pulpares en dentición permanente o las tartrectomías, se ofrecen de forma más heterogénea, lo que justifica la ampliación de la cartera común para homogeneizar las prestaciones en todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c75") }, {"long_answer": "En el Marco Estratégico para los Cuidados de Enfermería, la línea de investigación e innovación en cuidados persigue fomentar la investigación enfermera, generar evidencia que fundamente la práctica clínica y las políticas sanitarias y evaluar su impacto mediante indicadores. Las demás opciones son contrarias a ese objetivo: no se busca reducir la actividad investigadora ni eliminar los recursos destinados a ella, y la investigación enfermera no se limita a las farmacias hospitalarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c78") }, {"long_answer": "El Marco Estratégico para los Cuidados propone aumentar la presencia de enfermeras en puestos de alta dirección y toma de decisiones, por ejemplo como directoras generales de Cuidados en las comunidades autónomas y en los municipios, para que la visión de los cuidados se integre en las políticas sanitarias. No plantea mantener la situación actual sin cambios, ni reservar la dirección sanitaria a profesionales médicos, ni limitar el acceso a la gestión a enfermeras especialistas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7e") }, {"long_answer": "Según el Marco Estratégico, los Diplomas de Acreditación y de Acreditación Avanzada previstos en la Ley de Ordenación de las Profesiones Sanitarias certifican el nivel de formación y competencia alcanzado por las enfermeras en áreas funcionales específicas y pueden valorarse como mérito para acceder a determinados puestos de trabajo. No son licencias de prescripción para médicos, no unifican las especialidades enfermeras en un único título y no son una formación dirigida a técnicos auxiliares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c89") }, {"long_answer": "La sobreexpresión difusa en bloque de p16 en inmunohistoquímica es el marcador subrogado de infección por VPH de alto riesgo transcripcionalmente activa, y se utiliza para clasificar los carcinomas de cuello uterino como VPH-asociados o independientes, como recoge la clasificación de la OMS. El CEA es un marcador tumoral sérico inespecífico, la vimentina es un marcador mesenquimal y los receptores de estrógeno se emplean en el estudio de tumores de mama o endometrio, no como indicador de infección por VPH."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8b") }, {"long_answer": "En el cáncer de cuello uterino en estadio T1a1 sin invasión linfovascular, el riesgo de afectación ganglionar es prácticamente nulo, por lo que la guía indica que no se debe realizar estudio ganglionar; basta con la conización con márgenes libres o la histerectomía simple según el deseo genésico. La biopsia de ganglio centinela solo se considera si existe invasión linfovascular, la linfadenectomía pélvica completa supondría un sobretratamiento y el PET-TC no está indicado en este estadio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8c") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado (T1b3, T2a2-T4a o con afectación ganglionar N1), el tratamiento de elección es la radioquimioterapia concomitante basada en cisplatino seguida de braquiterapia guiada por imagen. La histerectomía radical no es el tratamiento estándar en estos estadios porque con frecuencia precisaría radioterapia adyuvante y aumentaría la morbilidad, la radioterapia externa sola es inferior a la combinación con quimioterapia y la quimioterapia adyuvante con carboplatino y paclitaxel no sustituye al tratamiento radical."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8d") }, {"option_1": "IB2", "long_answer": "En la clasificación FIGO 2018, el estadio IB corresponde a tumores invasivos limitados al cuello uterino con invasión en profundidad de 5 mm o más, y se subdivide por el diámetro mayor: IB1 menor de 2 cm, IB2 entre 2 y 4 cm e IB3 de 4 cm o más. Por tanto, un tumor de 3 cm limitado al cérvix sin afectación ganglionar es un IB2. El IA2 es una lesión microinvasiva, el IIB implica afectación parametrial y el IIIB extensión a la pared pélvica o hidronefrosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c93") }, {"long_answer": "Para la valoración preterapéutica del carcinoma cervical confirmado, la guía considera necesaria la resonancia magnética pélvica, que es la mejor prueba para valorar el tamaño tumoral, la extensión parametrial y la afectación de órganos vecinos, junto con el PET-TC para el estudio ganglionar y de enfermedad a distancia, especialmente en estadios avanzados. La radiografía de tórax, la ecografía abdominal o una TC sin contraste ofrecen una información insuficiente para estadificar y planificar el tratamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c95") }, {"long_answer": "En los tumores T1a2 de cuello uterino con invasión linfovascular presente, existe un riesgo de afectación ganglionar que justifica estudiar los ganglios, y la guía indica la biopsia selectiva de ganglio centinela como técnica de estadificación ganglionar, ya que es menos agresiva que la linfadenectomía y tiene alta sensibilidad. No estudiar los ganglios infravaloraría la enfermedad, la linfadenectomía pélvica completa sistemática aumenta la morbilidad sin ser necesaria y la TC simple no es una técnica válida de estadificación ganglionar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca0") }, {"long_answer": "Según la guía, la inmunohistoquímica con p16 es la herramienta fundamental para resolver los casos dudosos en el estudio histológico del cuello uterino, ya que ayuda a diferenciar las lesiones preinvasivas de alto grado de sus simuladores y apoya la confirmación de la naturaleza VPH-asociada de la lesión invasiva. La citología es una prueba de cribado y no permite valorar la invasión estromal, y el PET-TC y la ecografía transvaginal son técnicas de imagen sin capacidad para distinguir lesiones preinvasivas a nivel histológico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca2") }, {"long_answer": "En la enfermedad metastásica o recurrente no candidata a tratamiento local, la primera línea sistémica recomendada es la quimioterapia con platino (cisplatino o carboplatino) y paclitaxel asociada a bevacizumab, a la que se añade pembrolizumab en tumores con expresión de PD-L1. La terapia hormonal no tiene papel en este tumor, la radioterapia externa exclusiva solo se usa con fines locales o paliativos y la doxorrubicina en monoterapia no es un tratamiento de primera línea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca3") }, {"long_answer": "El adenocarcinoma de tipo gástrico, independiente del VPH, es el subtipo histológico de cáncer de cuello uterino con peor pronóstico: suele diagnosticarse en estadios avanzados, tiene mayor tendencia a la diseminación y responde peor a la radioquimioterapia. El carcinoma escamoso asociado al VPH es el tipo más frecuente y el más sensible a la radioquimioterapia. El adenocarcinoma inflamatorio no es una entidad reconocida en el cérvix y el carcinoma neuroendocrino, aunque agresivo, no es el tipo al que se refiere la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca8") }, {"long_answer": "Tras el tratamiento del cáncer de cuello uterino, el seguimiento se basa en la anamnesis dirigida a síntomas y en la exploración física completa, incluida la ginecológica, sin realizar citologías de rutina, ya que su rentabilidad para detectar recidivas es baja; la citología o la prueba de VPH se mantienen tras un tratamiento con preservación de la fertilidad. No se recomiendan citologías y biopsias mensuales, el seguimiento no debe basarse solo en imagen y sí está indicado el seguimiento tras un tratamiento satisfactorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cab") }, {"long_answer": "Los criterios de Rotterdam permiten diagnosticar el síndrome de ovario poliquístico cuando se cumplen al menos dos de estos tres criterios: oligoovulación o anovulación, hiperandrogenismo clínico o bioquímico y morfología de ovario poliquístico en la ecografía, tras excluir otras causas. Las opciones que exigen una combinación concreta de dos criterios son incompletas, porque cualquier pareja de criterios es válida, y exigir los tres criterios a la vez es incorrecto, ya que no es necesario que coincidan todos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cac") }, {"option_2": "Agarre, deglución audible, tipo de pezón, comodidad de la madre y ayuda necesaria para la posición", "long_answer": "La escala LATCH evalúa la toma de pecho con cinco ítems cuyas iniciales forman su nombre: L (latch, agarre), A (audible swallowing, deglución audible), T (type of nipple, tipo de pezón), C (comfort, comodidad de la madre en mama y pezón) y H (hold, ayuda que necesita la madre para la posición). Cada ítem puntúa de 0 a 2, con un máximo de 10. Las demás opciones incluyen parámetros que la escala no mide, como la cantidad de leche, la duración de la toma o la calma del bebé o del padre."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977caf") }, {"long_answer": "La Escala de Depresión Postparto de Edimburgo (EPDS) es un cuestionario autoaplicado de 10 ítems para el cribado de la depresión posparto; una puntuación elevada (habitualmente 10-12 o más, según el punto de corte) indica riesgo de depresión y la necesidad de una valoración más completa y de apoyo psicológico. Una puntuación alta no refleja normalidad emocional, la escala no está diseñada para diagnosticar ansiedad generalizada y, al ser una herramienta de cribado, no establece por sí sola la indicación de tratamiento farmacológico inmediato."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb2") }, {"long_answer": "El Cuestionario de Dolor de McGill valora el dolor de forma multidimensional, combinando su intensidad con su calidad mediante descriptores sensoriales, afectivos y evaluativos, lo que proporciona información cualitativa y cuantitativa sobre la experiencia dolorosa durante el parto. Por eso no se limita a la intensidad, como harían la escala visual analógica o la numérica, ni únicamente a la duración y severidad, y tampoco mide la frecuencia de las contracciones, que se valora con la exploración o la tocografía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb7") }, {"long_answer": "En el Test de Bonney, con la vejiga llena, se pide a la paciente que tosa y, si aparece pérdida de orina, se repite la maniobra elevando manualmente el cuello vesical con dos dedos introducidos en la vagina; si con esa elevación la pérdida desaparece, la prueba es positiva e indica que la incontinencia de esfuerzo mejoraría con la corrección de la hipermovilidad uretral. Los ejercicios de Kegel, el esfuerzo físico prolongado o el tratamiento farmacológico no forman parte de la maniobra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb8") }, {"long_answer": "En la escala de Waterlow, a mayor puntuación mayor riesgo de úlceras por presión: de 10 a 14 puntos indica riesgo, de 15 a 19 alto riesgo y 20 o más muy alto riesgo. Por tanto, una puntuación igual o superior a 15 se considera alto riesgo. Las puntuaciones inferiores a 10, incluido el rango de 5 a 9, indican ausencia de riesgo significativo, y el intervalo de 10 a 14 corresponde a riesgo, pero no a alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cbb") }, {"long_answer": "La escala de Norton valora cinco parámetros (estado físico general, estado mental, actividad, movilidad e incontinencia), cada uno puntuado de 1 a 4, por lo que la puntuación oscila entre 5 y 20 puntos; la máxima posible es 20, que corresponde al menor riesgo. En la escala de Norton modificada se considera riesgo de úlceras por presión una puntuación de 14 o menos, y 5 puntos es la puntuación mínima, que refleja el riesgo más elevado. Ninguna de estas cifras es el valor máximo de la escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cbd") }, {"long_answer": "La escala de Lawton y Brody valora 8 actividades instrumentales de la vida diaria y, en su versión de 8 ítems, la puntuación va de 0 (máxima dependencia) a 8 (independencia total). En la interpretación habitual, 0-1 puntos indica dependencia total, 2-3 dependencia severa, 4-5 moderada, 6-7 leve y 8 independencia. Por tanto, una puntuación de 0-1 no indica dependencia leve ni moderada ni autonomía completa, que corresponde a la puntuación máxima."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc5") }, {"long_answer": "En la escala NEWS (National Early Warning Score), una puntuación agregada de 7 o más indica alto riesgo clínico de deterioro grave, incluida la sepsis, y requiere una valoración urgente por un equipo con competencias en paciente crítico, con monitorización continua. Puntuaciones bajas (0-4) se asocian a bajo riesgo y vigilancia estándar, por lo que las opciones que hablan de bajo riesgo, estabilidad o vigilancia estándar no se corresponden con una puntuación de 7 o superior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc7") }, {"long_answer": "La escala de Aldrete valora la recuperación postanestésica mediante cinco parámetros (actividad, respiración, circulación, conciencia y saturación de oxígeno o coloración), cada uno de 0 a 2 puntos, con un máximo de 10. Una puntuación de 9 o más indica que el paciente puede ser dado de alta de la unidad de recuperación. Puntuaciones de 7 o de 5 reflejan una recuperación todavía insuficiente, y exigir 10 puntos sería un criterio demasiado restrictivo, ya que 9 se acepta como apto para el alta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ccf") }, {"long_answer": "El boletín de indicadores clave recuerda que el cerebro continúa desarrollándose hasta aproximadamente los 25 años, especialmente la corteza prefrontal, responsable del control de impulsos y la toma de decisiones, lo que hace a adolescentes y jóvenes más vulnerables a los efectos de las drogas y a desarrollar adicciones. Las edades de 18, 20 y 30 años no corresponden a lo indicado en el informe; la mayoría de edad legal no coincide con la maduración cerebral completa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd4") }, {"long_answer": "En los indicadores sobre adolescentes, el consumo de drogas ilegales incluye sustancias como el cannabis, la cocaína, la heroína o el éxtasis, entre otras. Las benzodiacepinas recetadas y los hipnosedantes sin receta son medicamentos que se analizan en indicadores propios y no se clasifican como drogas ilegales, mientras que el alcohol y el tabaco son drogas legales, aunque su venta a menores esté prohibida, y también se estudian por separado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd7") }, {"long_answer": "Según el informe, en la población adulta se considera consumo intensivo de alcohol o binge drinking la ingesta de 5 o más bebidas alcohólicas en hombres y 4 o más en mujeres en una misma ocasión, en un intervalo aproximado de dos horas. El umbral de 3 bebidas para ambos sexos y el de 6 en hombres y 5 en mujeres no corresponden a esta definición, y sí existe una definición específica para adultos que se emplea en la encuesta EDADES."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cdc") }, {"long_answer": "Según la serie de la encuesta EDADES recogida en el boletín de indicadores clave, el consumo diario o casi diario de cannabis en la población adulta aumentó desde el 0,7% en 1997 hasta el 2,9% en 2013. No se mantuvo estable en torno al 5%, cifra que nunca llegó a alcanzar este indicador, ni disminuyó por debajo del 1%, y existen datos disponibles de este indicador en las sucesivas ediciones de la encuesta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cde") }, {"long_answer": "En las encuestas del Plan Nacional sobre Drogas, el consumo de riesgo de alcohol se define con el cuestionario AUDIT a partir de una puntuación de 8 o más en hombres y de 6 o más en mujeres, utilizando un punto de corte más bajo en mujeres por su mayor vulnerabilidad a los efectos del alcohol. La opción que invierte los puntos de corte es incorrecta, igual que las que proponen 7 y 5 o un punto de corte común de 5 para ambos sexos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce9") }, {"long_answer": "Según el boletín de indicadores clave, el 93,1% de las madres de recién nacidos sanos refirieron no haber consumido alcohol durante el embarazo, lo que significa que aproximadamente 7 de cada 100 sí lo hicieron, pese a que no existe un nivel seguro de consumo en la gestación. Las cifras del 70,1%, el 85,4% y el 78,9% no corresponden al dato publicado en el informe para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cea") }, {"long_answer": "Según el boletín de indicadores clave, la cobertura del tratamiento sustitutivo de opioides (con metadona o buprenorfina) en las personas con trastorno por uso de heroína se estimó en torno al 99% en 2023, lo que refleja la amplia accesibilidad de estos programas en España. Las cifras del 84,1%, el 88,2% y el 92% no corresponden al valor publicado en el informe para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf0") }, {"long_answer": "Según el boletín de indicadores clave, en 2020 aproximadamente el 2,2% de la población adulta presentaba un posible juego problemático o trastorno del juego, según los instrumentos de cribado empleados en las encuestas. Las cifras del 1,4%, el 1,7% y el 2,6% no corresponden al valor publicado para ese año. El juego es la principal adicción comportamental estudiada en el informe, junto con el uso compulsivo de internet."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf2") }, {"long_answer": "El boletín incluye algunos indicadores en desarrollo para los que todavía no se dispone de datos, como el porcentaje de personas con trastorno por uso de sustancias que presentan antecedentes de otro trastorno de salud mental (patología dual). Por eso la respuesta correcta es que el dato no está disponible aún. Las cifras del 50%, el 30% y el 10% no proceden del informe, aunque la comorbilidad psiquiátrica en estos pacientes sea frecuente según otras fuentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cfe") }, {"long_answer": "GuíaSalud es el organismo del Sistema Nacional de Salud dedicado a promover la toma de decisiones clínicas basadas en la evidencia, mediante la elaboración, difusión, catálogo y registro de Guías de Práctica Clínica y la formación de profesionales en su elaboración y uso. No crea centros de atención al parto, no financia tecnologías para la maternidad y no desarrolla campañas de vacunación perinatal, que corresponden a otras estructuras sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cff") }, {"long_answer": "El Plan de Calidad para el Sistema Nacional de Salud es un conjunto de estrategias y medidas destinadas a garantizar una atención sanitaria de calidad, segura y homogénea a todos los ciudadanos, con independencia de su lugar de residencia, e incluye entre otras la elaboración de Guías de Práctica Clínica. No es un plan limitado a las infraestructuras hospitalarias, ni un protocolo único para el parto asistido, ni un programa informático para registrar nacimientos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1b") }, {"long_answer": "Según la guía, cuando los hemocultivos se extraen a través de un catéter venoso central no se recomienda desechar la sangre inicial, ya que esa primera muestra es la más representativa de la colonización del catéter y no hay evidencia de que descartarla reduzca la contaminación. Por tanto, no es necesario desechar 5-10 ml, la antigüedad del catéter no modifica esta recomendación y la opción que sugiere mezclar la muestra no responde a lo que se plantea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1d") }, {"long_answer": "En adultos, el lugar más adecuado para extraer hemocultivos es la venopunción periférica en la vena antecubital de la extremidad superior, por su accesibilidad, buen calibre y menor riesgo de contaminación. La vena femoral se asocia a mayor riesgo de contaminación por la flora de la zona inguinal y se reserva para casos sin otro acceso, el cuero cabelludo es un acceso propio de lactantes y las venas dorsales de la mano son más finas y dificultan obtener el volumen adecuado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d20") }, {"long_answer": "Ante la sospecha de infección, el momento ideal para extraer los hemocultivos es antes de iniciar el tratamiento antibiótico, ya que los antimicrobianos reducen la probabilidad de aislar el microorganismo y aumentan los falsos negativos. Extraerlos durante la administración del antibiótico disminuye su rentabilidad, la administración de antipiréticos no es un criterio para programar la extracción y no es indiferente el momento, ya que lo prioritario es extraerlos lo antes posible y antes del antibiótico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d21") }, {"long_answer": "En pacientes graves no es necesario esperar 20 o 30 minutos entre la primera y la segunda extracción: los hemocultivos pueden obtenerse de forma simultánea o con un intervalo corto, siempre en puntos de punción diferentes, para no retrasar el inicio del tratamiento antibiótico. Esperar sistemáticamente 20 o 30 minutos no mejora de forma relevante el rendimiento diagnóstico, y sí se recomienda extraer más de un hemocultivo, habitualmente dos parejas, para mejorar la sensibilidad y la interpretación de los resultados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d30") }, {"long_answer": "El Real Decreto 1029/2022, que traspone la Directiva 2013/59/Euratom, establece un nivel de referencia de 300 Bq/m³ para la concentración media anual de radón en recintos cerrados, tanto en viviendas como en lugares de trabajo; por encima de él se considera necesario adoptar medidas de reducción. Los 100 Bq/m³ son el valor que la OMS propone como deseable, 200 Bq/m³ no es el nivel de referencia de la norma española y 600 Bq/m³ corresponde a un antiguo nivel de acción para viviendas existentes en algunos países."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d33") }, {"long_answer": "La exposición conjunta a radón y tabaco tiene un efecto sinérgico (supraaditivo) sobre el riesgo de cáncer de pulmón: el riesgo combinado es mayor que la suma de los riesgos individuales, de modo que los fumadores expuestos a radón tienen un riesgo absoluto mucho más elevado. Por tanto, el riesgo sí se modifica, no se reduce por actuar en vías distintas y el aumento no se limita a los fumadores activos, ya que el radón también es la principal causa de cáncer de pulmón en personas que nunca han fumado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d34") }, {"long_answer": "Los análisis agrupados de estudios europeos de casos y controles muestran que el riesgo de cáncer de pulmón aumenta aproximadamente un 16% por cada 100 Bq/m³ de radón residencial, una vez corregida la incertidumbre en la medición de la exposición; sin esa corrección el incremento estimado es de alrededor del 8%. Las cifras de 5%, 11% y 13% no corresponden al valor que cita el Plan, y el aumento se considera lineal y sin umbral, incluso por debajo del nivel de referencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3b") }, {"long_answer": "El objetivo principal del Plan Nacional contra el Radón es proteger la salud de la población general y de las personas trabajadoras frente a los riesgos derivados de la exposición al radón en recintos cerrados, reduciendo dicha exposición y, con ella, el riesgo de cáncer de pulmón. No se centra únicamente en las fuentes naturales, no busca prohibir materiales de construcción y no pretende eliminar totalmente la exposición, algo imposible porque el radón es un gas natural presente en todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d42") }, {"long_answer": "El Comité del Plan Nacional contra el Radón constituye un grupo de trabajo técnico cuya función es elaborar, debatir y preparar propuestas que después se someten a la consideración y aprobación del propio Comité. Este grupo no se encarga de realizar mediciones de campo, que corresponden a laboratorios y servicios acreditados, ni de recaudar fondos para investigación, ni de supervisar la edificación en zonas de riesgo, que es competencia de las administraciones con funciones en materia de vivienda y urbanismo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d43") }, {"long_answer": "La sección HS6 del Documento Básico de Salubridad del Código Técnico de la Edificación obliga a incorporar medidas de protección frente al radón en los edificios situados en municipios con alto potencial de radón, clasificados en zona I o zona II según su potencial geogénico, con soluciones más exigentes en zona II, como barreras y espacios de contención ventilados o despresurización del terreno. El criterio no es el número de plantas, el uso industrial ni la existencia de ventilación mecánica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d44") }, {"long_answer": "Los ejes estratégicos del Plan Nacional contra el Radón abordan ámbitos relacionados con la exposición al radón, como la edificación, la comunicación y concienciación de la población y los profesionales y las zonas de actuación prioritaria, además de los lugares de trabajo y la investigación. El uso de pesticidas en la agricultura no guarda relación con el radón, que es un gas radiactivo natural procedente de la desintegración del uranio del terreno, por lo que no forma parte de los ejes del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4b") }, {"long_answer": "Según el Plan Nacional contra el Radón, aproximadamente el 17% del territorio nacional se incluye en zonas de actuación prioritaria, es decir, áreas en las que se estima que un porcentaje significativo de edificios supera el nivel de referencia de 300 Bq/m³ y en las que deben concentrarse las medidas de medición y reducción. Los porcentajes del 5%, 12% y 25% no corresponden al dato recogido en el Plan, elaborado a partir del mapa de potencial de radón del Consejo de Seguridad Nuclear."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4e") }, {"long_answer": "Según la OMS, las enfermedades bucodentales afectan a cerca de 3.500 millones de personas en el mundo, aproximadamente el 45% de la población mundial, lo que las convierte en las enfermedades no transmisibles más prevalentes, siendo la caries no tratada en dientes permanentes la más frecuente. Las cifras del 20%, el 60% y el 10% no corresponden a la estimación que recoge el plan de ampliación de la cartera de salud bucodental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d51") }, {"long_answer": "Según la encuesta del Ministerio de Sanidad a las comunidades autónomas recogida en el plan de ampliación de la cartera de salud bucodental, en las comunidades con modelo mixto, que combinan la atención en centros públicos con la provisión por dentistas privados habilitados mediante capitación, el importe medio anual por niño atendido fue de 53,4 euros. Las cifras de 41,87, 65,3 y 30,74 euros no corresponden al importe medio que recoge el documento para este modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d53") }, {"long_answer": "Según los datos de la Encuesta de Presupuestos Familiares de 2019 recogidos en el plan de ampliación de la cartera de salud bucodental, el gasto privado total de los hogares españoles en servicios dentales fue de aproximadamente 3.047 millones de euros, una cifra muy elevada que pone de manifiesto que la mayor parte de la atención dental en España se financia directamente por las familias. Las demás cifras son muy inferiores y no corresponden al gasto total en servicios dentales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d56") }, {"long_answer": "Para estimar el coste anual de la ampliación de la cartera común de salud bucodental, el documento asume una cobertura del 70% del colectivo diana, ya que no toda la población con derecho a las prestaciones acude a utilizarlas. Una cobertura del 100% sobreestimaría el gasto, y los porcentajes del 50% y el 40% no corresponden al supuesto adoptado en el plan para el cálculo del impacto económico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d59") }, {"long_answer": "La ampliación de la cartera común de servicios de salud bucodental incluye prestaciones preventivas y asistenciales, como la aplicación de flúor tópico, el sellado de fosas y fisuras, las obturaciones y el tratamiento de traumatismos dentales, pero no incluye la ortodoncia con carácter general, salvo en situaciones muy concretas como las maloclusiones derivadas de malformaciones craneofaciales. Por eso las ortodoncias son la opción que no forma parte de la ampliación, mientras que las demás opciones sí están incluidas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5f") }, {"long_answer": "En el modelo mixto de atención dental infantil, en el que intervienen dentistas privados habilitados, la financiación se realiza principalmente mediante un pago por capitación, es decir, un importe anual fijo por cada persona atendida o asignada, que cubre el conjunto de prestaciones incluidas, complementado en algunos casos con pagos por acto para tratamientos especiales. No es un pago único por tratamiento completo, ni un pago mensual por equipo, ni un pago ligado solo a las exodoncias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d63") }, {"long_answer": "Según el análisis de las prestaciones de las comunidades autónomas recogido en el plan, la ortodoncia se facilita a colectivos específicos, como las personas con discapacidad física o psíquica y las personas con maloclusión secundaria a malformaciones craneofaciales, y no se ofrece a la población general. No se limita a toda la población infantojuvenil ni a los mayores de 65 años, y no se presta a la población general sin problemas específicos, por lo que las demás opciones no se ajustan al documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d65") }, {"long_answer": "Según el documento, la propuesta definitiva para la ampliación de la cartera común de servicios de salud bucodental fue aprobada por el Consejo Interterritorial del SNS en diciembre de 2021, lo que permitió iniciar su implantación progresiva en las comunidades autónomas con financiación específica. Las fechas de enero, julio u octubre de 2021 no corresponden a la aprobación definitiva de la propuesta en el CISNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d71") }, {"long_answer": "El riesgo para el pulmón no procede tanto del propio radón inhalado, que se exhala en gran parte, sino de sus descendientes de vida corta, especialmente el polonio-218 y el polonio-214, que se depositan en el epitelio bronquial y emiten partículas alfa de alta energía capaces de dañar el ADN de las células. El uranio-238 y el radio-226 son precursores del radón y no actúan así sobre el epitelio, y el plomo-210 no libera neutrones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d72") }, {"long_answer": "La concentración de radón en el interior de los edificios depende sobre todo de las características geológicas del terreno sobre el que se asientan, en particular de su contenido en uranio-238 (como en los terrenos graníticos) y de su permeabilidad, ya que el radón procede de la desintegración de este elemento. La antigüedad del edificio, el tipo de ventanas, los materiales de construcción o la presencia de sótanos influyen en la entrada y acumulación del gas, pero son factores secundarios frente al sustrato geológico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d73") }, {"long_answer": "Según el Libro del Radón, en España se estima que aproximadamente el 4% de la mortalidad por cáncer de pulmón es atribuible a la exposición al radón en el hogar, lo que convierte al radón en la segunda causa de cáncer de pulmón después del tabaco y en la primera en personas que nunca han fumado. Las cifras del 7%, el 10% y el 25% no corresponden a la estimación nacional recogida en el documento, aunque en zonas de alto potencial la fracción atribuible es mayor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d74") }, {"long_answer": "Los estudios de cohortes en mineros de uranio mostraron una relación dosis-respuesta lineal entre la exposición acumulada al radón y el riesgo de cáncer de pulmón, sin un umbral por debajo del cual el riesgo desaparezca, de modo que el riesgo aumenta incluso a niveles bajos de exposición. Sí se encontró una relación estadísticamente significativa, el riesgo no depende de la radiación gamma, ya que se debe a las partículas alfa, y aunque el tabaco lo potencia, el riesgo también aparece en mineros no fumadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d79") }, {"long_answer": "Según el estudio de 2019 en lugares de trabajo en España recogido en el Libro del Radón, los sectores de salud y educación presentaron las mayores concentraciones medianas de radón, probablemente por ocupar con frecuencia edificios antiguos, plantas bajas y con ventilación limitada en zonas de alto potencial. Los sectores turístico, financiero, administrativo y de distribución eléctrica mostraron concentraciones medianas inferiores en dicho estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7d") }, {"long_answer": "Según el protocolo de vigilancia sanitaria, los trabajadores expuestos al radón se clasifican como categoría A cuando pueden recibir una dosis efectiva superior a 6 mSv al año y como categoría B cuando la dosis anual efectiva es inferior a 6 mSv pero superior al límite de dosis para el público. Por tanto, una dosis inferior a 6 mSv corresponde a categoría B. La categoría C no existe en esta clasificación, y decir no clasificado no se ajusta a un trabajador considerado expuesto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7e") }, {"long_answer": "El radón penetra en los edificios principalmente desde el terreno a través de grietas y fisuras en cimientos, soleras y muros en contacto con el suelo, así como por juntas y pasos de instalaciones, impulsado por la diferencia de presión entre el interior y el subsuelo. La ventilación mecánica bien diseñada ayuda a reducir su concentración, las paredes exteriores y los techos no están en contacto con la fuente principal y las piscinas o fuentes interiores no son una vía relevante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8a") }, {"long_answer": "El historial dosimétrico registra las dosis recibidas y acumuladas por cada trabajador expuesto a radón, lo que permite identificar a las personas expuestas, clasificarlas y planificar su vigilancia sanitaria, además de conservar la información a largo plazo dado el periodo de latencia del cáncer de pulmón. No es un simple trámite administrativo sin implicación clínica, se refiere a la exposición laboral y no a la residencial, y su existencia es obligatoria según la normativa de protección radiológica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8c") }, {"long_answer": "El cribado de cáncer de pulmón con tomografía computarizada de baja dosis en trabajadores expuestos a radón plantea la dificultad de equilibrar el beneficio de detectar precozmente el cáncer con los riesgos del cribado, entre ellos la exposición adicional a radiación ionizante, además de los falsos positivos y el sobrediagnóstico. El coste no es muy bajo, sí existe la tecnología necesaria, y no se trata de un procedimiento obligatorio para todos los trabajadores, sino de una estrategia que debe valorarse individualmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8e") }, {"long_answer": "En el contexto europeo, se considera zona propensa al radón (radon-prone area) aquella en la que se estima que más del 10% de las viviendas supera el nivel de referencia de 300 Bq/m³ de concentración media anual. Un umbral del 5%, del 50% o inferior al 1% no corresponde a este criterio. En España, estas zonas se identifican a partir del mapa de potencial de radón y son las que requieren actuaciones prioritarias de medición y protección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d58") }, {"long_answer": "La propuesta aprobada para la ampliación de la cartera común de salud bucodental prioriza la población infantojuvenil de 0 a 14 años inclusive, extendiendo las prestaciones a edades que antes no estaban cubiertas de forma homogénea, como la franja de 0 a 5 años. No se limita exclusivamente a los 0-5 años, y los intervalos de 6 a 15 y de 7 a 16 años no corresponden al rango de edad definido en el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d5e") }, {"long_answer": "Según el análisis de las prestaciones de las comunidades autónomas recogido en el plan, los tratamientos bajo sedación por falta de autocontrol se ofrecen a las personas con discapacidad que no pueden colaborar en la atención bucodental convencional, sin limitarse a la población infantil. Las personas adultas con enfermedad periodontal o los pacientes con cáncer cervicofacial reciben otras prestaciones específicas y no son el grupo destinatario de esta atención con sedación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d62") }, {"long_answer": "Para estimar el coste de la ampliación en las personas con discapacidad intelectual, el plan utiliza el 100% del gasto medio por persona como referencia, sin aplicar reducciones, dadas sus mayores necesidades de atención bucodental y la frecuente necesidad de técnicas especiales. Los porcentajes del 40%, el 70% y el 2% no corresponden al criterio que recoge el documento para este colectivo; el 70% es la cobertura que se asume para la población diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d66") }, {"long_answer": "El plan señala que uno de los principales obstáculos para conocer el gasto real en salud bucodental de las comunidades autónomas es la insuficiencia de sus sistemas de información, que no siempre permiten desagregar ese gasto ni obtener datos completos y comparables. No se atribuye a la falta de interés de las comunidades, ni a un exceso de recursos humanos, y la protección de datos no impide el acceso a información agregada de gasto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6c") }, {"long_answer": "Según las estimaciones económicas del plan de ampliación de la cartera común de salud bucodental, el gasto estimado por niño atendido en la cohorte de 0 a 5 años es de 21,36 euros, inferior al de otras edades porque las prestaciones en esta franja son sobre todo preventivas y de menor complejidad. La cifra de 53,40 euros corresponde al importe medio por niño en el modelo mixto, y los valores de 37,38 y 10 euros no corresponden a este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d75") }, {"long_answer": "Una limitación frecuente de los estudios en mineros para estimar el riesgo de cáncer de pulmón por radón es la falta de un ajuste adecuado por el consumo de tabaco, ya que en muchas cohortes la información sobre tabaquismo es incompleta, pese a ser el principal factor de confusión e interacción. Estos estudios sí estiman la exposición al radón, disponen de comparaciones internas o externas y no incluyen solo mujeres; de hecho, los mineros eran casi exclusivamente varones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d7f") }, {"long_answer": "La interacción entre el consumo de tabaco y la exposición a radón es sinérgica: el riesgo combinado de cáncer de pulmón es mayor que la suma de ambos riesgos por separado, por lo que los fumadores expuestos a radón presentan el riesgo absoluto más alto y se benefician especialmente de dejar de fumar y de reducir la exposición. El riesgo no se mantiene igual, no disminuye en fumadores y la interacción no se limita a los exfumadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d89") }, {"long_answer": "Según los datos recientes recogidos en el Libro del Radón, aproximadamente un 20% de los puestos de trabajo medidos en zonas de alto potencial de radón en España superan el nivel de referencia de 300 Bq/m³, lo que justifica las obligaciones de medición y reducción en estos lugares. Las cifras del 5% y el 50% no corresponden al dato publicado, y no es cierto que no se hayan detectado superaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d90") }, {"long_answer": "En los edificios con sótano, los muros de este en contacto con el terreno constituyen una vía adicional de entrada del radón por difusión y por las grietas y juntas, lo que explica que las concentraciones más elevadas suelan registrarse en sótanos y plantas bajas. Las ventanas abiertas favorecen la ventilación y reducen la concentración, los conductos de ventilación mecánica bien diseñados no son una vía de entrada y los materiales sintéticos no aportan radón de forma relevante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d96") }, {"long_answer": "La asociación entre exposición residencial a radón y cáncer de pulmón está respaldada principalmente por estudios de casos y controles con mediciones directas de radón en las viviendas, cuyos análisis agrupados en Europa, Norteamérica y China confirman un aumento lineal del riesgo. Los estudios ecológicos sin mediciones individuales están sujetos a sesgos, los ensayos clínicos aleatorizados no son éticamente viables para una exposición cancerígena y los estudios transversales con encuestas no permiten establecer esta relación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d99") }, {"long_answer": "En la desfibrilación de doble secuencia, las dos descargas, procedentes de dos desfibriladores diferentes, deben administrarse de forma secuencial y muy próxima en el tiempo, con un intervalo inferior a 1 segundo entre ambos pulsos, para que el miocardio reciba los dos vectores de corriente antes de recuperarse. Un intervalo de hasta 5 segundos o de exactamente 2 segundos superaría ese límite, y sí existe un límite de tiempo, ya que la técnica pierde su sentido si las descargas se separan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9a") }, {"long_answer": "La desfibrilación de doble secuencia requiere dos desfibriladores y dos juegos de parches, ya que se aplican dos descargas secuenciales con vectores diferentes: un juego en posición anterolateral y otro en posición anteroposterior. Con un solo monitor no es posible administrar dos descargas casi simultáneas, y un único juego de electrodos no permite cambiar el vector de la corriente, por lo que las demás combinaciones no permiten realizar la técnica correctamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9c") }, {"long_answer": "Durante las tres primeras descargas estándar, en posición anterolateral, el parche identificado como bajo la mamila izquierda se coloca en el lado izquierdo del tórax, en la línea axilar a la altura del quinto espacio intercostal, con la orientación que indica el protocolo, mientras que el otro parche se sitúa bajo la clavícula derecha. La posición paraesternal izquierda en vertical, la zona infraescapular y la región supraclavicular corresponden a otras colocaciones y no a la del parche apical en la configuración estándar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9e") }, {"long_answer": "En la desfibrilación de doble secuencia, el operador que controla ambos monitores debe avisar en voz alta al equipo de que se van a administrar dos descargas seguidas, comprobar que nadie está en contacto con el paciente y pulsar los botones de descarga de forma secuencial, con un intervalo aproximado de 1 segundo o inferior. Pulsar sin avisar compromete la seguridad del equipo, esperar 5 segundos entre ambas descargas anula el efecto buscado y usar un solo botón no permite realizar la técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da6") }, {"long_answer": "La desfibrilación de doble secuencia se emplea en la fibrilación ventricular o taquicardia ventricular sin pulso refractarias a las descargas estándar, con el objetivo de terminar la arritmia y lograr la recuperación de la circulación espontánea. No es una técnica preventiva de la fibrilación ventricular inicial, no tiene finalidad de mejorar el registro electrocardiográfico y no guarda relación con la intubación orotraqueal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da9") }, {"question": "¿Cuál es el intervalo aproximado que debe existir entre las dos descargas en la DDS?", "long_answer": "En la desfibrilación de doble secuencia, las dos descargas se administran de forma secuencial con un intervalo muy corto, de aproximadamente 1 segundo o inferior, entre el disparo del primer y del segundo desfibrilador, para que ambos vectores actúen sobre el miocardio casi a la vez sin que coincidan exactamente. Un intervalo cercano a 5 segundos o de 10 segundos sería excesivo y restaría eficacia a la técnica, y el protocolo sí especifica el intervalo que debe respetarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db0") }, {"option_2": "Continuar la RCP según el algoritmo de ritmos no desfibrilables, sin aplicar DDS", "option_4": "Administrar amiodarona y aplicar una descarga estándar adicional", "long_answer": "La desfibrilación, estándar o de doble secuencia, solo está indicada en ritmos desfibrilables, es decir, fibrilación ventricular o taquicardia ventricular sin pulso. Si tras tres descargas estándar el paciente presenta un ritmo no desfibrilable, no se aplica DDS, sino que se continúa la reanimación según el algoritmo de ritmos no desfibrilables (compresiones, ventilación, adrenalina y búsqueda de causas reversibles). No se debe suspender la RCP por este motivo ni administrar una descarga adicional, ya que no existe ritmo susceptible de desfibrilación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db3") }, {"long_answer": "En la desfibrilación de doble secuencia, el segundo monitor se conecta a un juego de parches en posición anteroposterior: el parche identificado como bajo la clavícula derecha se coloca en la espalda, bajo la escápula izquierda, en posición vertical, mientras que el otro se sitúa en la región paraesternal izquierda anterior. Así se crea un vector de corriente distinto al de los parches anterolaterales del primer monitor. Las posiciones infraclavicular derecha, paraesternal o en la línea media no corresponden a este parche."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db6") }, {"long_answer": "El uso poblacional de nirsevimab en lactantes, recomendado en España durante la temporada 2024-2025, tiene como objetivo prevenir la enfermedad de las vías respiratorias inferiores causada por el virus respiratorio sincitial, principal causa de bronquiolitis y de hospitalización en menores de un año. Es un anticuerpo monoclonal de acción prolongada que proporciona inmunización pasiva, no una vacuna, no tiene utilidad terapéutica en infecciones ya establecidas, no se dirige a la transmisión en adultos y no actúa frente a la gripe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dbf") }, {"long_answer": "Para la temporada 2024-2025, la recomendación en España es inmunizar con nirsevimab a toda la población infantil diana, independientemente de que la madre haya recibido o no la vacuna frente al VRS durante el embarazo, ya que la estrategia se basa en la protección directa del lactante con el anticuerpo monoclonal. Por eso no se limita a los hijos de madres no vacunadas, no se contraindica por la vacunación materna y no se restringe a los prematuros."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc0") }, {"long_answer": "Para la administración de nirsevimab se utiliza la edad cronológica, es decir, el tiempo transcurrido desde el nacimiento, con independencia de la edad gestacional, también en los prematuros, a diferencia de otras situaciones en las que se emplea la edad corregida. La edad corregida a 40 semanas, la edad gestacional al nacer o el tiempo transcurrido desde el alta hospitalaria no son el criterio de referencia para definir la población diana y la pauta del anticuerpo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc2") }, {"question": "En un niño de 11 kg en su segunda temporada de VRS sometido a cirugía cardiaca con circulación extracorpórea en los 90 días siguientes a recibir nirsevimab, ¿qué dosis adicional debe administrarse?", "long_answer": "En los niños sometidos a cirugía cardiaca con circulación extracorpórea se elimina parte del nirsevimab durante el bypass, por lo que se recomienda una dosis adicional en cuanto estén estables. En la segunda temporada, si la cirugía ocurre en los 90 días siguientes a la dosis, la dosis adicional se ajusta al peso: 100 mg si pesa menos de 10 kg y 200 mg, en dos inyecciones de 100 mg, si pesa 10 kg o más. Por tanto, a un niño de 11 kg le corresponden 200 mg. Los 100 mg serían adecuados con menos de 10 kg o pasados 90 días, los 50 mg son propios de la primera temporada y no administrar dosis adicional lo dejaría sin protección adecuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc5") }, {"long_answer": "En los prematuros de menos de 29 semanas de edad gestacional, el documento indica que se dispone de datos de seguridad y farmacocinética de nirsevimab, aunque no de datos de eficacia específicos en ese grupo, pese a lo cual se recomienda su administración por ser una población de alto riesgo de enfermedad grave por VRS. No existen amplios datos de eficacia sin seguridad, sí hay recomendación para este grupo y no se limita a la administración tras el alta hospitalaria, ya que puede administrarse durante el ingreso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc9") }, {"long_answer": "Según el documento de actualización sobre nirsevimab, durante la temporada 2023-2024 se administraron en España más de 277.000 dosis, con coberturas elevadas en la población diana de lactantes, lo que permitió evaluar su impacto poblacional. Las cifras de alrededor de 100.000, cerca de 50.000 o menos de 10.000 dosis no corresponden al volumen administrado en la primera temporada de uso poblacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd4") }, {"long_answer": "Tras la introducción de nirsevimab en la temporada 2023-2024, los estudios realizados en España observaron una reducción significativa, de aproximadamente el 71-77%, de las hospitalizaciones por VRS en menores de un año, con descensos también en los ingresos en UCI. No se ha observado un aumento de infecciones por otros virus atribuible al anticuerpo, ni un aumento de complicaciones respiratorias, y sí hubo cambios relevantes en las hospitalizaciones por VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dd5") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería define el cuidado profesional enfermero como el conjunto de acciones que realizan las enfermeras con autonomía y responsabilidad, basadas en conocimientos científicos, para promover, mantener y recuperar la vida y la salud de las personas. Por eso no son acciones sin fundamento científico, no se limitan a los cuidados visibles, ya que incluyen dimensiones relacionales y educativas, y no se restringen al ámbito hospitalario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de1") }, {"long_answer": "El Marco Estratégico señala que la retención y fidelización de enfermeras y técnicos en cuidados auxiliares de enfermería en el SNS depende de mejorar sus condiciones laborales, gestionar adecuadamente las cargas de trabajo, reforzar el liderazgo, favorecer la conciliación y ofrecer oportunidades de desarrollo profesional. Ofrecer solo formación sin cambios laborales es insuficiente, aumentar las horas de trabajo empeoraría el agotamiento y reducir las plazas de formación agravaría el déficit de profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de5") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería señala que, en una profesión mayoritariamente feminizada como la de enfermeras y TCAE, una problemática destacada es la elevada frecuencia de agresiones contra mujeres profesionales en el ámbito asistencial, especialmente en consultas, lo que exige incorporar la perspectiva de género en las medidas de prevención y protección. La escasa representación femenina es falsa, ya que la profesión está muy feminizada. Tampoco se describe un mayor salario para las mujeres, sino más bien desigualdades en su contra, ni la falta de formación específica por género como problema central."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de9") }, {"long_answer": "El documento recoge la evidencia de que unas dotaciones adecuadas de enfermeras se asocian a menos eventos adversos, menor mortalidad y mayor seguridad y calidad de los cuidados, por lo que la ratio enfermera-paciente es un determinante de los resultados en salud. Afirmar que más enfermeras aumentan la mortalidad es lo contrario de lo demostrado. Decir que la dotación no influye en la calidad asistencial contradice la literatura citada, y sostener que solo incrementa costes sin mejorar la atención ignora el beneficio en seguridad del paciente y eficiencia por reducción de complicaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dea") }, {"long_answer": "Entre las propuestas del Marco Estratégico para facilitar la incorporación de las enfermeras recién graduadas figura la implantación de programas de mentoría, en los que profesionales con experiencia acompañan a las noveles, favorecen su adaptación, reducen la ansiedad y el abandono temprano y refuerzan la seguridad del paciente. Eliminar la supervisión iría en sentido contrario, aumentando el riesgo de errores. Reducir la formación práctica para acelerar la inserción laboral empeoraría la preparación, y aumentar la carga de trabajo como método de adaptación incrementaría el estrés y el desgaste profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df1") }, {"long_answer": "El Marco Estratégico considera que incorporar la perspectiva de género en las profesiones de cuidados contribuye a alcanzar una igualdad real, a mejorar las condiciones laborales y a reducir las desigualdades que afectan a un colectivo mayoritariamente femenino, como la brecha en el acceso a puestos de gestión o la conciliación. No es irrelevante, ya que influye directamente en el desarrollo profesional y la calidad asistencial. Tampoco pretende limitar la elección profesional a las mujeres, sino lo contrario, ni se plantea como un recurso propagandístico sin impacto real."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df4") }, {"long_answer": "Entre los resultados de las líneas estratégicas orientadas a la visibilidad de los cuidados se recoge la creación de un espacio en la web del Ministerio de Sanidad dedicado al Comité de Cuidados en Salud, que facilite la transparencia y la difusión de sus actividades y documentos. Reducir la información al público iría en contra del objetivo de visibilidad. Evitar la publicidad de actividades para ahorrar costes y delegar toda la comunicación en entidades privadas tampoco se proponen, ya que la difusión institucional es precisamente una herramienta para el reconocimiento de la profesión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df7") }, {"long_answer": "En el cáncer de cuello uterino en estadio inicial de muy bajo riesgo (tumores pequeños, sin invasión linfovascular y con escasa infiltración estromal), la guía recomienda reducir la radicalidad quirúrgica y realizar una histerectomía tipo A de la clasificación de Querleu-Morrow, es decir, una histerectomía extrafascial sin resección significativa de parametrios. Las histerectomías tipo B1 y B2 implican una resección parcial del paracérvix y se reservan para riesgos mayores, mientras que la tipo C2 es una histerectomía radical completa sin preservación nerviosa, indicada en tumores de mayor riesgo, y supondría un sobretratamiento con más morbilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dfa") }, {"long_answer": "Para los procedimientos radicales que incluyen exéresis del parametrio, la guía recomienda el abordaje por laparotomía, ya que los ensayos comparativos (como el estudio LACC) demostraron peor supervivencia libre de enfermedad y global con la cirugía mínimamente invasiva en la histerectomía radical por cáncer de cuello uterino. Por ello, la cirugía laparoscópica y la robótica no se recomiendan de forma general en este contexto, salvo en estudios o situaciones muy seleccionadas. El abordaje vaginal no permite una exéresis parametrial radical con garantías oncológicas equivalentes y no es la técnica de elección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dfd") }, {"long_answer": "La radioterapia de intensidad modulada (IMRT) o en arco volumétrico (VMAT), combinada con radioterapia guiada por la imagen (IGRT), permite conformar con gran precisión la dosis al volumen tumoral y verificar la posición en cada sesión, de modo que se reduce la irradiación de órganos sanos como recto, vejiga o intestino y, con ello, la toxicidad aguda y tardía. No acelera ningún tratamiento quirúrgico ni sustituye a la braquiterapia, que sigue siendo imprescindible en el tratamiento radical del cáncer de cérvix. Tampoco permite administrar todo el tratamiento en un solo día, ya que se mantiene el fraccionamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dff") }, {"long_answer": "Tras un tratamiento preservador de la fertilidad en el cáncer de cuello uterino, la determinación del VPH forma parte del seguimiento porque permite detectar de forma precoz la persistencia de la infección y la aparición de nuevas lesiones relacionadas con el virus en el cérvix residual o la vagina, combinándose con la citología. Afirmar que no está indicada en ningún caso es incorrecto, puesto que la guía la incluye en el seguimiento. Limitarla a la presencia de síntomas vaginales le restaría su valor de cribado, y desaconsejarla por baja sensibilidad es falso, ya que la prueba de VPH es muy sensible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e02") }, {"long_answer": "En el cáncer de cuello uterino metastásico o recurrente no candidato a tratamiento local radical, el tratamiento sistémico inicial recomendado es la quimioterapia basada en platino combinada con un taxano (paclitaxel) y bevacizumab, esquema que demostró aumentar la supervivencia global; actualmente puede añadirse inmunoterapia en tumores PD-L1 positivos. La radioterapia externa exclusiva tiene un papel paliativo o local, pero no es el tratamiento sistémico de elección. La cirugía paliativa aislada no controla la enfermedad diseminada, y la inmunoterapia sin quimioterapia no es la pauta estándar de primera línea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e05") }, {"long_answer": "En la estadificación del cáncer de cuello uterino, cuando existe afectación ganglionar (estadio IIIC) se añade la letra r o p para indicar el método con el que se ha documentado: r cuando la evidencia procede de pruebas de imagen (radiológica) y p cuando hay confirmación anatomopatológica. Esta anotación no expresa el tamaño tumoral, que se refleja en los subestadios según los centímetros de la lesión. Tampoco indica el tratamiento recibido ni distingue entre carcinomas escamosos y adenocarcinomas, que se describen en el informe histológico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e08") }, {"long_answer": "Si el ganglio centinela resulta positivo en el estudio intraoperatorio, la guía recomienda abandonar la cirugía uterina radical y valorar una estadificación paraaórtica para delimitar los campos de radioterapia, ya que la paciente precisará radioquimioterapia y la combinación de cirugía radical más radioterapia aumenta mucho la morbilidad sin mejorar la supervivencia. Continuar la histerectomía radical planificada expondría a esa doble toxicidad. Completar de inmediato la linfadenectomía pélvica no aporta beneficio terapéutico, e iniciar quimioterapia exclusiva sin más estadificación no es la conducta recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e09") }, {"long_answer": "Cuando la colposcopia no permite valorar la profundidad de la infiltración estromal ante la sospecha de un cáncer cervical, especialmente en lesiones microinvasivas, el método recomendado es la conización o escisión local diagnóstica, que proporciona una pieza íntegra para que el patólogo mida la invasión y valore los márgenes. Repetir citologías no evalúa la infiltración del estroma. La biopsia por legrado aleatorio aporta fragmentos sin orientación que impiden medir la profundidad, y la tomografía computarizada abdominal sirve para la extensión a distancia, no para valorar la invasión estromal microscópica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e0f") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado tratado con radioquimioterapia y braquiterapia, la histerectomía de complemento no está recomendada cuando se obtiene respuesta completa, porque no ha demostrado mejorar la supervivencia y aumenta la morbilidad. Realizarla sistemáticamente para mejorar la supervivencia carece de respaldo. Los tumores T1a no se tratan con radioquimioterapia como enfermedad localmente avanzada, por lo que esa opción no procede, y tampoco existe recomendación de diferir la cirugía más de 12 semanas tras finalizar el tratamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e10") }, {"long_answer": "En la enfermedad metastásica o recurrente del cáncer de cérvix, el ensayo GOG 240 demostró que añadir bevacizumab a la quimioterapia con cisplatino y paclitaxel aumentaba de forma significativa la supervivencia global, por lo que esta combinación se convirtió en el estándar de primera línea. El carboplatino con 5-fluorouracilo no es el esquema que mostró ese beneficio. La monoterapia con paclitaxel es menos eficaz que los dobletes con platino, y la combinación de cisplatino con doxorrubicina no forma parte de las pautas recomendadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e11") }, {"long_answer": "La guía recomienda integrar de forma temprana los cuidados paliativos desde el diagnóstico de enfermedad avanzada, mediante un enfoque multidisciplinar y en paralelo con el tratamiento oncológico, porque mejora el control de síntomas, la calidad de vida y la toma de decisiones compartida. Reservarlos para los últimos días de vida supone una visión obsoleta de los paliativos. Limitarlos al fracaso del tratamiento quirúrgico o a que la paciente los solicite retrasaría una intervención que debe ofrecerse de manera proactiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e16") }, {"long_answer": "La sobreexpresión inmunohistoquímica de p16 es un marcador subrogado de la infección por VPH de alto riesgo, presente en la mayoría de los cánceres de cuello uterino, y permite distinguir los carcinomas asociados al VPH de los independientes del VPH, según la clasificación actual de la OMS. EGFR no se utiliza para diferenciar los subtipos histológicos cervicales. La ausencia de CEA no caracteriza a estos tumores, y HER2 se expresa solo en una pequeña proporción, sin utilidad para clasificar la mayoría de los casos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e19") }, {"long_answer": "La escala de Bishop valora la madurez cervical antes de una inducción del parto mediante cinco parámetros: dilatación, borramiento, consistencia y posición del cuello uterino, y altura o encajamiento de la presentación fetal. Cada ítem puntúa y una puntuación alta indica un cuello favorable con mayor probabilidad de éxito de la inducción. La frecuencia cardiaca fetal y la duración de las contracciones se monitorizan durante el parto, pero no forman parte de esta escala. Los niveles hormonales y las constantes maternas como presión arterial, temperatura o glucemia tampoco se incluyen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e22") }, {"long_answer": "La escala de Tinetti es un instrumento de valoración del riesgo de caídas, sobre todo en personas mayores, que explora la marcha y el equilibrio tanto estático como dinámico mediante la observación de tareas como levantarse, permanecer de pie, girar o caminar; a menor puntuación, mayor riesgo. No evalúa la fuerza del suelo pélvico, que se valora con escalas como la de Oxford. La gravedad de la incontinencia urinaria se mide con cuestionarios como el ICIQ-SF, y la dificultad de intubación según la anatomía orofaríngea corresponde a la escala de Mallampati."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e27") }, {"long_answer": "La escala de Mallampati clasifica en cuatro grados la visibilidad de las estructuras orofaríngeas (paladar blando, úvula y pilares) con el paciente sentado, la boca abierta y la lengua protruida, y se utiliza para predecir la dificultad de la intubación orotraqueal: los grados III y IV se asocian a vía aérea difícil. No valora el riesgo de tromboembolismo venoso, para el que se usa por ejemplo la escala de Caprini. El dolor postquirúrgico se mide con escalas como la EVA o la numérica, y el estado funcional oncológico con Karnofsky o ECOG."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e29") }, {"long_answer": "La escala CRIES valora el dolor postoperatorio en neonatos mediante cinco parámetros (llanto, necesidad de oxígeno para saturación superior al 95 %, aumento de constantes vitales, expresión facial e insomnio), cada uno puntuado de 0 a 2, con un total máximo de 10. Una puntuación a partir de 4 se considera indicativa de dolor significativo que requiere intervención analgésica. Una puntuación de 2 se encuadra en el dolor leve o ausente. Los valores de 6 y 8 ya reflejan dolor moderado-intenso, pero no constituyen el umbral a partir del cual se considera dolor significativo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2b") }, {"long_answer": "La herramienta MUST (Malnutrition Universal Screening Tool) suma puntuaciones del índice de masa corporal, la pérdida de peso involuntaria en 3-6 meses y el efecto de enfermedad aguda con ingesta nula durante más de cinco días. Una puntuación total de 2 o más indica alto riesgo de malnutrición y obliga a iniciar tratamiento nutricional y derivar al equipo de nutrición. Una puntuación de 0 corresponde a bajo riesgo y de 1 a riesgo moderado o intermedio, por lo que las opciones de bajo riesgo, riesgo moderado y ausencia de riesgo no corresponden a valores iguales o superiores a 2."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e32") }, {"long_answer": "El PHQ-9 (Patient Health Questionnaire-9) es un cuestionario autoadministrado de nueve ítems que se corresponden con los nueve criterios diagnósticos del episodio depresivo mayor del DSM, y se utiliza para el cribado y la valoración de la gravedad de la depresión, con puntuación de 0 a 27. La ansiedad generalizada se explora con otro instrumento de la misma familia, el GAD-7. El trastorno obsesivo-compulsivo se valora con escalas como la Y-BOCS, y la adicción a sustancias con herramientas específicas como el AUDIT para el alcohol."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e34") }, {"long_answer": "El índice QUICKI (Quantitative Insulin Sensitivity Check Index) se calcula a partir de la glucemia y la insulinemia basales y es un complemento del índice HOMA para estimar la sensibilidad a la insulina; valores bajos indican resistencia insulínica. No mide el grado de obesidad, que se valora con el índice de masa corporal o el perímetro abdominal. La función renal se estima con el filtrado glomerular, y el daño hepático con transaminasas u otros índices específicos, no con QUICKI."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e35") }, {"long_answer": "El índice cintura-cadera (WHR) valora la distribución de la grasa abdominal. Según los criterios utilizados en España (SEEDO), un valor superior a 0,90 en mujeres indica obesidad abdominal y riesgo cardiovascular aumentado, mientras que en hombres el umbral es superior a 1; otras referencias internacionales, como la OMS, emplean puntos de corte más bajos. Un valor inferior a 0,85 o a 0,75 se considera dentro de la normalidad y no expresa un riesgo elevado. El valor de 0,88 no es un punto de corte del índice cintura-cadera, sino que recuerda a los 88 cm de perímetro de cintura en mujeres."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e36") }, {"long_answer": "El NAQ-R (Negative Acts Questionnaire-Revised) evalúa la frecuencia con la que el trabajador ha estado expuesto a conductas negativas asociadas al acoso psicológico laboral durante los últimos meses, sin necesidad de que la persona se identifique explícitamente como víctima, lo que reduce el sesgo de autopercepción. No es un instrumento diagnóstico de trastornos de ansiedad laboral. Tampoco mide la motivación para dejar de fumar, que se valora con el test de Richmond, ni el nivel de estrés físico, que no es objeto de este cuestionario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e39") }, {"long_answer": "La escala de Morse valora el riesgo de caídas en pacientes hospitalizados mediante seis ítems: antecedentes de caídas, diagnóstico secundario, ayuda para deambular, vía venosa, marcha y estado mental. Según la clasificación recogida en el documento, una puntuación inferior a 25 indica riesgo bajo, entre 25 y 45 riesgo moderado, y una puntuación igual o superior a 46 identifica alto riesgo de caídas, que exige medidas preventivas intensivas. El valor mayor de 20 no constituye un punto de corte de la escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3c") }, {"long_answer": "El sistema GRADE (Grading of Recommendations Assessment, Development and Evaluation) se utiliza para clasificar la calidad o certeza de la evidencia científica (alta, moderada, baja o muy baja) y la fuerza de las recomendaciones (fuerte o débil) en guías de práctica clínica y revisiones sistemáticas. No es una escala de dolor, como la EVA. Tampoco sirve para calcular puntuaciones en ensayos clínicos, cuya calidad metodológica se valora con herramientas como la escala de Jadad, ni para diagnosticar diabetes gestacional, que se basa en pruebas de sobrecarga oral de glucosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e41") }, {"long_answer": "Según la encuesta ESTUDES 2023, recogida en el boletín de indicadores clave del Plan Nacional sobre Drogas, alrededor del 56,6 % de los estudiantes de 14 a 18 años habían consumido alcohol en los últimos 30 días, lo que mantiene al alcohol como la sustancia psicoactiva más consumida por los adolescentes. Las cifras de 53,6 %, 58,5 % y 67 % no corresponden al dato de 2023: las dos primeras quedan próximas al rango de otras ediciones y la última es claramente superior a la prevalencia mensual registrada ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e47") }, {"long_answer": "Según la encuesta ESTUDES 2023, el 15,6 % de los estudiantes de 14 a 18 años consumió cannabis en los últimos 30 días, lo que lo sitúa como la droga ilegal más consumida entre los adolescentes, aunque con tendencia descendente respecto a ediciones anteriores. Los valores de 20,1 % y 18,6 % sobreestiman la prevalencia de 2023 y se aproximan más a cifras de años previos, mientras que el 12,4 % la infravalora respecto al dato publicado en el boletín de indicadores clave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e48") }, {"long_answer": "De acuerdo con los indicadores clave del Plan Nacional sobre Drogas, en 2023 alrededor del 52 % de los adolescentes percibía que el consumo habitual de cannabis puede causar bastantes o muchos problemas, un dato que refleja una percepción del riesgo relativamente baja y en descenso, factor asociado a mayor consumo. Afirmar que más del 90 % o el 70 % percibe riesgo sobrestima la percepción real recogida en el informe. Decir que menos del 10 % la percibe la infravalora de forma notable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e49") }, {"long_answer": "Según el boletín de indicadores clave del Plan Nacional sobre Drogas, basado en la encuesta EDADES, en 2024 aproximadamente el 16,0 % de las personas adultas de 15 a 64 años refirió consumo episódico intensivo de alcohol (binge drinking) en el último mes, es decir, la ingesta de cinco o más bebidas en hombres o cuatro o más en mujeres en un intervalo de unas dos horas. Las cifras de 15,4 %, 15,3 % y 18,2 % no corresponden al dato de 2024 recogido en el informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e50") }, {"long_answer": "El informe muestra que la proporción de personas adultas con posible juego problemático o trastorno por juego, estimada con el cuestionario de cribado de la encuesta EDADES, ha descendido progresivamente desde el 2,6 % en 2018 hasta el 1,4 % en 2024. Hablar de un aumento progresivo de 1,4 % a 2,6 % invierte la tendencia real. La estabilidad en torno al 2 % y un incremento brusco entre 2022 y 2024 tampoco se ajustan a la evolución descendente descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e54") }, {"long_answer": "Según el boletín de indicadores clave del Plan Nacional sobre Drogas, en 2023 alrededor del 42 % de las personas que iniciaron tratamiento por trastorno por uso de sustancias lo hicieron por derivación desde otros servicios (sanitarios, sociales o del sistema judicial), frente a quienes acudieron por iniciativa propia o de su entorno. Las cifras de 49,4 %, 39,8 % y 44,3 % no se corresponden con el dato aproximado publicado en el informe para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e57") }, {"long_answer": "Según los indicadores clave del Plan Nacional sobre Drogas, alrededor del 93,1 % de las madres de recién nacidos sanos refieren no haber consumido alcohol durante el embarazo, lo que indica que cerca de un 7 % sí lo hizo pese a que la recomendación es la abstinencia total, ya que no existe una cantidad segura por el riesgo de trastorno del espectro alcohólico fetal. Los valores de 70,1 %, 50 % y 85,5 % infraestiman la proporción de abstinencia recogida en el informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e59") }, {"long_answer": "El informe estima que en 2023 la cobertura del tratamiento sustitutivo de opiáceos en personas con trastorno por uso de heroína fue cercana al 99 %, lo que refleja la amplia accesibilidad en España a los programas de mantenimiento con metadona o buprenorfina, una de las intervenciones más eficaces para reducir la mortalidad, las infecciones y la delincuencia asociadas. Las cifras de 84,1 %, 92 % y 96,5 % infravaloran la cobertura publicada en el boletín de indicadores clave para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e5c") }, {"long_answer": "La estimación nacional de muertes por reacción aguda adversa a sustancias psicoactivas se apoya en los datos de seis ciudades españolas, que se recogen a partir de los institutos de medicina legal con análisis toxicológico y mantienen una cobertura estable desde el inicio del indicador, lo que permite valorar tendencias. No se limitan a mayores de 65 años; de hecho, la mayoría de fallecidos son adultos de mediana edad. Tampoco se restringen a Madrid y Barcelona, y el indicador se refiere específicamente a reacciones agudas, por lo que sí diferencia estas muertes de las debidas a consecuencias crónicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d8f") }, {"long_answer": "Según la ICRP 137, el coeficiente de dosis para el radón en condiciones normales en edificios es de 3 mSv por mJ·h·m⁻³, que, asumiendo un factor de equilibrio de 0,4, equivale aproximadamente a 6,7 × 10⁻⁶ mSv por Bq·h·m⁻³; este valor permite convertir la exposición integrada en dosis efectiva. El valor de 1,3 × 10⁻⁵ es aproximadamente el doble y no corresponde a condiciones normales. Las cifras de 1,0 × 10⁻⁴ y 5,0 × 10⁻⁷ se alejan en un orden de magnitud por exceso o por defecto del coeficiente establecido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d91") }, {"long_answer": "El radón y el tabaco actúan de forma sinérgica sobre el riesgo de cáncer de pulmón, de modo que los fumadores expuestos tienen un riesgo absoluto muy superior. El documento indica que dejar de fumar reduce de manera notable ese riesgo, aproximadamente a la mitad tras unos diez años de abstinencia, lo que convierte la cesación tabáquica en una medida prioritaria en trabajadores expuestos. Es falso que no haya reducción aparente o que el riesgo aumente por compensación, y la disminución no exige más de 20 años sin fumar para empezar a manifestarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d94") }, {"long_answer": "El Reglamento sobre Protección Sanitaria contra las Radiaciones Ionizantes de 2022 establece que el historial dosimétrico de los trabajadores expuestos, incluidos los expuestos al radón, debe conservarse hasta que la persona alcance los 75 años y, en todo caso, durante un mínimo de 30 años desde que cesó la actividad que motivó su clasificación como trabajador expuesto. Mantenerlo solo mientras ocupe el puesto o 5 años desde la última exposición sería insuficiente, dada la latencia de los efectos estocásticos. La conservación indefinida sin límite tampoco es lo que fija la norma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d97") }, {"long_answer": "La concentración de radón en el interior de los edificios depende en gran medida de la renovación del aire. En edificaciones antiguas, con ventanas pequeñas y escasas, la ventilación es deficiente y el gas procedente del terreno se acumula, aumentando su concentración. Es falso que la ventilación no influya, puesto que es una de las medidas básicas para reducir el radón. Ventilar no incrementa su concentración, sino que la diluye, y aunque la ventilación mecánica es eficaz, no garantiza la eliminación completa del gas, que requiere a veces medidas de sellado o despresurización del suelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d9f") }, {"long_answer": "En la desfibrilación de doble secuencia (DDS), antes de realizar la descarga hay que confirmar en el segundo monitor que el ritmo es desfibrilable (fibrilación ventricular o taquicardia ventricular sin pulso), ya que la técnica solo está indicada en la fibrilación ventricular refractaria. Comprobar que la batería esté al 100 % no es el requisito establecido por el protocolo. El paciente debe estar en decúbito supino, no en posición vertical, y no se indica desconectar el electrodo situado bajo la mamila izquierda, que forma parte del segundo vector de descarga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da2") }, {"long_answer": "El protocolo de desfibrilación de doble secuencia indica comunicar a la Central de Comunicaciones la situación de parada cardiorrespiratoria tan pronto como se enciende el primer monitor en la atención, para activar precozmente los recursos necesarios, como un segundo desfibrilador o apoyo adicional. Esperar a la primera descarga o a completar las tres primeras desfibrilaciones retrasaría la llegada de esos recursos, imprescindibles para aplicar la DDS. Notificar antes de encender el monitor no es posible si aún no se ha confirmado la situación clínica en la escena."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da4") }, {"long_answer": "Entre las primeras tres desfibrilaciones estándar debe mantenerse un ciclo de reanimación cardiopulmonar de 2 minutos, siguiendo las recomendaciones de soporte vital avanzado, de forma que tras cada descarga se reanudan inmediatamente las compresiones sin comprobar el pulso hasta finalizar el ciclo. Un intervalo de 1 minuto no se corresponde con la pauta establecida, y uno de 5 minutos prolongaría en exceso el tiempo hasta la siguiente descarga. No hacer RCP entre descargas aumentaría el tiempo sin perfusión coronaria y cerebral, empeorando el pronóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da5") }, {"long_answer": "En la desfibrilación de doble secuencia, los parches del segundo monitor se colocan de modo que generen un vector de descarga diferente al del primero, por lo que se orientan de forma perpendicular (vertical) respecto a la posición habitual de los primeros electrodos, que se sitúan en disposición esternal-apical. Colocarlos en la misma posición horizontal no modificaría el vector y anularía el beneficio de la técnica. Situar ambos parches en la espalda o ambos en la línea media del tórax no crea un vector de descarga eficaz a través del miocardio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da7") }, {"long_answer": "Durante la colocación de los electrodos del segundo monitor en la desfibrilación de doble secuencia debe minimizarse la interrupción de las compresiones torácicas, ya que cada pausa reduce la presión de perfusión coronaria y cerebral y disminuye la probabilidad de éxito de la desfibrilación. No se pretende acortar la duración global de las intervenciones a costa de la calidad, ni limitar la comunicación con el equipo, que es esencial para coordinar la descarga secuencial. Tampoco se busca reducir la energía, ya que se emplea la energía máxima en ambos desfibriladores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977da8") }, {"long_answer": "En la desfibrilación de doble secuencia, el electrodo del segundo monitor que lleva el dibujo de colocación bajo la mamila izquierda se sitúa en posición vertical en la zona paraesternal izquierda, sin que llegue a contactar con el otro parche, para crear un vector de descarga diferente al del primer desfibrilador. La posición horizontal bajo la clavícula derecha corresponde a la colocación habitual del electrodo esternal. La línea media del abdomen y la espalda bajo la escápula derecha no son las ubicaciones indicadas en el protocolo para este electrodo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dab") }, {"long_answer": "Al comenzar la técnica de desfibrilación de doble secuencia, el paciente debe estar en decúbito supino sobre una superficie firme y en un lugar seguro, posición que permite realizar compresiones torácicas eficaces, colocar los electrodos de ambos monitores y efectuar las descargas con seguridad para el equipo. El decúbito prono dificulta las compresiones y la colocación de los parches anteriores. Las posiciones sentado con respaldo o de pie con soporte son incompatibles con una reanimación cardiopulmonar de calidad."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db5") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977db7") }, {"long_answer": "Las recomendaciones para la temporada 2024-2025 establecen que nirsevimab debe administrarse prioritariamente, además de a los nacidos durante la temporada y a los menores de seis meses al inicio de esta, a los prematuros de menos de 35 semanas de edad gestacional antes de cumplir los 12 meses, por su mayor riesgo de infección grave por virus respiratorio sincitial. Los recién nacidos a término sin patología se incluyen solo según su fecha de nacimiento. Los lactantes mayores de 12 meses no entran en este grupo, y el asma leve no es indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dba") }, {"long_answer": "Según las recomendaciones del Ministerio de Sanidad, en la segunda temporada de VRS los niños con alto riesgo de enfermedad grave reciben una dosis de nirsevimab según el peso: si pesan 10 kg o más, 200 mg administrados como dos inyecciones intramusculares de 100 mg en lugares diferentes y en el mismo acto, y si pesan menos de 10 kg, 100 mg en una única inyección. Por tanto, a un niño de 11 kg le corresponden 200 mg. La dosis de 50 mg se usa en la primera temporada en menores de 5 kg, 100 mg en una inyección es insuficiente con este peso y 100 mg en dos inyecciones no es una pauta establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dbd") }, {"long_answer": "Según la actualización de las recomendaciones, en la temporada 2023-2024 la cobertura media de inmunización con nirsevimab en los recién nacidos durante la temporada en España alcanzó aproximadamente el 92 %, una cifra muy elevada que contribuyó a la marcada reducción de hospitalizaciones por virus respiratorio sincitial. Los valores de 88 %, 75 % y 60 % infravaloran la cobertura obtenida, que fue de las más altas en un programa de este tipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dbe") }, {"long_answer": "En los recién nacidos durante la temporada de VRS, nirsevimab se recomienda en las primeras 24-48 horas tras el nacimiento, preferentemente antes del alta de la maternidad, porque los primeros meses de vida, y en particular las primeras semanas, son el periodo de mayor riesgo de hospitalización y enfermedad grave. Esperar a los 6 meses o a los 3 meses dejaría al lactante sin protección en su etapa más vulnerable, y administrarlo al finalizar la temporada carecería de utilidad preventiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc3") }, {"long_answer": "Las evaluaciones realizadas tras la introducción de nirsevimab en España mostraron una reducción de las hospitalizaciones por virus respiratorio sincitial en los menores de un año de entre aproximadamente el 71 % y el 77 %, según la actualización del documento de recomendaciones, lo que confirma su elevada efectividad en condiciones reales. Los rangos de 50-60 % y 30-40 % infravaloran el impacto observado, y una reducción inferior al 20 % no se corresponde con los resultados publicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc7") }, {"long_answer": "Si un recién nacido durante la temporada no recibe nirsevimab en las primeras 48 horas, la recomendación es administrar la dosis a la mayor brevedad posible, ya que el riesgo de infección grave por VRS es máximo en las primeras semanas de vida y cualquier retraso prolonga el periodo sin protección. Retrasarlo hasta los 6 meses carece de justificación. Omitirlo en esa temporada privaría al lactante de protección, y limitarlo a la presencia de síntomas respiratorios es incorrecto, ya que es una medida preventiva y no un tratamiento.", "option_3": "No administrar nirsevimab en esa temporada"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dc8") }, {"long_answer": "Además de reducir las hospitalizaciones, nirsevimab ha mostrado un impacto positivo sobre las infecciones respiratorias de vías bajas por VRS médicamente atendidas en atención primaria, disminuyendo su incidencia en los lactantes inmunizados. Afirmar que no tiene impacto en atención primaria o que solo actúa sobre la hospitalización contradice los datos de efectividad recogidos en la actualización. Tampoco incrementa la incidencia de enfermedades respiratorias; su perfil de seguridad es favorable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dcb") }, {"long_answer": "Se recomienda administrar nirsevimab precozmente en los neonatos nacidos durante la temporada de otoño-invierno porque la enfermedad por VRS es más grave cuanto menor es la edad, y los primeros días y semanas de vida concentran el mayor riesgo de bronquiolitis grave y hospitalización. Nirsevimab no es una vacuna sino un anticuerpo monoclonal que proporciona protección inmediata, por lo que no tiene una respuesta lenta. Su objetivo es proteger al lactante, no evitar la transmisión a los adultos, y no se limita a niños con cardiopatías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dde") }, {"long_answer": "El modelo de práctica profesional que plantea el Marco Estratégico para los Cuidados de Enfermería tiene como finalidad garantizar una atención centrada en la persona, integrar y clarificar las posiciones y roles profesionales y contribuir a la sostenibilidad del sistema, en todos los ámbitos asistenciales. No se centra en procedimientos administrativos de contratación ni se limita a uniformar la práctica en hospitales de alta complejidad, ya que abarca también atención primaria y comunitaria. Tampoco se restringe a regular la docencia en enfermería."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ddf") }, {"long_answer": "Para potenciar el reconocimiento social y profesional de enfermeras y TCAE, el Marco Estratégico propone desarrollar un plan de comunicación y fomentar su presencia en medios de comunicación, foros y actividades comunitarias, incorporando la perspectiva de género para visibilizar a un colectivo mayoritariamente femenino. Limitar su participación en campañas de salud o renunciar a los foros internacionales reduciría su visibilidad. Restringir la formación en comunicación iría en contra del objetivo de liderazgo y proyección pública que persigue el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de2") }, {"long_answer": "El enfoque One Health (Una sola salud) es uno de los principios transversales del Marco Estratégico y reconoce que la salud humana, la salud animal y la del medio ambiente están estrechamente interrelacionadas en un mismo ecosistema, por lo que deben abordarse de forma coordinada, por ejemplo ante zoonosis o resistencias antimicrobianas. La salud comunitaria se centra en la población de un territorio y sus activos. La salud pública integral y la epidemiología ambiental son conceptos más restringidos que no integran explícitamente las tres dimensiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977de7") }, {"long_answer": "El itinerario formativo vinculado a las posiciones y roles del modelo de práctica profesional busca impulsar una formación específica que garantice cuidados seguros y de calidad, incluyendo el desarrollo de roles de práctica avanzada y la actualización continua de competencias. No se limita a las enfermeras especialistas, sino que abarca a todas las posiciones profesionales. Reducir la formación para acelerar la incorporación al mercado laboral o limitarla a conocimientos básicos sin actualización contradice el objetivo de calidad y seguridad del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dec") }, {"long_answer": "El Marco Estratégico recoge un concepto de salud basado en la definición de la OMS pero redefinido como un estado dinámico de completo bienestar físico, mental, espiritual y social, superando la visión estática de la definición clásica e incorporando la dimensión espiritual. La concepción de ausencia total de enfermedad y bienestar completo absoluto es la idea estática que se pretende superar. Reducirla a bienestar físico y psicológico omite las esferas social y espiritual, y basarla únicamente en indicadores biomédicos contradice el enfoque holístico de los cuidados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977df2") }, {"long_answer": "Establecer indicadores de cuidados en el Sistema Nacional de Salud permite medir la actividad, la seguridad, la calidad y la productividad de la prestación de cuidados, lo que facilita la evaluación, la comparación entre servicios, la toma de decisiones y la visibilidad de la aportación enfermera. Su finalidad no es controlar la jornada laboral de las enfermeras ni reducir la dedicación en atención primaria. Tampoco persiguen fomentar la competencia entre profesionales, sino la mejora continua de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977dfb") }, {"long_answer": "En la radioterapia externa postoperatoria del cáncer de cuello uterino, la dosis habitualmente prescrita es de 45-50 Gy con fraccionamiento estándar, es decir, 1,8-2 Gy por sesión durante unas cinco semanas, generalmente con quimioterapia concomitante con cisplatino cuando existen factores de riesgo. Una dosis de 20-30 Gy en una sola fracción sería tóxica e insuficiente para el control tumoral. Las dosis de 70-80 Gy superan la tolerancia de los órganos pélvicos en radioterapia externa, y 15 Gy en dos sesiones es una pauta insuficiente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e00") }, {"long_answer": "Ante una recidiva locorregional de cáncer de cuello uterino en una paciente que no ha recibido radioterapia previa, el tratamiento recomendado es la radioquimioterapia concomitante basada en platino seguida de braquiterapia guiada por imagen cuando sea técnicamente posible, con intención curativa. La cirugía radical sin adyuvancia no es el tratamiento de elección en esta situación. El seguimiento clínico aislado supondría renunciar a un tratamiento potencialmente curativo, y la radioterapia externa sin quimioterapia es menos eficaz que la combinación concomitante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e01") }, {"long_answer": "La exenteración pélvica extendida se plantea en la recidiva locorregional del cáncer cervical cuando la enfermedad se extiende hacia la pared pélvica y no es posible administrar radioterapia radical, por ejemplo por haberla recibido previamente, siempre que no existan metástasis a distancia y pueda lograrse una resección con márgenes libres. No tiene indicación en procesos inflamatorios como una vaginitis post-tratamiento. Los tumores T1a sin afectación ganglionar no son recidivas y se tratan de forma conservadora, y en la recidiva no locorregional la cirugía pélvica ultrarradical no está indicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e12") }, {"long_answer": "En la clasificación de Querleu-Morrow, la histerectomía radical tipo C2 implica la movilización completa del uréter y la resección completa del paracérvix hasta los vasos ilíacos internos, sin preservación de los nervios autonómicos pélvicos. La tipo A es una histerectomía extrafascial sin resección parametrial. La tipo B1 desplaza el uréter lateralmente y reseca parcialmente el paracérvix a la altura del uréter, sin llegar a la pared pélvica. La tipo D corresponde a resecciones laterales extendidas que incluyen la pared pélvica y los vasos ilíacos internos.", "question": "¿Qué tipo de histerectomía radical, según la clasificación de Querleu-Morrow, incluye la movilización completa del uréter y la resección completa del paracérvix sin preservación nerviosa?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e14") }, {"long_answer": "En la radioterapia del cáncer cervical, el volumen blanco clínico de riesgo bajo o intermedio del tumor (CTV-T-LR) incluye el GTV-T y el CTV de alto riesgo, la totalidad del cuello uterino y del útero, los parametrios y un margen de vagina no afectada de unos 2 cm por debajo del tumor, para cubrir la posible extensión microscópica. Limitarlo al tumor visible macroscópicamente correspondería al GTV. Incluir solo los ganglios pélvicos corresponde al CTV ganglionar, y restringirlo al cuello uterino dejaría sin cubrir áreas de riesgo de diseminación.", "option_1": "GTV-T, cuello uterino, útero, parametrios y 2 cm de vagina no afectada"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e18") }, {"long_answer": "Los criterios de Rotterdam establecen el diagnóstico de síndrome de ovario poliquístico cuando se cumplen al menos dos de estos tres: oligoovulación o anovulación, signos clínicos o bioquímicos de hiperandrogenismo y morfología de ovarios poliquísticos en la ecografía, tras excluir otras causas. La insulinorresistencia y la obesidad son frecuentes, pero no forman parte de los criterios diagnósticos, y el hipotiroidismo debe descartarse. La resistencia a la insulina no es obligatoria, y la hiperprolactinemia es una causa de anovulación que precisamente hay que excluir."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1b") }, {"long_answer": "La escala LATCH valora la eficacia de la toma de lactancia materna mediante cinco elementos cuyas iniciales forman su nombre en inglés: agarre (Latch), deglución audible (Audible swallowing), tipo de pezón (Type of nipple), comodidad o confort de la madre (Comfort) y ayuda para la posición o sujeción del bebé (Hold), cada uno puntuado de 0 a 2. El peso al nacer, el color de la piel o el reflejo de búsqueda no forman parte de la escala. Tampoco incluye el sueño, las deposiciones, el peso materno, la frecuencia cardiaca ni el índice de masa corporal.", "option_1": "Agarre, deglución audible, tipo de pezón, comodidad de la madre y ayuda para la posición"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e1f") }, {"long_answer": "La escala RASS (Richmond Agitation-Sedation Scale) va de +4 (combativo) a -5 (no despertable). La puntuación -5 corresponde al paciente que no responde a la voz ni a la estimulación física, es decir, en coma profundo o con sedación muy profunda. El valor +4 describe un paciente combativo y violento. El 0 corresponde al paciente alerta y tranquilo, y el -2 a una sedación ligera en la que el paciente se despierta brevemente a la voz con contacto visual de menos de 10 segundos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e21") }, {"long_answer": "El test FINDRISC estima el riesgo de desarrollar diabetes tipo 2 en los próximos diez años mediante ocho preguntas sobre edad, índice de masa corporal, perímetro de cintura, actividad física, consumo de frutas y verduras, antihipertensivos, glucemia elevada previa y antecedentes familiares. Una puntuación de 12 a 14 corresponde a riesgo moderado. Las puntuaciones inferiores a 7 indican riesgo bajo y las de 7 a 11 riesgo ligeramente aumentado, mientras que de 15 a 20 el riesgo es alto y más de 20 muy alto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e23") }, {"long_answer": "El test de Finnegan es la escala más utilizada para valorar el síndrome de abstinencia neonatal, especialmente por opiáceos, en recién nacidos de madres consumidoras. Puntúa signos neurológicos, vegetativos, gastrointestinales y respiratorios, y su resultado guía el inicio y ajuste del tratamiento farmacológico. No valora el riesgo de tromboembolismo venoso, para el que se emplea la escala de Caprini. La depresión posparto se criba con la escala de Edimburgo, y la función cognitiva infantil se explora con otros instrumentos del desarrollo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e28") }, {"long_answer": "La escala de Aldrete valora la recuperación del paciente tras la anestesia en la unidad de recuperación postanestésica mediante cinco parámetros: actividad motora, respiración, circulación (presión arterial), nivel de conciencia y saturación de oxígeno o coloración. Una puntuación de 9 o más suele indicar que el paciente está en condiciones de ser dado de alta de la sala de recuperación. No evalúa la función renal ni el riesgo de sangrado postoperatorio, y la ansiedad prequirúrgica se mide con otros instrumentos, como la escala APAIS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e2f") }, {"long_answer": "La escala ASIA (American Spinal Injury Association) clasifica las lesiones medulares de la A a la E. El grado A corresponde a una lesión completa, sin preservación de la función motora ni sensitiva en los segmentos sacros S4-S5. El grado B indica lesión incompleta con preservación sensitiva pero no motora por debajo del nivel neurológico. Los grados C y D son lesiones motoras incompletas, que se diferencian según si más o menos de la mitad de los músculos clave tienen un balance muscular de al menos 3."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e30") }, {"long_answer": "El CAM-ICU confirma el delirium cuando se cumplen el criterio 1 (cambio agudo o curso fluctuante del estado mental) y el 2 (inatención), junto con el 3 (alteración del nivel de conciencia) o el 4 (pensamiento desorganizado). Por eso la combinación diagnóstica es 1 + 2 y 3 o 4. Las combinaciones 2 + 3 y 4 o 1 + 3 y 4 omiten alguno de los dos criterios obligatorios, el inicio agudo o fluctuante y la inatención, y la opción de solo 2 y 4 tampoco cumple el algoritmo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e31") }, {"long_answer": "La escala de coma de Glasgow valora el nivel de conciencia mediante tres componentes: apertura ocular (1-4), respuesta verbal (1-5) y respuesta motora (1-6), con una puntuación total entre 3 y 15; una puntuación de 8 o menos indica coma y suele implicar la necesidad de aislar la vía aérea. No valora el riesgo de hemorragia. La presión intracraneal solo puede determinarse mediante monitorización específica, y la intensidad del dolor se mide con escalas como la EVA o la numérica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e37") }, {"long_answer": "La escala de Karnofsky valora el estado funcional y la capacidad para realizar actividades cotidianas con una puntuación de 0 a 100 en intervalos de 10. Aunque se desarrolló y se utiliza sobre todo en pacientes oncológicos para decidir tratamientos y estimar el pronóstico, también se aplica en pacientes no oncológicos con enfermedad avanzada, por ejemplo en cuidados paliativos. No está diseñada para valorar específicamente fracturas abiertas, diabetes o neonatos, colectivos en los que se emplean otras herramientas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e3e") }, {"long_answer": "La escala de Caprini estima el riesgo de tromboembolismo venoso en pacientes quirúrgicos sumando factores de riesgo con distinto peso. Una puntuación igual o superior a 5 se considera riesgo alto y suele indicar profilaxis farmacológica combinada con medidas mecánicas. Una puntuación de 0 corresponde a riesgo muy bajo, de 1 a 2 a riesgo bajo y de 3 a 4 a riesgo moderado, por lo que ninguna de esas categorías representa el riesgo alto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e40") }, {"long_answer": "En el informe del Plan Nacional sobre Drogas, el consumo intensivo de alcohol o binge drinking en adolescentes se define como la ingesta de cinco o más bebidas alcohólicas en una misma ocasión, en un intervalo aproximado de dos horas. Tres o más bebidas en menos de una hora no constituyen la definición utilizada. El consumo diario y continuado durante una semana describe un patrón de consumo frecuente, no un episodio intensivo, y cuatro o más bebidas en menos de tres horas tampoco se ajusta al criterio empleado en la encuesta ESTUDES."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e44") }, {"long_answer": "Según los indicadores clave del Plan Nacional sobre Drogas, basados en la encuesta ESTUDES, la proporción de estudiantes de 14 a 18 años con posible trastorno por uso de videojuegos descendió del 7,1 % en 2019 al 5,1 % en 2023. Hablar de un incremento de 7,1 % a 8,5 % o de 5,1 % a 7,1 % invierte o distorsiona la tendencia real. La estabilidad en torno al 6,1 % tampoco refleja el descenso observado en el periodo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e4b") }, {"long_answer": "Según el boletín de indicadores clave, el consumo de analgésicos opioides sin receta o con fines no médicos en personas adultas se sitúa alrededor del 0,6 % en los años más recientes, una prevalencia baja pero relevante por el riesgo de dependencia y sobredosis. Una proporción menor del 0,1 % infravalora el dato. Las cifras superiores al 2 % o situadas entre el 5 % y el 7 % sobreestiman claramente el consumo no médico de opioides recogido en la encuesta EDADES.", "option_1": "Entre el 5% y el 7%"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e52") }, {"long_answer": "Según el boletín de indicadores clave del Plan Nacional sobre Drogas, en 2024 aproximadamente el 0,2 % de la población adulta presentaba un posible trastorno por consumo de cocaína en el último año, estimado mediante escalas de cribado incluidas en la encuesta EDADES. Las cifras de 0,3 % y 0,5 % sobrestiman la prevalencia publicada, y el 1,4 % se aproxima más a la prevalencia de consumo de cocaína en el último año que a la del trastorno por consumo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e53") }, {"long_answer": "El informe muestra que la prevalencia estimada de trastorno por consumo de heroína ha experimentado una disminución gradual entre 2009 y 2023, pasando aproximadamente del 0,25 % al 0,16 %, en consonancia con el descenso del consumo de heroína y del inicio de nuevos consumidores en España. Hablar de un incremento sostenido del 0,16 % al 0,25 % invierte la tendencia. La estabilidad en torno al 0,22 % o las oscilaciones sin tendencia clara no describen la reducción progresiva observada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e58") }, {"long_answer": "El informe señala que la proporción de episodios de urgencias hospitalarias relacionados con el consumo no médico de fármacos opioides distintos de la heroína ha aumentado y podría superar el 13 % de las urgencias relacionadas con drogas, lo que refleja la creciente relevancia de los opioides de prescripción. No es cierto que no existan datos registrados ni que la proporción se desconozca, ya que el indicador de urgencias del Plan Nacional sobre Drogas la recoge. Situarla por debajo del 5 % infravalora el dato descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e63") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal reflexiona sobre el volumen creciente de información científica disponible y señala que, sin herramientas adecuadas como las GPC basadas en la evidencia, ese exceso de información dificulta la toma de decisiones clínicas y favorece la variabilidad. No propone dejar de actualizarse para evitar confusión, sino sintetizar críticamente la evidencia. Tampoco considera útil solo la información de fuentes no oficiales, y afirma su relevancia también en el parto normal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e60") }, {"long_answer": "El Plan de Calidad para el Sistema Nacional de Salud, en su estrategia dirigida a la mejora de la práctica clínica, plantea disminuir la variabilidad no justificada mediante la elaboración y el uso de Guías de Práctica Clínica basadas en la evidencia, marco en el que se encuadra esta guía sobre el parto normal. No promueve protocolos para aumentar la intervención en el parto, sino reducir las intervenciones innecesarias. Tampoco limita el acceso a las guías a determinados profesionales ni excluye a las asociaciones de pacientes, que participan en su elaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e61") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal fue elaborada por un grupo de trabajo multidisciplinar formado por profesionales sanitarios de distintas disciplinas, como matronas, obstetras, pediatras, anestesiólogos y metodólogos, junto con mujeres representantes de asociaciones, lo que garantiza que se incorpore la perspectiva de las usuarias. No se limitó a especialistas en ginecología y obstetricia ni a matronas de una sola comunidad autónoma. El personal administrativo y los técnicos de laboratorio no constituyeron el grupo elaborador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e62") }, {"long_answer": "La función principal de esta Guía de Práctica Clínica es ofrecer recomendaciones basadas en la evidencia que mejoren la calidad asistencial en el parto normal y faciliten la participación activa de la mujer en la toma de decisiones, respetando la fisiología del proceso. Las GPC no sustituyen el juicio clínico, sino que lo apoyan. Tampoco pretenden imponer un procedimiento único para todos los partos, ya que deben individualizarse, ni recomiendan el uso exclusivo de métodos farmacológicos, puesto que incluyen también alternativas no farmacológicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e64") }, {"long_answer": "Según la Guía, la Agencia de Calidad del Sistema Nacional de Salud promueve la elaboración, difusión y utilización de Guías de Práctica Clínica, velando por que tengan la calidad metodológica necesaria y sean accesibles a los profesionales, en el marco del Plan de Calidad. No limita su publicación al sector privado ni se ocupa solo de aspectos administrativos. Tampoco evalúa únicamente intervenciones quirúrgicas, ya que su ámbito abarca todo tipo de procesos asistenciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6c") }, {"long_answer": "El proyecto GuíaSalud, organismo del Sistema Nacional de Salud, incluye entre sus funcionalidades el registro de Guías de Práctica Clínica, su difusión y la formación de los profesionales en su elaboración y uso, con el objetivo de favorecer la toma de decisiones clínicas basadas en la evidencia. No promueve el uso exclusivo de técnicas quirúrgicas ni sustituye el juicio clínico por protocolos obligatorios. Tampoco se limita a evaluar medicamentos, ya que su ámbito incluye guías sobre cualquier proceso asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6e") }, {"long_answer": "La Guía considera el parto normal como un proceso fisiológico, en el que la mujer y el recién nacido requieren una atención de calidad y unos cuidados adecuados que respeten su evolución natural y eviten intervenciones innecesarias. No se trata de una emergencia médica que siempre precise intervención quirúrgica, ni de un evento que deba intervenirse farmacológicamente desde el inicio. Tampoco se entiende como un procedimiento exclusivamente tecnológico, ya que el enfoque prioriza la atención humanizada y la participación de la mujer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e65") }, {"long_answer": "La Guía subraya que la calidad y la calidez de los cuidados proporcionados durante la atención al parto normal favorecen que la mujer tenga una vivencia satisfactoria de la experiencia, lo que influye en su bienestar y en el inicio del vínculo con el recién nacido. Restringir la presencia de acompañantes es contrario a las recomendaciones, que apoyan el acompañamiento continuo. Intervenir de forma precoz sin explicaciones vulnera la participación informada de la mujer, y eliminar cualquier analgesia ignora su derecho a recibir alivio del dolor si lo desea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e66") }, {"long_answer": "La versión resumida de la Guía de Práctica Clínica sobre la atención al parto normal, elaborada en el marco del Plan de Calidad para el Sistema Nacional de Salud, se publicó en su primera edición en 2010. El año 2003 es anterior al desarrollo de la Estrategia de Atención al Parto Normal, que se aprobó en 2007. El año 2006 corresponde a la puesta en marcha del Plan de Calidad, y 2015 es posterior a la publicación de la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e67") }, {"long_answer": "La Guía señala que la implementación de la Estrategia de Atención al Parto Normal en el Sistema Nacional de Salud se ve facilitada por el trabajo conjunto de las distintas profesiones implicadas en la atención al parto y por la participación de las mujeres y sus asociaciones en las decisiones. La imposición de protocolos rígidos sin participación femenina contradice el enfoque de la estrategia. Reducir el personal sanitario o excluir las recomendaciones basadas en la evidencia iría en contra de la calidad y la seguridad que persigue."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6a") }, {"long_answer": "En la elaboración de la Guía han participado profesionales de reconocido prestigio como colaboradores y revisores externos, aportando rigor científico y una revisión crítica que contribuye a la calidad y credibilidad de las recomendaciones. Es falso que no se haya considerado su opinión. Su aportación no se basó solo en la experiencia clínica sin evidencia, ya que la guía se apoya en la mejor evidencia disponible, y no fue redactada exclusivamente por personal administrativo, sino por un grupo multidisciplinar de profesionales sanitarios."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e68") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6d") }, {"long_answer": "La elaboración de la Guía de Práctica Clínica sobre la atención al parto normal se financió mediante el convenio suscrito entre el Instituto de Salud Carlos III, organismo dependiente entonces del Ministerio de Ciencia e Innovación, y la Agencia de Evaluación de Tecnologías Sanitarias del País Vasco (OSTEBA), en el marco del Plan de Calidad para el Sistema Nacional de Salud. La Sociedad Española de Matronas no fue la entidad financiadora. Tampoco lo fueron el Ministerio de Educación ni la Organización Mundial de la Salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e69") }, {"long_answer": "Las recomendaciones de la Guía se sustentan en las mejores evidencias científicas disponibles, obtenidas mediante revisión sistemática de la literatura y evaluadas con una metodología explícita que gradúa la calidad de la evidencia y la fuerza de cada recomendación. Las opiniones de expertos solo se utilizan cuando no existe evidencia suficiente y siempre de forma explícita, no como base general. Las experiencias personales de algunos profesionales y las tradiciones culturales sin base científica no constituyen el fundamento de las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e6b") }, {"long_answer": "La utilización de la Guía en la atención al parto normal en España busca mejorar la calidad de la atención y aumentar la satisfacción tanto de las mujeres como de los profesionales, reduciendo intervenciones innecesarias y favoreciendo decisiones compartidas. No pretende aumentar la medicalización del parto sin justificación, sino lo contrario. Tampoco limita la autonomía de la mujer, cuya participación activa se promueve, ni estandariza la duración del parto, que varía según cada mujer y debe valorarse de forma individual."});
rm('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e73") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7c") }, {"long_answer": "Los cannabinoides sintéticos son agonistas totales, de alta afinidad y gran potencia, de los receptores cannabinoides CB1 y CB2, mientras que el THC del cannabis natural es un agonista parcial; por ello pueden producir efectos mucho más intensos e impredecibles y una mayor toxicidad, con intoxicaciones graves e incluso muertes. Es falso que tengan menor potencia o que no afecten al sistema nervioso central. El cannabis natural sí tiene efectos psicoactivos debidos al THC, y los cannabinoides sintéticos no contienen CBD, que en el cannabis puede modular algunos efectos del THC."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7e") }, {"long_answer": "El término cannabis sintético resulta inapropiado y peligroso porque sugiere que estas sustancias son equivalentes al cannabis natural, con riesgos y efectos similares, cuando en realidad son compuestos químicos distintos, mucho más potentes y con mayor toxicidad, lo que puede llevar a infravalorar su peligrosidad. No se limitan a productos legales y regulados, ya que se distribuyen en el mercado ilícito. Tampoco se refieren a derivados del cáñamo, y su potencia es mayor, no menor, que la del cannabis natural."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e80") }, {"long_answer": "El ADB-BUTINACA es un cannabinoide sintético de última generación, agonista total de los receptores cannabinoides con una potencia muy elevada, que se ha asociado a intoxicaciones graves y a fallecimientos en distintos países europeos, por lo que ha sido objeto de alertas. No es un cannabinoide natural extraído del cáñamo, sino un compuesto sintetizado químicamente. Tampoco tiene un uso legal con efectos terapéuticos comprobados ni es un compuesto de baja afinidad sin efectos graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e86") }, {"long_answer": "Los consumidores buscan cannabinoides sintéticos sobre todo para experimentar efectos similares a los del cannabis pero más intensos, y porque muchos de estos compuestos no se detectan en los análisis de drogas convencionales, lo que resulta atractivo en contextos de control como el laboral, penitenciario o vial. No se utilizan como suplementos nutricionales ni como tratamiento supervisado de enfermedades neurodegenerativas. Su perfil farmacológico no es similar a un placebo, sino de alta potencia y toxicidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e87") }, {"long_answer": "Para evitar confusiones se recomienda emplear la denominación agonistas sintéticos de los receptores cannabinoides (SCRA, por sus siglas en inglés), que describe su mecanismo de acción y los distingue del cannabis natural. El término cannabis sintético es precisamente el que se desaconseja, porque induce a pensar que comparten riesgos con el cannabis. Las expresiones extractos derivados del cáñamo con bajo THC y productos de cannabidiol natural hacen referencia a productos diferentes y no describen a estas sustancias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e89") }, {"long_answer": "La THCV (tetrahidrocannabivarina) es un fitocannabinoide presente de forma natural en la planta de cannabis, por lo que no pertenece a las familias químicas de cannabinoides sintéticos. En cambio, JWH-018 y AM-2201 pertenecen a la familia de los naftoilindoles, sintetizados inicialmente con fines de investigación y detectados en productos tipo Spice. El HU-210 es un cannabinoide sintético clásico, análogo estructural del THC y de potencia muy superior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8b") }, {"long_answer": "Los sistemas nacionales de alerta temprana tienen como función principal detectar, evaluar y responder con rapidez a incidentes relacionados con nuevas sustancias psicoactivas, como intoxicaciones derivadas de productos adulterados o contaminados con cannabinoides sintéticos, emitiendo alertas a profesionales y población. No promocionan el uso seguro o legal de estas sustancias. Tampoco emiten certificados de calidad a establecimientos ni regulan la producción legal de cannabis natural, que corresponde a otros organismos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8c") }, {"long_answer": "El consumo de cannabinoides sintéticos puede provocar graves consecuencias neurológicas y psiquiátricas, como convulsiones, crisis epilépticas, agitación, psicosis aguda y desarrollo de dependencia con síndrome de abstinencia, debido a su acción como agonistas totales de alta potencia. Es falso que mejoren la memoria a largo plazo o la concentración. Tampoco disminuyen los síntomas depresivos sin efectos adversos, y sí producen alteraciones cognitivas significativas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8d") }, {"long_answer": "En los productos de tipo Spice, los cannabinoides sintéticos se pulverizan o impregnan sobre materia vegetal seca que no siempre es Cannabis sativa, sino otras plantas como Canavalia maritima o Nymphaea alba, para que el producto parezca una mezcla de hierbas inocua. No se utiliza únicamente cáñamo industrial certificado. Tampoco se emplean exclusivamente flores naturales de cannabis sin adulterar, ya que precisamente se adulteran, y las plantas utilizadas no son solo medicinales no psicoactivas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e93") }, {"long_answer": "La terminología incoherente utilizada en la industria del cannabis aumenta los riesgos para la salud pública porque genera confusión y favorece términos engañosos que minimizan los peligros reales de productos como los cannabinoides sintéticos, haciendo que los consumidores los perciban como seguros o naturales. No promueve un lenguaje científico claro, sino lo contrario. Tampoco ayuda a identificar productos seguros para uso recreativo, ni su efecto principal es limitar la disponibilidad de productos en el mercado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e94") }, {"long_answer": "La facilidad de acceso a cannabinoides sintéticos a través de internet y redes sociales favorece su difusión, especialmente entre los jóvenes, lo que se traduce en un incremento del consumo y en una mayor incidencia de intoxicaciones. No reduce el consumo general de drogas ilícitas ni disminuye la demanda de cannabis natural. Tampoco ha permitido contener el tráfico ilegal, ya que la venta en línea dificulta precisamente el control y la regulación de estas sustancias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9c") }, {"long_answer": "Los cannabinoides sintéticos se han comercializado en el mercado ilícito bajo nombres comerciales como K2, Spice, Spice Gold, Hierba Falsa o Yucatán Fire, presentados a menudo como inciensos o mezclas de hierbas no aptas para el consumo humano para eludir la regulación. Cannabis sativa, hachís o cáñamo natural se refieren a productos derivados de la planta, no a cannabinoides sintéticos. El CBD, el aceite de cáñamo o la marihuana medicinal y el Sativex son productos de origen vegetal o medicamentos autorizados.", "option_2": "Cannabis sativa, hachís, cáñamo natural", "option_4": "Marihuana medicinal, aceite terapéutico, Sativex"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9d") }, {"long_answer": "En la Clinical Frailty Scale adaptada en España (CFS-España), los niveles 1 a 3 (muy en forma, en forma y manejándose bien) corresponden a pacientes no frágiles. El nivel 4 representa a personas vulnerables o con fragilidad muy leve, y a partir del nivel 5 se considera fragilidad leve, que progresa hasta el nivel 8 de fragilidad muy grave. El nivel 9 identifica al paciente con enfermedad terminal. Por ello, los rangos 4-5, 5-8 y 6-9 incluyen pacientes vulnerables o frágiles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea2") }, {"long_answer": "En el estudio de fiabilidad se compararon distintas formas de agrupar por estratos los niveles de la CFS-España. La opción C es la que incluye a los pacientes del nivel 4, vulnerables o con fragilidad muy leve, dentro del grupo de frágiles, adoptando un criterio más amplio de fragilidad. En las opciones A y B, en cambio, el nivel 4 no se clasifica como frágil, sino como no frágil o como categoría intermedia. Por tanto, no es cierto que ninguna opción lo considere frágil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea3") }, {"long_answer": "En el análisis de fiabilidad interobservador de la FRAIL-España, el grupo de intensivistas fue el que mostró la menor concordancia en sus valoraciones, probablemente por la dificultad de evaluar dimensiones subjetivas, como la fatiga o la pérdida de peso previa, en pacientes críticos que a menudo no pueden responder. Las enfermeras mostraron una concordancia mayor. Los pacientes y los investigadores principales no fueron el grupo con peor concordancia en el estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea4") }, {"long_answer": "En la evaluación de la fiabilidad intraobservador de la FRAIL-España, la dimensión enfermedades obtuvo la mayor concordancia, ya que se basa en datos objetivos que pueden comprobarse en la historia clínica, como el número de enfermedades crónicas. La fatiga es una dimensión subjetiva que depende de la percepción del paciente. La ambulación y la pérdida de peso requieren información previa al ingreso que a menudo resulta difícil de obtener de forma fiable en pacientes críticos, por lo que su concordancia fue menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea7") }, {"long_answer": "En la Clinical Frailty Scale-España, el nivel 9 corresponde al paciente con enfermedad terminal, es decir, con una esperanza de vida inferior a seis meses, con independencia de que presente o no otros signos evidentes de fragilidad. El nivel 8 describe una fragilidad muy grave, con dependencia total y aproximación al final de la vida. El nivel 7 corresponde a fragilidad grave con dependencia para el cuidado personal, y el nivel 4 a personas vulnerables o con fragilidad muy leve."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ea9") }, {"long_answer": "En el estudio, los pacientes considerados frágiles según la FRAIL-España presentaron una mediana del índice de Charlson de 5, con un rango intercuartílico de 4 a 8, lo que refleja una carga elevada de comorbilidad, coherente con la asociación entre fragilidad y enfermedades crónicas. Las medianas de 2 y 3 son más propias de pacientes no frágiles con menor comorbilidad. La mediana de 7 sobrestima el valor observado en el grupo de pacientes frágiles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb1") }, {"long_answer": "Entre las limitaciones del estudio se señala la falta de un entrenamiento previo específico de los profesionales en la aplicación de las escalas de fragilidad, lo que pudo influir en la concordancia de las valoraciones. No se trató de la ausencia de herramientas validadas en español, ya que precisamente se analizan versiones adaptadas al español. Tampoco se excluyó a los mayores de 65 años, población en la que la fragilidad es especialmente relevante, ni se incluyó exclusivamente a pacientes con COVID-19."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb5") }, {"long_answer": "La escala FRAIL valora cinco dimensiones: fatiga, resistencia, deambulación, enfermedades y pérdida de peso. El componente de resistencia se explora preguntando si la persona tiene dificultad para subir un tramo de escaleras sin ayuda, es decir, unos diez escalones. La pérdida de apetito no es un ítem de la escala. La pérdida de peso involuntaria corresponde a la dimensión de pérdida de peso, y la fatiga constante a la dimensión de fatiga, no a la de resistencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eba") }, {"long_answer": "La CFS-España es una escala ordinal que clasifica el grado de fragilidad en niveles de 1 a 9 a partir del juicio clínico sobre la funcionalidad, la comorbilidad y la dependencia. La FRAIL-España, en cambio, valora la presencia o ausencia de cinco dimensiones dicotómicas (fatiga, resistencia, deambulación, enfermedades y pérdida de peso), cuya suma permite clasificar al paciente como robusto, prefrágil o frágil. Decir que la CFS es dicotómica y la FRAIL ordinal invierte su estructura, y ninguna de ellas se limita a la actividad física, las comorbilidades o la fatiga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ebb") }, {"long_answer": "La utilización de escalas validadas de fragilidad en pacientes críticos permite valorar de forma objetiva su situación basal y así adecuar los límites del esfuerzo terapéutico y planificar cuidados personalizados, ya que la fragilidad se asocia a peor pronóstico y mayor mortalidad. Su objetivo principal no es estimar la duración de la estancia en la UCI. Tampoco predicen el tipo de infección hospitalaria ni sirven para determinar el grado de dolor, que se valora con escalas específicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ebd") }, {"long_answer": "Según el estudio, la dimensión de pérdida de peso involuntaria de la FRAIL-España fue la que presentó menor consenso entre profesionales, porque requiere conocer la evolución del peso en el año previo, un dato que a menudo no está registrado y es difícil de obtener de forma objetiva en el paciente crítico. La fatiga, la resistencia y la ambulación también dependen de información referida, pero no fueron las dimensiones con menor acuerdo en el estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec1") }, {"long_answer": "En el sistema suizo revisado de clasificación de la hipotermia accidental, basado en signos clínicos y en el nivel de conciencia, el grado II o hipotermia moderada corresponde a una víctima con alteración de la conciencia, somnolienta, que ya no tiembla. La víctima consciente y temblando corresponde al grado I o leve. La víctima inconsciente pero con signos vitales define el grado III, y la ausencia de signos vitales o muerte aparente corresponde al grado IV."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec8") }, {"long_answer": "En el sistema suizo revisado, una víctima de hipotermia con una puntuación en la escala de coma de Glasgow menor de 9 presenta una alteración profunda de la conciencia y, por tanto, un riesgo alto de parada cardiaca, por lo que debe trasladarse directamente a un hospital con capacidad de ECMO o circulación extracorpórea, que permite el recalentamiento y el soporte si se produce la parada. Un hospital general sin UCI o un centro de atención primaria no pueden ofrecer este soporte. La opción de hospital con UCI y preferiblemente con ECMO se reserva para víctimas de menor riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eca") }, {"long_answer": "En el sistema suizo revisado, la clasificación se basa en el nivel de conciencia, pero en caso de signos de inestabilidad hemodinámica, como hipotensión o arritmias ventriculares, hay que ser prudentes, porque pueden indicar el tránsito hacia un riesgo mayor de parada cardiaca, aunque la conciencia parezca relativamente conservada. Considerar siempre un riesgo bajo o descartar la posibilidad de parada sería peligroso. Basarse solo en la temperatura no es lo que propone el sistema, que prioriza los signos clínicos por la dificultad de medir la temperatura central sobre el terreno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed0") }, {"long_answer": "En el sistema suizo revisado, el grado IV de hipotermia corresponde a la ausencia de signos vitales, y la temperatura asociada abarca un amplio rango por debajo de unos 24 °C, cuyo límite inferior aproximado se sitúa en torno a 11,8 °C, la temperatura central más baja con supervivencia documentada tras una hipotermia accidental. Los 24 °C marcan el umbral superior aproximado a partir del cual aumenta mucho el riesgo de parada, no el límite inferior. Los 28 °C se relacionan con el grado III, y los 35 °C con el límite de la hipotermia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977edd") }, {"long_answer": "En el sistema suizo revisado, la escala AVDN (alerta, respuesta verbal, respuesta al dolor, no respuesta) permite valorar sobre el terreno el nivel de conciencia, un hallazgo clínico clave para clasificar el grado de hipotermia y estimar el riesgo de parada cardiaca y el pronóstico, sin depender de la medición de la temperatura central. No sirve para determinar el tiempo de exposición al frío. Tampoco mide la temperatura corporal ni controla de forma objetiva los signos vitales, que requieren monitorización específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee8") }, {"long_answer": "La guía recomienda que en los pacientes con trastorno de ansiedad generalizada grave se inicie tratamiento farmacológico con un inhibidor selectivo de la recaptación de serotonina mientras se completa la evaluación en salud mental, para no demorar el alivio sintomático. Es falso que no esté indicado el tratamiento farmacológico en el TAG grave. Las benzodiacepinas no deben usarse de forma exclusiva ni prolongada por su riesgo de dependencia, y limitarse solo a la psicoterapia no es la recomendación en los casos graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eef") }, {"long_answer": "La guía plantea la quetiapina en el trastorno de ansiedad generalizada refractario como alternativa a las benzodiacepinas en pacientes con riesgo de abuso o dependencia o con deterioro cognitivo, en quienes estas resultan desaconsejables, valorando siempre sus efectos adversos metabólicos y sedantes. No es un tratamiento de primera línea, que corresponde a los ISRS o IRSN. Tampoco se recomienda solo en combinación con opipramol, y no está contraindicada de forma absoluta, aunque requiere una indicación cuidadosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef5") }, {"long_answer": "La guía recomienda derivar a atención especializada en salud mental al paciente con trastorno de ansiedad generalizada grave, con ideación suicida, con comorbilidad psiquiátrica grave, con síntomas muy incapacitantes o sin respuesta al tratamiento en atención primaria. La ansiedad leve sin comorbilidades debe manejarse en atención primaria. Derivar solo a petición del paciente ignoraría criterios clínicos de gravedad, y si existe buena respuesta al tratamiento en atención primaria no está indicada la derivación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef7") }, {"long_answer": "En relación con el tratamiento farmacológico a largo plazo del trastorno de ansiedad generalizada, la guía sugiere reevaluar de forma activa y periódica su adecuación, valorando la eficacia, los efectos adversos y la posibilidad de una retirada gradual cuando el paciente se mantiene estable. Es falso que no sea necesaria la reevaluación. Suspender sistemáticamente el tratamiento a los tres meses aumenta el riesgo de recaída, y mantenerlo sin modificaciones de forma indefinida contradice la recomendación de revisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977efa") }, {"long_answer": "Según la guía, siguiendo los criterios del DSM, el trastorno de ansiedad generalizada requiere ansiedad y preocupación excesivas la mayor parte de los días durante al menos seis meses, difíciles de controlar, acompañadas de al menos tres síntomas como inquietud, fatiga, dificultad de concentración, irritabilidad, tensión muscular o alteraciones del sueño, con malestar o deterioro funcional. La ansiedad ocasional sin síntomas físicos o los episodios breves sin repercusión no cumplen los criterios, y la preocupación no se limita al trabajo, sino que abarca múltiples áreas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977efd") }, {"long_answer": "Según el documento de recomendaciones de vacunación frente a COVID-19 para 2025-2026, en las temporadas recientes la mayor tasa de infección por SARS-CoV-2 en atención primaria se ha registrado en los niños menores de un año, aunque la gravedad y las hospitalizaciones se concentran en las personas mayores. Las personas de 75 años o más presentan las tasas más altas de hospitalización, no de infección en atención primaria. Los grupos de 50-69 años y de 20-29 años registraron tasas de infección inferiores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f02") }, {"long_answer": "Para la temporada 2025-2026 se dispondrá de vacunas frente a COVID-19 de ARN mensajero adaptadas a las variantes circulantes y de vacunas basadas en proteínas recombinantes, que constituyen las dos plataformas autorizadas y utilizadas en la campaña. Las vacunas de virus inactivado y las vectoriales de adenovirus no se utilizan en España en esta temporada. Afirmar que solo habrá vacunas de ARNm es incorrecto, ya que también se incluye la plataforma de proteína recombinante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0a") }, {"long_answer": "Las recomendaciones establecen que la campaña de vacunación frente a COVID-19 de la temporada 2025-2026 se inicie en la última semana de septiembre y se desarrolle durante octubre, de forma coordinada con la vacunación antigripal, para alcanzar la máxima protección antes del periodo de mayor circulación de virus respiratorios. La primera semana de agosto es demasiado temprana. Finales de noviembre o enero de 2026 retrasarían la protección de los grupos de riesgo frente a la onda estacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0c") }, {"long_answer": "Entre las condiciones de riesgo que justifican la vacunación frente a COVID-19 en la temporada 2025-2026 figuran, entre otras, la obesidad mórbida, la diabetes mellitus, las hemoglobinopatías y los trastornos de la coagulación, así como las enfermedades crónicas cardiovasculares, respiratorias, renales o hepáticas y la inmunosupresión. El hipotiroidismo en tratamiento sustitutivo bien controlado, en ausencia de otras patologías, no se incluye por sí solo en ese listado, por lo que no justifica la indicación de vacunación como grupo de riesgo.", "option_3": "Hipotiroidismo en tratamiento sustitutivo bien controlado, sin otras patologías"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f0d") }, {"long_answer": "El documento propone establecer estrategias de captación activa durante la campaña para mejorar las coberturas en los grupos prioritarios, reforzando la vacunación de las personas mayores, en especial las que viven en residencias, y de las personas con condiciones de riesgo clínico, que son las que tienen más riesgo de enfermedad grave. No se busca mejorar la cobertura en personas sin factores de riesgo. Tampoco se pretende vacunar exclusivamente en hospitales ni reducir costes logísticos como objetivo principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f10") }, {"long_answer": "Las recomendaciones consideran que las personas tratadas con inhibidores de JAK u otros fármacos moduladores inmunitarios en los tres meses anteriores a la vacunación tienen una inmunosupresión relevante que justifica una dosis adicional, ya que su respuesta a la vacuna puede ser insuficiente. Un tratamiento finalizado hace más de seis meses no se considera indicación. Es falso que nunca se consideren indicativos, y la vía de administración intravenosa no es el criterio que determina la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f13") }, {"long_answer": "En la temporada 2025-2026, las personas de los grupos a vacunar que ya tienen vacunación previa completa, con o sin antecedente de infección, deben recibir una sola dosis de vacuna adaptada, salvo situaciones especiales de inmunosupresión grave. Las pautas ampliadas de tres dosis no están indicadas en este contexto. No vacunar no es lo recomendado en los grupos diana, ya que la protección disminuye con el tiempo, y el número de dosis no se ajusta según el nivel de anticuerpos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f14") }, {"long_answer": "Según los datos del Sistema de Vigilancia de Infección Respiratoria Aguda (SiVIRA) recogidos en las recomendaciones, durante la temporada 2024-2025 el SARS-CoV-2 circuló en España en niveles bajos, sin ondas epidémicas destacadas hasta la semana 23 de 2025. No se produjeron picos epidémicos altos y constantes durante toda la temporada. Tampoco hubo ausencia total del virus, que siguió circulando a bajo nivel, ni un incremento exponencial de casos en menores de seis meses."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f20") }, {"long_answer": "Las recomendaciones de vacunación antigripal 2025-2026 incluyen entre las condiciones de riesgo de las personas de 5 a 59 años, entre otras, la diabetes mellitus y el síndrome de Cushing, la inmunosupresión y la enfermedad hepática crónica. En el caso de las enfermedades cardiovasculares, el documento excluye expresamente la hipertensión arterial aislada, por lo que una persona hipertensa sin otras condiciones no forma parte de este grupo de riesgo. Las demás opciones sí figuran en el listado de condiciones que indican la vacunación.", "option_3": "Hipertensión arterial aislada sin otras condiciones"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f25") }, {"long_answer": "En la vacunación antigripal, los niños menores de 9 años que se vacunan por primera vez, incluidos los prematuros de menos de 32 semanas de gestación entre los 6 y los 24 meses de edad, deben recibir dos dosis separadas por al menos cuatro semanas, para conseguir una respuesta inmunitaria adecuada. Una única dosis anual se aplica en temporadas posteriores, cuando ya han recibido la primovacunación. La pauta de tres dosis cada dos semanas no existe, y la pauta no depende de la disponibilidad de vacunas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2a") }, {"long_answer": "Las recomendaciones de vacunación antigripal incluyen, entre los grupos a vacunar para mantener los servicios críticos y esenciales para la comunidad, a las fuerzas y cuerpos de seguridad del Estado, los bomberos y los servicios de protección civil, entre otros. El personal de oficinas de farmacia no se encuadra en ese grupo, sino en el del personal de centros y establecimientos sanitarios, cuya vacunación se recomienda para proteger a los pacientes y reducir la transmisión en el ámbito asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f34") }, {"long_answer": "Según las recomendaciones de vacunación antigripal 2025-2026, la estimación del sistema de vigilancia para la temporada 2024-2025 fue de aproximadamente 1,71 millones de casos de gripe atendidos en atención primaria en España, además de un elevado número de hospitalizaciones y defunciones atribuibles. La cifra de 1,20 millones infravalora la carga de la temporada, mientras que 2,5 millones la sobrestima. Los 700.000 casos quedan muy por debajo del dato publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3f") }, {"long_answer": "El documento de vacunación en mujeres en edad fértil, embarazo y puerperio indica que la vacuna frente a la hepatitis B se recomienda a las mujeres que no estén vacunadas y pertenezcan a grupos de riesgo o presenten conductas de riesgo, así como tras una exposición potencial al virus. No se recomienda vacunar sistemáticamente a todas las mujeres en edad fértil, ya que la mayoría de las jóvenes españolas fueron vacunadas en la infancia. Las mujeres con AgHBs positivo ya están infectadas y no se benefician de la vacuna, y la pauta estándar consta de tres dosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f41") }, {"long_answer": "Durante el embarazo se recomienda de forma rutinaria la vacuna dTpa (difteria, tétanos y tosferina de baja carga antigénica), preferentemente entre las semanas 27 y 32 de gestación, en cada embarazo, para que la transferencia transplacentaria de anticuerpos proteja al recién nacido frente a la tosferina en sus primeros meses de vida. La triple vírica y la vacuna de la varicela son vacunas atenuadas contraindicadas en el embarazo. La vacuna de la hepatitis B solo se indica en gestantes con riesgo, no como medida frente a la tosferina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f45") }, {"long_answer": "Según el documento, la vacuna neumocócica polisacárida 23-valente (VNP23) no se administra de forma universal en el embarazo, pero puede indicarse en el segundo y tercer trimestre en mujeres con condiciones de riesgo de enfermedad neumocócica invasiva, por ejemplo asplenia o inmunodepresión, cuando no puede esperarse al posparto. No es cierto que esté contraindicada en todo momento del embarazo. Tampoco se recomienda tras el parto en todos los casos, sino solo en mujeres con indicación por factores de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f49") }, {"long_answer": "Las mujeres que reciban vacunas de virus vivos atenuados, como la triple vírica o la de la varicela, deben evitar el embarazo durante el mes siguiente a cada dosis, por el riesgo teórico de infección fetal por el virus vacunal; no obstante, una vacunación inadvertida durante la gestación no justifica interrumpirla. Ignorar este intervalo es incorrecto. No es necesario evitar cualquier vacunación durante toda la vida fértil, y no está indicado ningún tratamiento antirretroviral después de la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4a") }, {"long_answer": "En la mujer embarazada sin evidencia documental de inmunidad frente a varicela (sin dos dosis de vacuna registradas ni antecedente fiable de enfermedad) se solicita la determinación de IgG frente al virus varicela zóster, que indica si existe protección previa. Si es negativa, la vacuna no puede administrarse durante la gestación por ser de virus vivos atenuados, y se pospone al puerperio, informando a la mujer de que evite el contacto con casos. La IgM de hepatitis B y el AgHBs se relacionan con el cribado de hepatitis B, no con la varicela, y la IgG de sarampión valora la inmunidad frente a otra enfermedad distinta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4c") }, {"long_answer": "La vacuna frente a la hepatitis B es inactivada (recombinante) y el embarazo no supone una contraindicación. Por ello, en la embarazada con alto riesgo de exposición al virus se recomienda iniciar o continuar durante la gestación la pauta completa de vacunación, ya que la infección materna supone un riesgo grave tanto para la madre como para el recién nacido. Esperar al posparto deja a la mujer desprotegida durante el periodo de riesgo, y un AgHBs positivo indica infección, situación en la que la vacuna ya no está indicada. Afirmar que nunca se debe vacunar a una embarazada es incorrecto, puesto que las vacunas inactivadas pueden utilizarse cuando están indicadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f4e") }, {"long_answer": "La vacunación frente al virus del papiloma humano no se aconseja durante el embarazo porque no existen datos suficientes de seguridad, aunque en los casos de administración inadvertida no se han observado efectos adversos sobre la gestación ni el feto. Si una mujer queda embarazada tras iniciar la pauta, las dosis pendientes se posponen hasta después del parto, sin necesidad de interrumpir la gestación. No es una vacuna recomendada de forma rutinaria en el embarazo, no se limita exclusivamente al puerperio como norma general y tampoco se plantea su administración durante la gestación por exposición de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f51") }, {"long_answer": "Las vacunas inactivadas no suponen riesgo teórico para el feto, por lo que en situaciones especiales de riesgo o exposición pueden administrarse durante el embarazo vacunas como la de la rabia, la hepatitis A, la fiebre tifoidea polisacárida parenteral o la poliomielitis inactivada (VPI), valorando siempre el beneficio frente al riesgo. En cambio, la triple vírica, la BCG, la varicela, la antigripal intranasal, la tifoidea oral y la fiebre amarilla son vacunas de microorganismos vivos atenuados, contraindicadas de forma general durante la gestación; la fiebre amarilla solo se valoraría de forma excepcional si el viaje a zona endémica es inevitable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f52") }, {"long_answer": "Se considera que una mujer es inmune frente a la rubeola, sin necesidad de serología, cuando tiene documentada al menos una dosis de vacuna triple vírica o de vacuna atenuada frente a rubeola administrada después de los 12 meses de edad, ya que una sola dosis induce seroconversión en la gran mayoría de las personas. El antecedente clínico de enfermedad no se acepta como prueba de inmunidad porque el diagnóstico clínico de rubeola es poco fiable. La vacuna antigripal y la de hepatitis B no confieren ninguna protección frente a la rubeola, por lo que son opciones incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f54") }, {"long_answer": "Ante una serología de rubeola negativa o dudosa en una mujer previamente vacunada se recomienda administrar una dosis adicional de vacuna triple vírica, sin superar un máximo de tres dosis en total, y no es necesario repetir la serología después. Si tras ello sigue sin detectarse protección, se considera que la mujer ha recibido la vacunación adecuada y no se administran más dosis. No intervenir dejaría a la mujer potencialmente susceptible; no existe tratamiento antiviral para la prevención de la rubeola, y la inmunoglobulina específica no es la medida indicada para conseguir inmunidad duradera en mujeres en edad fértil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f55") }, {"long_answer": "La vacuna dTpa (tétanos, difteria y tosferina de baja carga antigénica) se recomienda de forma sistemática en cada embarazo, preferentemente entre las semanas 27 y 28 de gestación, aunque puede administrarse en todo el tercer trimestre. Los anticuerpos maternos atraviesan la placenta y protegen al recién nacido frente a la tosferina en los primeros meses de vida, antes de que pueda completar su propia vacunación. La triple vírica es de virus vivos y está contraindicada en el embarazo, y ni la vacuna de hepatitis A ni la neumocócica conjugada se emplean de rutina en la gestación ni protegen frente a la tosferina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5a") }, {"long_answer": "Según el documento de consenso del Sistema de Información de los programas de Cribado de Cáncer (SICC), la carga anual de datos se realiza entre el 1 de enero y el 31 de marzo del segundo año consecutivo al año de estudio. Este desfase permite que se completen los procesos de cribado iniciados en el año índice, incluyendo pruebas de confirmación diagnóstica y tratamientos, de forma que los indicadores calculados reflejen resultados definitivos. Los periodos que coinciden con el propio año índice o con el inicio del año inmediatamente posterior no dejan tiempo suficiente para cerrar el seguimiento de las personas cribadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5b") }, {"long_answer": "En el cribado de cáncer de cérvix se considera invitación válida la enviada a una mujer elegible, por correo postal, SMS u otro medio establecido, que no haya sido devuelta, ya que solo así puede asumirse que la mujer ha tenido la oportunidad real de participar. No deben contabilizarse las invitaciones enviadas a mujeres con criterios de exclusión, porque no forman parte de la población elegible. Tampoco se cuentan como nuevas invitaciones las repetidas dentro de la misma ronda para pruebas intermedias o de seguimiento, ni las actividades derivadas del cribado oportunista, que distorsionarían los indicadores de participación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5d") }, {"long_answer": "En las mujeres vacunadas frente al VPH antes de los 15 años la probabilidad de lesiones precancerosas es muy baja, por lo que se recomienda iniciar el cribado a los 30 años mediante la determinación de VPH de alto riesgo como prueba primaria, repetida cada 5 años si es negativa. La citología trienal desde los 25 años corresponde a la estrategia de las mujeres no vacunadas menores de 30 años. La citología anual desde los 18 años supone un sobrecribado sin beneficio, y suprimir el cribado no está indicado, ya que la vacuna no protege frente a todos los genotipos oncogénicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f62") }, {"long_answer": "Ante una citología de adenocarcinoma in situ (AIS) o síntomas compatibles con cáncer de cuello uterino se establece un tiempo máximo inferior a 2 semanas para realizar la colposcopia, porque la sospecha de lesión glandular o de carcinoma exige una confirmación diagnóstica y un tratamiento precoces. Los plazos más amplios, de 4, 8 o 12 semanas, se reservan para resultados de menor gravedad, como las lesiones de bajo grado o los hallazgos que requieren estudio sin sospecha de malignidad. Retrasar la colposcopia en estos casos podría empeorar el pronóstico y no se ajusta a los estándares de calidad del programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f65") }, {"long_answer": "El documento establece que el sistema de información de un programa de cribado debe ser operativo, fiable, factible, válido y de calidad, de modo que permita registrar a toda la población diana, gestionar invitaciones y resultados y calcular los indicadores de evaluación con datos consistentes. Un sistema exclusivamente manual sería poco eficiente y más propenso a errores. El acceso público sin autenticación vulneraría la confidencialidad y la protección de los datos personales de salud, y limitar el sistema a la gestión financiera impediría evaluar el proceso y los resultados del cribado, que es su finalidad principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f66") }, {"long_answer": "La tasa de detección en el cribado de cáncer de mama incluye en el numerador a las mujeres diagnosticadas de cáncer, tanto carcinoma ductal in situ como carcinoma invasivo, confirmado histológicamente tras la biopsia, y en el denominador a las mujeres cribadas. Las alteraciones mamográficas sin confirmación no son diagnóstico de cáncer, sino motivo de valoración adicional, y se reflejan en la tasa de rellamada. Las biopsias negativas no son casos detectados. El carcinoma lobulillar in situ se considera un marcador de riesgo y no un cáncer, por lo que no se contabiliza como detección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f71") }, {"long_answer": "En la clasificación FIGO 2018 del cáncer de cuello uterino, el estadio II corresponde al tumor que se extiende más allá del útero sin alcanzar el tercio inferior de la vagina ni la pared pélvica. Dentro de él, el estadio IIB se define por la afectación parametrial sin llegar a la pared pélvica. La invasión de los dos tercios superiores de la vagina sin afectación parametrial corresponde al estadio IIA. El tumor limitado estrictamente al cuello uterino es estadio I, y la afectación de ganglios paraaórticos se clasifica como IIIC2, por lo que no definen el estadio IIB."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e74") }, {"long_answer": "Tal como recoge la presentación de la guía, el Consejo Interterritorial del Sistema Nacional de Salud creó en el año 2003 el proyecto GuíaSalud, cuyo objetivo final es mejorar la toma de decisiones clínicas basadas en la evidencia científica mediante actividades de formación y la configuración de un registro de guías de práctica clínica en el SNS. Posteriormente, en el marco del Plan de Calidad, se impulsó la elaboración de nuevas guías dentro del Programa de GPC en el SNS. Los años 1999, 2006 y 2010 no corresponden a la creación de este proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e75") }, {"long_answer": "El Plan de Calidad para el Sistema Nacional de Salud persigue garantizar la máxima calidad de la atención sanitaria a todos los ciudadanos con independencia de su lugar de residencia, favoreciendo la equidad y la cohesión del sistema; en este marco se impulsa la elaboración de guías de práctica clínica como la de atención al parto normal. No pretende concentrar la atención en grandes hospitales urbanos, ni imponer una supervisión médica obligatoria del parto normal, que puede ser atendido por matronas, ni fija como objetivo reducir la estancia hospitalaria a menos de 24 horas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e77") }, {"long_answer": "Una guía de práctica clínica se caracteriza por contener recomendaciones elaboradas a partir de una revisión sistemática de la evidencia y graduadas según la calidad de los estudios que las apoyan, lo que permite al profesional conocer la solidez de cada recomendación. Solo cuando no existe evidencia suficiente se recurre al consenso del grupo elaborador, pero no constituye la base exclusiva. Las descripciones anecdóticas sin base científica son precisamente lo que las guías pretenden evitar, y esta guía aborda la atención al parto normal en su conjunto, no únicamente las cesáreas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e79") }, {"long_answer": "Las recomendaciones de una guía de práctica clínica son una ayuda para la toma de decisiones, pero no sustituyen el juicio clínico de los profesionales sanitarios, que deben adaptarlas a las circunstancias concretas de cada mujer y de cada parto, teniendo en cuenta además sus preferencias. La guía no establece ninguna necesidad de supervisión médica cada 5 minutos ni la aplicación automática de intervenciones farmacológicas, ideas contrarias a su enfoque de atención respetuosa y basada en la evidencia. Del mismo modo, la guía no se plantea como sustituto de la información y la participación de la mujer en las decisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7a") }, {"long_answer": "La participación de mujeres y asociaciones en la elaboración de la guía aporta la perspectiva directa de las usuarias sobre qué cuidados consideran adecuados, cuáles son sus expectativas y cómo viven la experiencia del parto, lo que permite que las recomendaciones sean más aceptables y centradas en la mujer. No se limita a aportar datos estadísticos, que proceden de la revisión de la evidencia, ni tiene como finalidad aumentar el uso de analgesia. Tampoco produce instrucciones dirigidas únicamente a médicos, ya que la guía está pensada para todos los profesionales implicados, incluidas las matronas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7b") }, {"long_answer": "El beneficio esperado de la guía es mejorar la calidad de la atención al parto normal y la experiencia global de las mujeres, ofreciendo cuidados basados en la evidencia, evitando intervenciones innecesarias y respetando la fisiología del parto y la autonomía de la mujer. Incrementar las cesáreas en partos normales sería contrario a la evidencia y aumentaría la morbilidad. La guía reconoce el papel central de las matronas en la atención al parto normal y promueve que la mujer pueda elegir entre distintas opciones, por lo que no defiende un modelo rígido de atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e7d") }, {"long_answer": "El dossier sobre cannabinoides sintéticos señala que su consumo ilícito se ha asociado a trastornos psicóticos, a intoxicaciones graves que pueden requerir atención urgente e incluso causar la muerte, y a un posible potencial cancerígeno de algunos compuestos y productos de degradación. No se trata de sustancias con efectos leves y sin riesgo de intoxicación; al contrario, su potencia es muy superior a la del cannabis natural. Tampoco mejoran el rendimiento cognitivo, y compararlos con el alcohol minimizando sus riesgos graves es incorrecto, dado su perfil de toxicidad aguda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e81") }, {"long_answer": "Los cannabinoides sintéticos suelen ser más tóxicos que el cannabis natural porque actúan como agonistas totales de los receptores cannabinoides CB1 y CB2, con mayor afinidad, potencia y eficacia que el THC, que es solo un agonista parcial. Esto produce efectos más intensos e imprevisibles con dosis muy pequeñas. No contienen siempre alcohol ni disolventes, aunque puedan aparecer en algunos productos. Su consumo no se asocia a dosis menores que reduzcan el riesgo, y precisamente carecen del cannabidiol (CBD), que en la planta modula y atenúa parte de los efectos psicoactivos del THC."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e83") }, {"long_answer": "Según los datos recogidos en el dossier, las prevalencias de consumo de cannabinoides sintéticos más elevadas se observan en subpoblaciones concretas, como las personas privadas de libertad, en las que se usan por su difícil detección en los controles, y los policonsumidores de otras drogas. Los niños menores de 10 años no constituyen un grupo de consumo, y los adultos mayores en residencias o los pacientes con enfermedad cardiovascular establecida no aparecen como poblaciones con mayor prevalencia, aunque estos últimos sí podrían sufrir consecuencias más graves en caso de consumo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e85") }, {"long_answer": "Entre los efectos adversos agudos más comunicados tras el consumo de cannabinoides sintéticos figuran la ansiedad, la agitación, las náuseas y vómitos, la paranoia y la taquicardia, reflejo de su intensa acción sobre el sistema nervioso central y el cardiovascular. La sedación profunda con bradicardia no es el cuadro típico, que suele ser simpaticomimético con taquicardia e hipertensión. La hipotermia grave con pérdida de conciencia prolongada no es el efecto más habitual, y la hiperglucemia y las hemorragias digestivas no figuran entre los efectos agudos característicos de estas sustancias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e8f") }, {"long_answer": "De acuerdo con los datos del sistema europeo de alerta temprana recogidos en el dossier, el MDMB-4en-PINACA fue el cannabinoide sintético más detectado en Europa hasta 2020, presente en una gran proporción de incautaciones y asociado a intoxicaciones graves. El JWH-018 y el AM-2201 pertenecen a generaciones anteriores de cannabinoides sintéticos, muy frecuentes en los primeros productos tipo Spice, pero posteriormente sustituidos tras su control legal. El ADB-BUTINACA ganó protagonismo después, como uno de los compuestos de aparición más reciente en el mercado europeo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e90") }, {"long_answer": "Las intoxicaciones graves por cannabinoides sintéticos se relacionan, en algunos productos adulterados, con la adición de sustancias aún más peligrosas, como opioides sintéticos del tipo fentanilo, y con una distribución desigual del compuesto en el material vegetal, que genera zonas con concentraciones muy altas e imprevisibles para el consumidor. Los materiales vegetales puros sin aditivos no son el origen del problema, ya que el producto se rocía con sustancias sintéticas. El consumo supervisado por personal sanitario no existe en este contexto, y el CBD no se añade en dosis controladas, ya que los cannabinoides sintéticos carecen de él."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e92") }, {"long_answer": "El dossier recoge que los síntomas psicóticos tras el consumo de cannabinoides sintéticos aparecen con mayor frecuencia en hombres jóvenes, y que pueden presentarse incluso en personas sin antecedentes familiares ni historia previa de trastornos mentales, lo que pone de relieve el elevado potencial psicotógeno de estas sustancias. Los adultos mayores con enfermedades cardiovasculares, los niños menores de 12 años y las mujeres embarazadas no se señalan como los grupos más propensos a desarrollar síntomas psicóticos, sino que corresponden a perfiles de consumo poco habituales en los datos disponibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e96") }, {"long_answer": "Las noticias en los medios sobre posibles usos terapéuticos de los cannabinoides sintéticos pueden generar confusión entre la población y, al no basarse en información contrastada, influir en la actitud hacia su consumo, transmitiendo una falsa percepción de seguridad. No reducen la curiosidad de los adolescentes, sino que pueden aumentarla. Tampoco garantizan que el consumo se limite a usos medicinales certificados por las autoridades sanitarias ni que las personas conozcan los riesgos asociados, ya que precisamente la falta de información rigurosa es el problema señalado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e99") }, {"long_answer": "El cannabis natural contiene cannabidiol (CBD), que modula y atenúa algunos efectos psicoactivos y adversos del THC, como la ansiedad o los síntomas psicóticos. Los cannabinoides sintéticos carecen de CBD, de modo que su potente efecto agonista no se ve contrarrestado, lo que se traduce en un mayor potencial tóxico. Por ello no tienen menor riesgo cardiovascular, sino que se asocian a taquicardia, arritmias e infarto. Tampoco existe una efectividad terapéutica demostrada en estudios clínicos para los productos ilícitos, y su potencia psicoactiva y capacidad adictiva son mayores, no menores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9a") }, {"long_answer": "Para ayudar a una persona con problemas por consumo de cannabinoides sintéticos se recomienda escucharla, aceptar sus preocupaciones sin juzgar y construir una relación de confianza, como base para abordar el consumo como un problema de salud y facilitar el acceso a recursos especializados. Exigir la abstinencia absoluta sin apoyo psicológico reduce la adherencia y no responde a un enfoque sanitario integral. Los anticoagulantes no tienen ningún papel en este contexto, y promover un consumo controlado no es una recomendación adecuada ante sustancias de toxicidad tan elevada e imprevisible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9e") }, {"long_answer": "La escala FRAIL evalúa cinco dimensiones: fatiga, resistencia, deambulación, comorbilidad y pérdida de peso. En su adaptación española, FRAIL-España, se considera que el paciente es frágil cuando están presentes 3 o más dimensiones. La presencia de 1 o 2 dimensiones identifica a la persona prefrágil, no frágil. No es necesario que estén presentes las cinco dimensiones para establecer la fragilidad, y la ausencia de todas ellas corresponde a una persona robusta o no frágil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977e9f") }, {"long_answer": "En el estudio de fiabilidad de la CFS-España y la FRAIL-España realizado en pacientes críticos, la CFS-España clasificó como no frágiles al 53% de los pacientes evaluados, por lo que la mayoría no presentaba fragilidad según esta escala. El resto de los pacientes se distribuyó entre las categorías de vulnerabilidad y fragilidad. Las cifras de 34%, 44% y 70% no corresponden a la proporción de pacientes no frágiles según la CFS-España recogida en el estudio, aunque algunas de ellas aparezcan en el documento referidas a otros resultados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eaf") }, {"long_answer": "El documento menciona un estudio realizado en 4 unidades de cuidados intensivos españolas que, utilizando la escala FRAIL en pacientes mayores de 65 años, encontró una prevalencia de fragilidad del 34,9%. Este dato muestra que aproximadamente uno de cada tres pacientes mayores ingresados en UCI es frágil, lo que justifica valorar la fragilidad por su influencia en el pronóstico. El 53% corresponde a la proporción de pacientes no frágiles según la CFS-España en el estudio principal, y las cifras de 30% y 16% no corresponden a la prevalencia descrita en ese estudio multicéntrico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb0") }, {"long_answer": "Entre las adaptaciones de la Clinical Frailty Scale citadas en el documento, la versión portuguesa es la que ha comunicado valores de fiabilidad intraobservador cercanos a 0,999, lo que indica una concordancia casi perfecta cuando el mismo evaluador aplica la escala en dos momentos. Las versiones brasileña, francesa y española también han mostrado buena fiabilidad, pero no se les atribuye este valor concreto. De hecho, uno de los objetivos del estudio era precisamente analizar la fiabilidad de la versión española en pacientes críticos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb3") }, {"long_answer": "Según la clasificación de Landis y Koch para interpretar el índice Kappa, los valores entre 0,61 y 0,80 corresponden a un acuerdo sustancial. Los valores de 0,81 a 1,00 indican un acuerdo casi perfecto, los de 0,41 a 0,60 un acuerdo moderado y los de 0,21 a 0,40 un acuerdo aceptable o débil. Por debajo de 0,20 el acuerdo se considera leve o pobre. Esta clasificación se utiliza en el estudio para valorar la concordancia inter e intraobservador de las escalas de fragilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb7") }, {"long_answer": "La Clinical Frailty Scale gradúa a los pacientes del 1 al 9. En la estratificación utilizada en el estudio con la CFS-España, la opción A agrupa los niveles 1 a 3 como no frágiles, el nivel 4 como vulnerable y los niveles 5 a 9 como frágiles. Por tanto, la categoría vulnerable corresponde al nivel 4, que describe a personas que no dependen de otros para su vida diaria pero cuyos síntomas limitan su actividad. El nivel 9 corresponde al paciente con enfermedad terminal, incluido dentro de la fragilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eb8") }, {"long_answer": "En el documento la fragilidad se define como un estado de mayor vulnerabilidad a presentar resultados adversos tras sufrir eventos de baja intensidad o banales, debido a la disminución de la reserva fisiológica. Esta definición es especialmente relevante en cuidados intensivos, donde la fragilidad previa condiciona la evolución. La fragilidad no se identifica con una edad determinada, como superar los 80 años, ni equivale a la presencia de enfermedades crónicas o a la comorbilidad, aunque se relacione con ellas. Tampoco es sinónimo de dependencia total para las actividades básicas, que es una situación más avanzada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ebf") }, {"long_answer": "El estudio reconoce como limitación que no fue posible evaluar a todos los pacientes por todos los profesionales en dos momentos distintos, debido a circunstancias clínicas, como el empeoramiento o el alta del paciente, o a condiciones asistenciales de la unidad. Por ello, el análisis de concordancia intraobservador se realizó sobre los pacientes en los que sí pudo repetirse la valoración. Afirmar que se evaluó a todos en dos momentos o que todos se evaluaron una sola vez sin excepciones contradice lo descrito, y el estudio sí especifica esta circunstancia.", "question": "En el estudio, ¿qué ocurrió respecto a la evaluación de todos los pacientes por todos los profesionales en dos momentos distintos?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec0") }, {"long_answer": "El sistema suizo revisado clasifica la hipotermia accidental según la temperatura central y los signos clínicos. La hipotermia leve o grado I corresponde a temperaturas entre 35 y 32 °C, con el paciente consciente y habitualmente tiritando. El rango de 32 a 28 °C corresponde al grado II o moderado, el de 28 a 24 °C al grado III o grave, y las temperaturas inferiores a 24 °C, hasta 11,8 °C, que es la temperatura más baja con supervivencia documentada, se asocian al grado IV."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec2") }, {"long_answer": "En el sistema suizo revisado, el grado III de hipotermia corresponde a una víctima inconsciente pero con signos vitales presentes, con un riesgo alto de parada cardíaca, lo que obliga a una movilización muy cuidadosa y a valorar el traslado a un centro con soporte vital extracorpóreo. La víctima somnolienta o con respuesta verbal alterada corresponde al grado II, mientras que el temblor activo con consciencia conservada es propio del grado I. La muerte aparente con ausencia de signos vitales define el grado IV o parada cardíaca hipotérmica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec3") }, {"long_answer": "En el sistema suizo revisado, el paciente con ausencia completa de signos vitales se clasifica como grado IV, que corresponde a la parada cardíaca hipotérmica o muerte aparente. Estos pacientes pueden tener posibilidades de supervivencia con buena recuperación neurológica si se realizan reanimación prolongada y recalentamiento, idealmente con soporte vital extracorpóreo. El grado II describe una consciencia alterada y el grado III un paciente inconsciente con signos vitales presentes. El grado V, que se refería a la muerte irreversible, fue eliminado en la revisión del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec4") }, {"long_answer": "En la revisión del sistema suizo de estadificación de la hipotermia accidental se eliminó el grado V, que correspondía a la muerte por hipotermia irreversible, porque no es posible establecer de forma fiable la irreversibilidad en el ámbito prehospitalario y la clasificación debe orientar la actuación y no excluir pacientes. El sistema revisado queda con cuatro grados, el último de los cuales es la parada cardíaca hipotérmica. Por tanto, el grado V no se amplió, no se estableció como el más frecuente ni se redefinió con otros límites de temperatura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ec9") }, {"long_answer": "En el sistema suizo revisado, el nivel de consciencia valorado con la escala AVDN se relaciona con el riesgo de parada cardíaca: la víctima alerta tiene un riesgo bajo, la que responde a la voz un riesgo moderado y la que solo responde al dolor un riesgo alto. El nivel de mayor gravedad es la ausencia de respuesta acompañada de ausencia de signos vitales, que corresponde a la parada cardíaca hipotérmica (grado IV). Las demás opciones describen niveles intermedios de consciencia, con riesgo bajo, moderado o alto, pero no la situación más grave de la escala.", "question": "Según el sistema suizo revisado, ¿qué nivel de la escala AVDN y riesgo asociado corresponde a la situación de mayor gravedad?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ecd") }, {"long_answer": "La escala AVDN estima la gravedad de la hipotermia a partir del nivel de consciencia, pero su precisión se ve afectada cuando existen otras causas de alteración neurológica, como asfixia, intoxicaciones, edema cerebral o traumatismos, especialmente el craneoencefálico. En estas situaciones la disminución de consciencia puede no deberse a la hipotermia y llevar a sobrestimar su grado. La hipertensión con fiebre no es un escenario propio de la hipotermia, una glucemia normal no interfiere con la valoración, y el antecedente de hipotiroidismo no altera por sí mismo la aplicación de la escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ece") }, {"long_answer": "Las recomendaciones del Consejo Europeo de Resucitación de 2021, en el capítulo de parada cardíaca en circunstancias especiales, indican que la elección del tratamiento y del hospital de destino en la hipotermia grave debe basarse en el riesgo de parada cardíaca inminente o en la presencia de parada cardíaca hipotérmica. Los pacientes con factores de riesgo de parada o en parada deben trasladarse a un centro con soporte vital extracorpóreo. La medición subjetiva de la temperatura no es fiable, y ni el tiempo de exposición ni la edad y comorbilidades son el criterio principal para decidir el destino.", "option_2": "El riesgo de parada cardíaca inminente o la presencia de parada cardíaca hipotérmica"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ecf") }, {"long_answer": "El término parada cardíaca hipotérmica describe en el sistema suizo revisado la situación de muerte aparente propia de la hipotermia profunda, es decir, el grado IV, en el que no hay signos vitales detectables. Estas víctimas no deben considerarse fallecidas sin intentar la reanimación y el recalentamiento, ya que el frío ejerce un efecto protector sobre el cerebro. La hipotermia leve sin afectación hemodinámica corresponde al grado I, la somnolencia con temblor al grado II, y la respuesta verbal con signos vitales estables no describe una parada cardíaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed1") }, {"long_answer": "El sistema suizo revisado resulta útil en el medio prehospitalario porque permite estimar la gravedad de la hipotermia y el riesgo de parada cardíaca a partir de signos clínicos, como el nivel de consciencia y la presencia de signos vitales, cuando no es posible medir la temperatura central de forma fiable. No permite obtener mediciones de temperatura sin equipo, sino que las sustituye por la valoración clínica. Tampoco reemplaza la necesidad de traslado hospitalario, que suele ser imprescindible, ni está diseñado para diagnosticar traumatismos asociados, que de hecho dificultan su aplicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed4") }, {"long_answer": "La escala de coma de Glasgow es la escala de coma de referencia con la que se correlacionan los niveles de consciencia empleados en el sistema suizo revisado, que utiliza la escala AVDN para estimar el grado de hipotermia. La escala Rancho Los Amigos valora la evolución cognitiva tras un traumatismo craneoencefálico, la escala de Ramsay mide el nivel de sedación en pacientes críticos y la Canadian Neurological Scale se emplea en la valoración del ictus, por lo que ninguna de ellas se utiliza para este fin.", "option_3": "Escala de Ramsay"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed8") }, {"long_answer": "En la clasificación suiza revisada, la hipotermia profunda o grado IV se asocia a temperaturas inferiores a 24 °C, con un límite inferior de 11,8 °C, que corresponde a la temperatura central más baja con supervivencia documentada tras una hipotermia accidental. Los rangos de 32 a 35 °C, 28 a 32 °C y 24 a 28 °C corresponden respectivamente a la hipotermia leve, moderada y grave, es decir, a los grados I, II y III de la clasificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ed9") }, {"long_answer": "Aunque el sistema suizo revisado se basa en signos clínicos, siempre que sea posible debe confirmarse la temperatura central con un método de medida fiable, como la sonda esofágica en el paciente con vía aérea aislada o un termómetro epitimpánico adecuado, ya que la clínica puede verse alterada por otras causas. Iniciar la reanimación sin medir la temperatura solo procede si no hay signos vitales, sin retrasar la actuación. Administrar líquidos fríos empeoraría la hipotermia; deben usarse calientes. Afirmar que nunca es necesario confirmar la temperatura contradice las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eda") }, {"long_answer": "En la hipotermia accidental grave o grado III del sistema suizo revisado, la víctima está inconsciente pero mantiene signos vitales, aunque pueden ser difíciles de detectar por la bradicardia y la bradipnea, por lo que la valoración debe prolongarse hasta un minuto. La ausencia de signos vitales define el grado IV o parada cardíaca hipotérmica. La víctima consciente que tiembla activamente corresponde al grado I, y la víctima somnolienta con temblor ausente o intermitente se asocia al grado II."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977edb") }, {"long_answer": "En el sistema suizo revisado se entiende por muerte aparente en hipotermia profunda la ausencia de signos vitales en un paciente con temperatura central entre 11,8 y 24 °C, situación potencialmente reversible que corresponde a la parada cardíaca hipotérmica (grado IV). Estos pacientes deben ser reanimados y recalentados, ya que pueden recuperarse sin secuelas. No se trata de una muerte irreversible, y la cifra de 4 °C no aparece en la clasificación. La inconsciencia con frecuencia cardíaca aumentada o el estado de alerta con temblor no definen la muerte aparente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee6") }, {"long_answer": "Según la guía de práctica clínica sobre trastornos de ansiedad, cuando no hay respuesta o se produce un empeoramiento tras 4 a 6 semanas de terapia cognitivo-conductual, se sugiere reevaluar el caso e iniciar tratamiento farmacológico o cambiar a otra terapia psicológica, en función de las preferencias del paciente. Mantener el mismo tratamiento prolongaría el sufrimiento sin beneficio, suspender todo tratamiento dejaría al paciente sin abordaje terapéutico, y limitarse a aumentar la frecuencia de las sesiones no da respuesta a la falta de eficacia observada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ee7") }, {"long_answer": "La guía formula una recomendación débil en contra del uso de la terapia psicodinámica en el trastorno de ansiedad generalizada, ya que la evidencia disponible muestra resultados inferiores a los de otras intervenciones, como la terapia cognitivo-conductual, que es el tratamiento psicológico de elección. Por ello no puede considerarse de primera línea ni, mucho menos, de uso obligatorio. Tampoco es correcto afirmar que no existen datos para recomendar, ya que la evidencia analizada permitió formular la recomendación en contra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977eea") }, {"long_answer": "Cuando un paciente con TAG presenta intolerancia a un ISRS que estaba siendo eficaz, la guía recomienda cambiar a otro ISRS, salvo que las reacciones adversas hayan sido graves, en cuyo caso, o si persiste la intolerancia, se pasará a un IRSN como venlafaxina o duloxetina. Suspender el tratamiento sin alternativa expone a recaídas, y aumentar la dosis del mismo fármaco empeoraría los efectos adversos. Las benzodiacepinas no deben pautarse de forma indefinida por el riesgo de tolerancia, dependencia y deterioro cognitivo, quedando para usos breves y concretos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef4") }, {"long_answer": "Para el uso de valeriana en el trastorno de ansiedad generalizada la guía no puede emitir una recomendación a favor ni en contra, ya que la evidencia disponible es escasa y de baja calidad para establecer su eficacia y seguridad. Por tanto, no puede recomendarse para mejorar los síntomas ni, menos aún, para los casos graves, en los que se dispone de tratamientos con eficacia demostrada. Tampoco se establece en la guía una contraindicación específica de su combinación con antidepresivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ef6") }, {"long_answer": "Cuando un paciente con trastorno de ansiedad generalizada no responde a las terapias psicológicas ni a dos opciones de tratamiento antidepresivo tras 12 semanas, la guía recomienda derivarlo al psiquiatra para una nueva valoración diagnóstica y del tratamiento, ya que puede tratarse de un caso resistente o con comorbilidad no identificada. Continuar esperando retrasa una atención adecuada, las benzodiacepinas a largo plazo no están indicadas por sus riesgos, y suspender el tratamiento dejaría al paciente sin abordaje."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f03") }, {"long_answer": "Las vacunas frente a la COVID-19 se actualizan cada temporada para adaptar su composición a las variantes del SARS-CoV-2 predominantes o emergentes, ya que el virus evoluciona continuamente y la protección frente a nuevas variantes disminuye con vacunas antiguas. De este modo se mejora la protección, sobre todo frente a la enfermedad grave en los grupos de riesgo. La actualización no tiene como fin abaratar la producción ni eliminar los efectos secundarios, y la inmunidad que confieren disminuye con los meses, por lo que no se pretende alcanzar una duración superior a 5 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f05") }, {"long_answer": "Las recomendaciones indican que, si no se dispone todavía de vacunas adaptadas a la variante seleccionada para la temporada, no debe retrasarse la vacunación y pueden utilizarse las vacunas autorizadas adaptadas a la variante KP.2, ya que siguen ofreciendo protección frente a la enfermedad grave. Las vacunas antigripales no protegen frente a la COVID-19, aunque puedan coadministrarse. No existe una vacuna de dosis única sin actualización como alternativa recomendada, y esperar a la vacuna actualizada dejaría desprotegidos a los grupos de riesgo durante la temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f09") }, {"long_answer": "Aunque la circulación actual del SARS-CoV-2 sea baja, la estrategia prioriza la vacunación de las personas con mayor riesgo de enfermedad grave y de quienes conviven con ellas o las cuidan, ya que vacunar a convivientes y cuidadores de personas de grupos de riesgo contribuye a protegerlas indirectamente. El personal sin contacto con personas vulnerables, los adolescentes sin comorbilidades y las personas sin factores de riesgo, con o sin vacunación previa, no constituyen grupos prioritarios en las recomendaciones de la temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f11") }, {"long_answer": "Entre los criterios de inmunosupresión extrema que justifican una dosis adicional de vacuna frente a la COVID-19 se incluye el tratamiento con corticoides a dosis altas, definido como más de 40 mg diarios de prednisona o equivalente durante más de una semana en el mes previo, ya que este tratamiento reduce notablemente la respuesta inmunitaria a la vacuna. Las dosis bajas, inferiores a 10 mg diarios, el uso esporádico en crisis agudas o las pautas cortas a dosis reducidas no alcanzan el grado de inmunosupresión que justifica pautas especiales de vacunación.", "option_1": "≥5 mg prednisona/día durante 3 días en el mes anterior"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f18") }, {"long_answer": "La vacunación frente a la COVID-19 como medida de salud pública se ampara en la Ley 33/2011, de 4 de octubre, General de Salud Pública, que regula las actuaciones de prevención y promoción de la salud, incluida la vacunación como estrategia de protección colectiva. La Ley 14/1986 General de Sanidad establece la organización del sistema sanitario, y el artículo 43 de la Constitución reconoce el derecho a la protección de la salud, pero no son la referencia específica citada. No existe ningún Decreto 2025/2025 del Ministerio de Sanidad sobre esta materia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1a") }, {"long_answer": "La pauta primaria de tres dosis se reserva para las personas que no tienen inmunidad previa frente al SARS-CoV-2, es decir, sin vacunación previa ni antecedente de infección, como ocurre en los niños pequeños de 6 meses a 4 años con la formulación pediátrica, en quienes una pauta más corta no asegura una respuesta adecuada. Quienes ya han completado la primovacunación o han pasado la infección solo necesitan una dosis estacional. La inmunosupresión leve sin tratamiento no exige una pauta de tres dosis, y una vacunación completa reciente no requiere reiniciar la pauta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f1d") }, {"long_answer": "Según los datos de vigilancia de la temporada 2024-2025, las mayores tasas de hospitalización por gripe se registraron en las personas de 70 años o más, que concentran la mayor carga de enfermedad grave, ingresos en UCI y defunciones, lo que justifica priorizar su vacunación. Los menores de 5 años también presentan tasas de hospitalización relevantes, pero inferiores a las de los mayores. Los grupos de 15 a 59 años y de 30 a 59 años son los que presentan las tasas de hospitalización más bajas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f22") }, {"long_answer": "Se recomienda vacunar frente a la gripe estacional a las personas con exposición laboral directa a aves, cerdos o visones en granjas o explotaciones para reducir la posibilidad de una coinfección por virus gripales humanos y animales, que podría favorecer la recombinación o reordenamiento genético y la aparición de nuevos virus con potencial pandémico. La vacunación no tiene como objetivo prevenir alergias ocupacionales, ni se relaciona con un mayor riesgo de enfermedad hepática, y se fundamenta en criterios epidemiológicos de salud pública, no en una obligación legal sin evidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f23") }, {"long_answer": "Para la temporada 2025-2026 se modificó el componente A(H3N2): en las vacunas producidas en huevos embrionados, la cepa análoga a A/Thailand/8/2022 se sustituyó por la análoga a A/Croatia/10136RV/2023, para adaptarse a los virus circulantes. El componente B/Victoria, representado por B/Austria/1359417/2021, se mantiene, por lo que no se eliminó. No se ha incorporado ninguna cepa de gripe C a las vacunas, y afirmar que no hubo cambios en la cepa A(H3N2) es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f27") }, {"long_answer": "Para la temporada 2025-2026 se mantiene como objetivo alcanzar o superar coberturas de vacunación antigripal del 75% en las personas de 60 años o más, en línea con las recomendaciones de la OMS y de la Unión Europea, así como en el personal sanitario y sociosanitario. Las cifras del 50% y del 60% están por debajo del objetivo establecido, y el 90% no es el objetivo fijado para este grupo de edad, aunque se aspire a coberturas lo más altas posibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f2b") }, {"long_answer": "Según los datos de la temporada 2024-2025 recogidos en las recomendaciones, aproximadamente el 94% de los fallecimientos asociados a la gripe se produjeron en personas de 60 años o más, lo que refleja la concentración de la mortalidad en las edades avanzadas y respalda la prioridad de vacunar a este grupo. Las cifras del 30% y del 50% subestiman claramente esta proporción, y el intervalo del 76-77% también queda por debajo de la proporción de defunciones registrada en este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f38") }, {"long_answer": "Los menores de 6 meses no pueden recibir la vacuna antigripal, por lo que su protección depende de la vacunación durante el embarazo y de la vacunación de su entorno. Por ello se recomienda vacunar a los cuidadores principales y convivientes de estos lactantes, creando una estrategia de protección indirecta. La recomendación no se limita a las madres lactantes, ni únicamente al personal sanitario o de educación infantil, aunque estos colectivos también tienen recomendada la vacunación por otros motivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f39") }, {"long_answer": "El objetivo principal de la atención prenatal es asegurar el nacimiento de niños y niñas sanos con el mínimo riesgo para las madres, mediante la prevención, la detección precoz y el tratamiento de los problemas que puedan afectar a la gestación, incluida la revisión del estado vacunal. Vacunar a la mujer frente a todas las enfermedades no es posible ni adecuado, el cribado serológico se realiza de forma selectiva según lo indicado y no de forma masiva indiscriminada, e iniciar pautas completas de vacunación es solo una de las actividades, no el objetivo principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3c") }, {"long_answer": "Tras administrar cada dosis de vacuna triple vírica a una mujer en edad fértil se recomienda evitar el embarazo durante 4 semanas (un mes), ya que se trata de una vacuna de virus vivos atenuados con un riesgo teórico para el feto. Sin embargo, la vacunación inadvertida durante el embarazo o en el periodo previo no justifica la interrupción de la gestación, porque no se han observado malformaciones atribuibles a la vacuna. El plazo de 2 semanas es insuficiente, el de 6 semanas no es el recomendado, y sí existe una restricción temporal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f3d") }, {"long_answer": "En las mujeres en edad fértil no embarazadas, el cribado serológico de rubeola solo se realiza cuando no existe evidencia documentada de inmunidad, es decir, cuando no constan dosis de vacuna adecuadas ni una serología positiva previa. En esos casos, si la serología es negativa, se administra la vacuna triple vírica. No está indicado en todas las mujeres con independencia de su historia vacunal, ni en las que tienen antecedentes de vacunación y serología positiva, ya protegidas. Las mujeres con dos dosis documentadas se consideran inmunes y no se recomienda su cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f46") }, {"long_answer": "La vacuna triple vírica, frente al sarampión, la rubeola y la parotiditis, contiene virus vivos atenuados y está contraindicada durante el embarazo por el riesgo teórico de transmisión al feto, aunque en los casos de administración inadvertida no se han observado problemas de seguridad ni síndrome de rubeola congénita. Las vacunas de hepatitis B recombinante, la inactivada frente a la gripe y la antitetánica son inactivadas o de toxoides y pueden administrarse durante la gestación cuando están indicadas; de hecho, la antigripal está recomendada sistemáticamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f53") }, {"long_answer": "La vacuna inactivada frente a la gripe está recomendada en las embarazadas en cualquier trimestre durante la temporada gripal, porque protege a la madre frente a complicaciones y los anticuerpos transferidos a través de la placenta protegen al lactante en sus primeros meses de vida, cuando aún no puede ser vacunado. Las vacunas de virus vivos atenuados, como la antigripal intranasal, están contraindicadas en el embarazo. La dTpa protege frente a la tosferina y la vacuna de hepatitis B frente a esa infección, pero ninguna de ellas protege frente a la gripe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5e") }, {"long_answer": "El programa de cribado de cáncer colorrectal se dirige a mujeres y hombres de 50 a 69 años, a quienes se ofrece una prueba de sangre oculta en heces, de tipo inmunológico, cada 2 años; los resultados positivos se estudian mediante colonoscopia. No se dirige solo a mujeres ni utiliza la colonoscopia como prueba primaria trienal. La tomografía no es una prueba de cribado poblacional, y la población de 45 a 75 años no corresponde a la población diana del programa. Tampoco se limita a hombres ni se realiza con periodicidad anual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f5f") }, {"long_answer": "Para la tasa de aceptación de biopsia en el cribado de cáncer de mama, los estándares de calidad establecen un nivel aceptable del 90% y un nivel deseable superior al 90%, ya que la mayoría de las mujeres a las que se indica una biopsia tras una prueba de cribado alterada deben completarla para no perder diagnósticos. Los valores del 60%, el 70% o el 85% como nivel aceptable son demasiado bajos y supondrían que una parte importante de las lesiones sospechosas quedaría sin confirmar, lo que comprometería la efectividad del programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f67") }, {"long_answer": "La gestión del Sistema de Información de los programas de Cribado de Cáncer (SICC) y la garantía de la seguridad de la información corresponden al Ministerio de Sanidad, a través de la Dirección General de Salud Digital y Sistemas de Información para el SNS. Las Comunidades Autónomas son responsables de sus programas y de aportar los datos, pero no gestionan el sistema común. El Instituto Nacional de Estadística no participa en esta función, y los centros asistenciales registran la actividad, pero no gestionan el sistema de información."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6a") }, {"long_answer": "La tasa bruta de incidencia se calcula dividiendo el número de casos nuevos diagnosticados en un periodo entre la población total de todas las edades y multiplicando por 100.000, por lo que se expresa en casos por 100.000 habitantes. Al no ajustarse por edad ni restringirse a un grupo concreto, es una tasa bruta. Multiplicar por 1.000 no es la convención para el cáncer, usar como denominador la población diana daría una tasa específica de ese grupo, y emplear los casos totales en lugar de los nuevos correspondería a la prevalencia, no a la incidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f74") }, {"long_answer": "En el cribado de cáncer de mama, la tasa de aceptación del primer tratamiento tiene un nivel aceptable recomendado del 90%, lo que significa que al menos nueve de cada diez mujeres diagnosticadas en el programa deben aceptar e iniciar el tratamiento indicado, condición imprescindible para que la detección precoz se traduzca en reducción de la mortalidad. Los valores del 70% y el 85% son inferiores al estándar aceptable establecido, y el 95% se sitúa por encima del nivel aceptable, acercándose más a un nivel deseable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f76") }, {"long_answer": "Cuando la prueba primaria de cribado de cérvix muestra una citología ASC-US y el triaje con determinación de VPH es negativo, el riesgo de lesión de alto grado es muy bajo, por lo que se recomienda realizar un co-test, citología y VPH, a los 3 años antes de volver al cribado rutinario. Repetir la citología a los 6 meses supone un seguimiento excesivo. La derivación directa a colposcopia se reserva para el VPH positivo o lesiones de mayor grado, y suspender el cribado 5 años no corresponde a este resultado anómalo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f88") }, {"long_answer": "En los niños con infección por VIH, el calendario de vacunación en grupos de riesgo establece para la vacuna meningocócica MenACWY una dosis de recuerdo a los 12 años, coincidiendo con la recomendada en la población general. A diferencia de lo que ocurre en la asplenia o en las deficiencias del complemento, no se indican recuerdos periódicos cada 5 años en este grupo. Tampoco es correcto afirmar que no se recomienda ningún recuerdo, y la administración anual no tiene fundamento, ya que la protección no requiere refuerzos con esa frecuencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8c") }, {"long_answer": "La vacuna de la varicela es de virus vivos atenuados, por lo que está contraindicada durante el embarazo y en las personas con inmunosupresión grave, por el riesgo de enfermedad diseminada por el virus vacunal o de afectación fetal. La asplenia no contraindica las vacunas atenuadas, y la enfermedad hepática crónica sin complicaciones es más bien una indicación de vacunación frente a varias enfermedades. El tratamiento con ácido acetilsalicílico supone una precaución por el riesgo teórico de síndrome de Reye, recomendándose evitar salicilatos durante 6 semanas tras la vacuna, pero no es una contraindicación absoluta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8f") }, {"long_answer": "En determinados grupos de riesgo, como las personas con asplenia anatómica o funcional o los receptores de trasplante de progenitores hematopoyéticos, se recomienda administrar la vacuna frente a Haemophilus influenzae tipo b con independencia de la vacunación previa, debido a su mayor vulnerabilidad frente a las bacterias encapsuladas o a la pérdida de la inmunidad tras el trasplante. No se trata de proteger a menores con inmunidad intacta, la eficacia de la vacuna no depende de una vacunación previa completa, y la revacunación no tiene como fin evitar reacciones adversas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f94") }, {"long_answer": "En los prematuros de menos de 32 semanas de gestación se recomienda la vacunación antigripal anual con vacuna inactivada entre los 6 y los 24 meses de edad. La primera temporada en que se vacunan deben recibir 2 dosis separadas al menos 4 semanas, y en las temporadas siguientes una sola dosis. La vacuna atenuada intranasal no está autorizada antes de los 2 años y no se administra a los 6 meses. No es cierto que la vacunación no se recomiende en estos niños, y la pauta de una dosis anual sin más especificaciones no contempla las dos dosis iniciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f95") }, {"long_answer": "En las personas que han recibido tratamiento por una lesión intraepitelial de alto grado en el cérvix (CIN2+), la vacunación frente al VPH se recomienda con una pauta de 3 dosis, a los 0, 1-2 y 6 o más meses, porque reduce el riesgo de recurrencia de las lesiones. Al tratarse de un grupo de riesgo, no se aplican las pautas reducidas de la población general. No se administra una única dosis con finalidad paliativa, la vacunación no está contraindicada en esta situación, y no existe una pauta de solo recuerdo sin primovacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f96") }, {"long_answer": "En los pacientes con infección por VIH que no responden a la primera pauta de vacunación frente a la hepatitis B, se recomienda revacunar con la vacuna de tipo adulto o de mayor carga antigénica, con una pauta de 0, 1 y 6 meses, y comprobar después los marcadores serológicos, ya que la respuesta inmunitaria en estos pacientes suele ser menor. No revacunar los dejaría sin protección frente a una infección con gran impacto en esta población. Las dosis semanales hasta obtener respuesta no constituyen una pauta establecida, y la vacuna de hepatitis B ya es inactivada, por lo que no existe la alternativa planteada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9c") }, {"long_answer": "En las personas no vacunadas con infección por VIH y riesgo de hepatitis B, se recomienda verificar previamente los marcadores serológicos, para descartar infección previa o actual, y administrar 3 dosis con pauta de 0, 1 y 6 meses, comprobando después la respuesta. Una dosis única de vacuna adyuvada no completa la pauta, y la inmunoglobulina antihepatitis B solo proporciona protección pasiva y transitoria tras una exposición, sin sustituir a la vacuna. La pauta de 4 dosis sin verificar marcadores no es la recomendada con carácter general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9d") }, {"long_answer": "La vacuna frente a la varicela es de virus vivos atenuados y está contraindicada en los adultos con infección por VIH y recuento de linfocitos CD4 inferior a 200/μl, por el riesgo de enfermedad por el virus vacunal en una situación de inmunosupresión grave. Solo en personas con CD4 iguales o superiores a 200/μl y serología negativa puede administrarse la vacuna, con 2 dosis separadas al menos 4 semanas. Una dosis única tras serología negativa no es la pauta adecuada, y el antecedente certificado de varicela indica inmunidad, por lo que no sería necesaria la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa0") }, {"long_answer": "En los adultos con infección por VIH y condiciones de riesgo de hepatitis A se recomienda una pauta de 2 dosis: una dosis inicial y una dosis de recuerdo a partir de los 6 meses, valorando la comprobación de la respuesta por la posible menor inmunogenicidad en esta población. La pauta de 0, 1 y 6 meses corresponde a la vacuna de la hepatitis B o a la vacuna combinada de hepatitis A y B. La dosis única sin recuerdo no asegura una protección duradera, y la vacuna es inactivada, por lo que no está contraindicada en la infección por VIH."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa4") }, {"long_answer": "En el calendario de vacunación de grupos de riesgo de 2025, la vacunación frente al VPH en hombres que tienen relaciones sexuales con hombres no vacunados se recomienda hasta los 25 años inclusive con una pauta de 1 dosis, de acuerdo con la evidencia que respalda la eficacia de la dosis única en personas jóvenes inmunocompetentes. Las pautas de 2 o 3 dosis se mantienen para otras situaciones, como la inmunosupresión o determinados grupos de riesgo específicos. Afirmar que no se recomienda la vacunación es incorrecto, ya que este colectivo tiene una indicación expresa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa5") }, {"long_answer": "En los adultos con condiciones de riesgo, el calendario de 2025 recomienda administrar 1 dosis de vacuna antigripal en cada temporada estacional, ya que la composición de la vacuna se actualiza anualmente y la protección disminuye con el tiempo. La pauta de 2 dosis solo se aplica a los menores de 9 años que se vacunan por primera vez, no a los adultos. La indicación no se limita a las personas con asplenia ni a las que tienen infección por VIH, sino que abarca a todos los adultos con condiciones de riesgo recogidas en el calendario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa7") }, {"long_answer": "En los adultos con patologías de riesgo, la vacunación frente a la enfermedad neumocócica debe valorarse de forma individual, utilizando una pauta secuencial o la vacuna conjugada más adecuada según la patología de base, los antecedentes de vacunación y las vacunas disponibles en cada momento. No se limita a una dosis única de vacuna conjugada en todos los casos, ya que algunas condiciones requieren pautas adicionales. La vacuna no está contraindicada en estas personas, que son precisamente las que más se benefician, y la indicación abarca muchas otras patologías además de la cardiovascular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa8") }, {"long_answer": "En los adultos con asplenia o disfunción esplénica el calendario recomienda la vacuna MenACWY con una pauta de 2 dosis separadas por un intervalo mínimo de 8 semanas, seguida de dosis de recuerdo cada 5 años mientras persista el riesgo, debido a la mayor susceptibilidad de estos pacientes frente a las bacterias encapsuladas. Un intervalo de 2 semanas es demasiado corto para lograr una respuesta óptima, y 6 meses no es el intervalo establecido entre las dosis de la primovacunación. Sí se especifica un intervalo mínimo en el calendario.", "option_1": "8 semanas"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977faa") }, {"long_answer": "El síndrome WHIM es una inmunodeficiencia primaria caracterizada por una especial susceptibilidad a las infecciones por el virus del papiloma humano, con verrugas extensas y de difícil tratamiento, por lo que se recomienda la vacunación con una vacuna frente al VPH que incluya los tipos 6 y 11, responsables de las verrugas, como la nonavalente, que además cubre los tipos oncogénicos. Una vacuna que cubra solo los tipos 16 y 18 no protege frente a las verrugas. Esperar a que aparezcan lesiones resta eficacia, y la vacunación sí está recomendada en este síndrome.", "option_1": "Vacuna frente al VPH que incluya los tipos 6 y 11", "option_3": "Vacunación frente al VPH solo tras la aparición de verrugas"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fab") }, {"long_answer": "En los adultos mayores de 18 años se recomienda realizar serología de varicela antes de vacunar a quienes no tienen antecedentes claros de haber pasado la enfermedad o los tienen inciertos y no están vacunados, ya que muchos adultos son inmunes aunque no lo recuerden, lo que evita vacunaciones innecesarias. No es necesario hacerla en todos los adultos, como los que tienen antecedente fiable de varicela o herpes zóster. Tampoco se limita a las personas inmunodeprimidas, y quienes han recibido 2 dosis de vacuna se consideran protegidos sin necesidad de serología."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb4") }, {"long_answer": "Se considera que una persona adulta es inmune frente a la varicela cuando tiene documentada la recepción de 2 dosis de vacuna frente al virus varicela zóster, o bien un antecedente fiable de varicela o herpes zóster o una serología positiva. Una sola dosis de vacuna no se considera suficiente en adultos, por lo que debe completarse la pauta con una segunda. La vacunación con triple vírica protege frente al sarampión, la rubeola y la parotiditis, pero no confiere inmunidad frente a la varicela, y una serología negativa con una sola dosis indica que la persona no está protegida.", "option_3": "Vacunación previa con triple vírica"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb6") }, {"long_answer": "El calendario de 2025 recomienda la vacunación antigripal anual de las personas internas en residencias y centros de larga estancia, así como de los convivientes y cuidadores de personas mayores o con condiciones de riesgo, para protegerlas de forma directa e indirecta frente a complicaciones graves. La recomendación no se limita al personal sanitario, aunque este también es un grupo prioritario, ni únicamente a las personas con asplenia. El antecedente de neumonía no constituye por sí mismo el criterio que define a la población que debe vacunarse anualmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fbb") }, {"long_answer": "En el personal sanitario con condiciones de riesgo se recomienda administrar 1 dosis de vacuna frente a la COVID-19 en cada temporada estacional, con posibilidad de dosis adicionales en caso de inmunosupresión de alto grado, en quienes la respuesta inmunitaria es menor. La vacunación no se pauta cada 5 años ni solo al comenzar la actividad profesional, ya que la protección disminuye con los meses y las vacunas se actualizan según las variantes circulantes. Afirmar que no está recomendada es incorrecto, ya que este colectivo tiene indicación por su riesgo y su exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fbf") }, {"long_answer": "Para que las dosis de un mismo antígeno sean válidas deben respetarse los intervalos mínimos: entre dosis de primovacunación suelen ser de 4 a 8 semanas y, entre la primovacunación y las dosis de recuerdo, de 8 semanas a 6 meses según la vacuna. No existe un intervalo máximo, por lo que una pauta interrumpida se continúa sin reiniciarla, independientemente del tiempo transcurrido. Las dosis administradas con intervalos menores de los recomendados pueden no ser válidas y deben repetirse, por lo que sí es necesario respetar los intervalos entre dosis del mismo antígeno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc4") }, {"long_answer": "En la vacunación de las personas de 7 a 18 años, la vacuna meningocócica MenACWY se administra a los 12 años como dosis de recuerdo, siguiendo el calendario común de vacunación a lo largo de toda la vida, de forma que se protege a los adolescentes, grupo con mayor tasa de portadores y de transmisión. La vacuna de hepatitis B y la triple vírica se administran en pautas de primovacunación de varias dosis si la persona no está vacunada, y la vacuna de polio inactivada forma parte de la pauta de rescate, pero ninguna de ellas corresponde a la dosis de recuerdo de los 12 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc6") }, {"long_answer": "En los adultos sin vacunación previa frente a la hepatitis B se recomiendan tres dosis, con un esquema de 0, 1 y 6 meses o de 0, 2 y 4 meses, respetando los intervalos mínimos entre dosis para asegurar la protección. Una dosis única con refuerzo anual no se corresponde con ninguna pauta establecida. Dos dosis separadas por 2 semanas no garantizan la respuesta inmunitaria ni respetan los intervalos mínimos, y la administración de cuatro dosis anuales tampoco se ajusta a las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fcd") }, {"long_answer": "Según el documento de vacunación acelerada, tanto Infanrix-IPV como Tetraxim pueden administrarse de forma simultánea con las vacunas triple vírica, varicela y Haemophilus influenzae tipo b, y se considera que Infanrix-IPV también puede administrarse junto con la vacuna de hepatitis B, lo que facilita completar el calendario en menos visitas. Por tanto, no es cierto que no puedan coadministrarse con ninguna otra vacuna, ni que solo Tetraxim pueda administrarse con la de hepatitis B, ni que Infanrix-IPV deba administrarse sin otras vacunas concomitantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fce") }, {"long_answer": "Para elegir entre Infanrix-IPV y Tetraxim hay que valorar las posibles reacciones de hipersensibilidad a los excipientes o trazas específicas de cada vacuna, como antibióticos o sustancias empleadas en su fabricación, ya que su composición no es idéntica. Por ello no es correcto afirmar que no existan diferencias en las contraindicaciones. La alergia a la penicilina no es una contraindicación de estas vacunas, que no la contienen, y el embarazo no supone una contraindicación de las vacunas de toxoides y poliovirus inactivados, aunque en la gestación se prefiera la dTpa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd4") }, {"long_answer": "Tetraxim puede contener trazas de glutaraldehído, utilizado en su proceso de fabricación, que no figuran en Infanrix-IPV y que pueden causar reacciones alérgicas en personas sensibilizadas, por lo que debe tenerse en cuenta al elegir entre ambas vacunas. El ácido paraaminobenzoico no es un componente de estas vacunas, el cloruro sódico es un excipiente habitual sin relevancia alérgica, y la pertactina es un antígeno de la tosferina acelular presente en Infanrix-IPV, no una traza exclusiva de Tetraxim."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd8") }, {"long_answer": "En la vacunación acelerada de personas sin documentación vacunal previa, la primera visita debe priorizar las vacunas frente a las enfermedades con mayor riesgo de transmisión o gravedad y con objetivos de eliminación, como el sarampión, la rubeola, la poliomielitis, el tétanos y la difteria, administrando en la misma visita todas las vacunas posibles según la edad. Limitarse al neumococo y la varicela, o exclusivamente a la hepatitis B, dejaría sin protección frente a enfermedades prioritarias. Administrar solo vacunas vivas no es un criterio de priorización, ya que la elección depende de la edad y del riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd9") }, {"long_answer": "En la vacunación acelerada, el intervalo mínimo recomendable entre la última dosis de primovacunación y la dosis de recuerdo del mismo antígeno se sitúa entre 8 semanas y 6 meses, según la vacuna, para que la respuesta de memoria inmunológica sea adecuada y la dosis se considere válida. Un intervalo de solo 2 semanas es insuficiente y la dosis no contaría. Sí existe un intervalo mínimo entre dosis de recuerdo y primovacunación, y exigir al menos 12 meses alargaría innecesariamente la pauta acelerada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe0") }, {"long_answer": "El plan de erradicación de la poliomielitis establece que, cuando las Comunidades Autónomas detectan áreas con coberturas de vacunación inferiores al 90%, deben notificarlo y desarrollar estrategias de captación y vacunación de la población no vacunada o de alto riesgo, ya que las bolsas de población susceptible favorecen la transmisión si se importa el virus. Eliminar la vacunación o esperar sin intervenir agravaría el problema, y limitarse a informar a los medios de comunicación no mejora las coberturas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fe5") }, {"long_answer": "En España, las muestras para la detección de poliovirus procedentes de casos de parálisis flácida aguda se procesan en laboratorios primarios de vigilancia de PFA acreditados, que cumplen los requisitos de bioseguridad y calidad exigidos y trabajan en coordinación con el Laboratorio Nacional de Poliovirus. Los laboratorios de diagnóstico microbiológico generales no están designados para esta función, los de microbiología veterinaria no participan en la vigilancia de la poliomielitis humana, y los laboratorios privados no acreditados no pueden procesar estas muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fec") }, {"long_answer": "La detección de poliovirus en muestras ambientales de aguas residuales indica circulación del virus en la población aunque no se hayan detectado casos clínicos, por lo que debe notificarse de inmediato al Centro de Coordinación de Alertas y Emergencias Sanitarias (CCAES) y enviar las muestras al Laboratorio Nacional de Poliovirus para su confirmación y caracterización. Ignorar el hallazgo por la ausencia de casos sería un error grave, ya que la mayoría de las infecciones son asintomáticas. Publicar informes sin actuar o desinfectar sin investigar no constituyen la respuesta establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff1") }, {"long_answer": "Tras el cierre de una alerta por detección de poliovirus en una instalación, deben destruirse todas las muestras y materiales infecciosos o potencialmente infecciosos y certificar esa destrucción al Laboratorio Nacional de Poliovirus, en cumplimiento de las medidas de contención del plan de acción mundial, cuyo objetivo es minimizar el riesgo de liberación del virus. Mantener o almacenar las muestras para estudios futuros o vigilancia prolongada solo puede hacerse en instalaciones expresamente autorizadas para ello, y no basta con eliminar únicamente las muestras positivas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ff7") }, {"long_answer": "El Comité Nacional para la Certificación de la Erradicación de la Poliomielitis supervisa las actividades necesarias para documentar y mantener la situación de país libre de polio, como la vigilancia de la parálisis flácida aguda, la vigilancia ambiental, las coberturas vacunales y la contención en laboratorio, y elabora informes anuales que remite a la Comisión Regional de Certificación de la Región Europea de la OMS. No fabrica vacunas, no se limita a investigar casos clínicos en otros países y no se dedica a aprobar campañas de comunicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ffc") }, {"long_answer": "Se considera poliovirus vacunal o Sabin-like a las cepas derivadas de la vacuna oral atenuada que presentan una divergencia en la secuencia de la proteína VP1 inferior al 1% para los tipos 1 y 3 e inferior al 0,6% para el tipo 2 respecto a las cepas vacunales originales. Si la divergencia supera estos valores se habla de poliovirus derivado de la vacuna, con mayor riesgo de recuperar neurovirulencia. Las cepas salvajes no proceden de la vacuna, y los poliovirus Sabin-like sí están relacionados con ella y conservan capacidad infectiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978000") }, {"long_answer": "Los anestésicos locales son fármacos que, aplicados en una zona concreta, impiden de forma transitoria, reversible y predecible la conducción del impulso nervioso, y pueden afectar también a la conducción muscular, produciendo la pérdida de sensibilidad en la zona sin pérdida de consciencia. Por ello, no producen anestesia general, que sí implica pérdida de consciencia. No se trata de antitérmicos ni de analgésicos sistémicos para el dolor generalizado, y tampoco actúan como relajantes musculares periféricos, cuyo mecanismo es el bloqueo de la placa motora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978005") }, {"long_answer": "La guía establece que en la historia clínica debe quedar registrada la identificación de la enfermera o el enfermero responsable de la actuación y las intervenciones realizadas conforme al protocolo o guía correspondiente, garantizando la trazabilidad, la continuidad asistencial y la seguridad del paciente. No basta con la firma del médico responsable sin detallar la actuación enfermera, ni con anotar solo la dosis sin la hora de administración, ni con registrar únicamente el nombre del anestésico utilizado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978007") }, {"long_answer": "La dispensación de anestésicos locales por parte de enfermeros se realiza mediante la orden de dispensación enfermera, documento regulado por el Real Decreto 1718/2010 sobre receta médica y órdenes de dispensación, que permite a las enfermeras acreditadas indicar y dispensar medicamentos en el marco de los protocolos y guías aprobados. No se requiere una prescripción médica tradicional en cada caso, la receta electrónica médica no se emite automáticamente para estas actuaciones, y no es necesaria una autorización administrativa previa de farmacia hospitalaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97800b") }, {"long_answer": "Para aplicar la guía de anestésicos locales, la enfermera debe ser titular de la correspondiente acreditación para la indicación, uso y autorización de dispensación de medicamentos, emitida por el órgano competente de su Comunidad Autónoma conforme al Real Decreto 954/2015. No se exige un título de medicina, la experiencia clínica previa sin acreditación formal no habilita para estas actuaciones, y una certificación en gestión hospitalaria no guarda relación con la competencia requerida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978010") }, {"long_answer": "La Comisión Permanente de Farmacia del Consejo Interterritorial del SNS es el órgano encargado de elaborar y validar las guías para la indicación, uso y autorización de dispensación de medicamentos por parte de las enfermeras, como la guía de anestésicos locales, que posteriormente se publica por resolución del Ministerio. No se limita a controlar la dispensación en las farmacias comunitarias, no se encarga de formar al personal auxiliar y no supervisa la administración hospitalaria de anestésicos generales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978014") }, {"long_answer": "En situaciones urgentes que requieran anestésico local, la guía contempla que la enfermera actúe de forma inmediata dentro de su ámbito competencial y conforme al protocolo o guía asistencial consensuado, para no demorar la atención que necesita el paciente. La derivación automática al médico para toda intervención, la exigencia de la presencia de un anestesista o la consulta previa a farmacia retrasarían la asistencia y no se corresponden con lo previsto para estas situaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801a") }, {"long_answer": "La guía establece que la actuación enfermera en la indicación y uso de anestésicos locales debe basarse en protocolos y guías asistenciales elaborados y acordados de forma multidisciplinar y consensuada entre los profesionales implicados, médicos, enfermeras y farmacéuticos, lo que asegura la seguridad del paciente y la continuidad asistencial. No pueden ser elaborados unilateralmente por enfermería, ni dependen de una decisión exclusiva del anestesista, y no tienen relación con acuerdos con farmacias privadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97801d") }, {"long_answer": "En las infecciones del tracto urinario inferior no complicadas en mujeres adultas, el objetivo del tratamiento es erradicar la infección y resolver la sintomatología, utilizando el antibiótico adecuado durante el menor tiempo eficaz para limitar efectos adversos y resistencias. La prevención en la población general no es un objetivo terapéutico, la reducción de efectos secundarios es una consideración secundaria al elegir el fármaco, y el seguimiento a largo plazo no se requiere en una infección no complicada con buena evolución."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978022") }, {"long_answer": "La guía atribuye a la enfermera un papel destacado en la educación sanitaria de la mujer con infección urinaria no complicada: enseñarle a reconocer los síntomas, identificar los signos de alarma que obligan a consultar, como fiebre, dolor lumbar o persistencia de síntomas, y promover el uso responsable de los antibióticos, cumpliendo la pauta indicada. No se limita a indicar que acuda al médico, no consiste en proponer tratamientos alternativos sin antibiótico cuando este está indicado, y no prioriza únicamente la administración del fármaco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978024") }, {"long_answer": "Para el tratamiento empírico de la infección urinaria se recomienda emplear antibióticos cuya tasa de resistencia local en los uropatógenos habituales, principalmente Escherichia coli, sea inferior al 20%, ya que por encima de ese umbral aumenta notablemente la probabilidad de fracaso terapéutico. Un umbral del 50% sería claramente inaceptable, utilizar fármacos con resistencias superiores al 20% no es una opción recomendada para el tratamiento empírico, y las resistencias son precisamente uno de los criterios principales para seleccionar el antibiótico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978026") }, {"long_answer": "La guía define la recidiva clínica como la reaparición de la infección urinaria, habitualmente causada por el mismo microorganismo, en un plazo inferior a 15 días desde el episodio previo, lo que sugiere un fracaso del tratamiento o la persistencia del germen. Las reinfecciones aparecen más tarde y suelen deberse a otro microorganismo. Los síntomas durante más de 7 días no definen la recidiva, la existencia de dos o más episodios en un año se relaciona con la infección urinaria recurrente, y la reaparición pasado un mes no corresponde a una recidiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978028") }, {"long_answer": "En el marco del seguimiento colaborativo de la infección urinaria no complicada, la guía permite que la enfermera acreditada intervenga en el tratamiento antibiótico: puede iniciarlo, interrumpirlo temporalmente, modificarlo y finalizarlo según los criterios establecidos en el protocolo. Su actuación no se limita a administrar el tratamiento prescrito por el médico ni a la educación sanitaria, aunque ambas sean también funciones propias. En cambio, no le corresponde el diagnóstico médico ni la prescripción libre de antibióticos nuevos fuera del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802a") }, {"long_answer": "Cuando la enfermera realiza actuaciones de indicación y dispensación, en la historia clínica debe quedar registrada su identificación y la actuación realizada, fundamentada en el protocolo o guía correspondiente, lo que asegura la trazabilidad, la continuidad asistencial y la seguridad del paciente. No basta con registrar solo el medicamento dispensado o la fecha y hora de la dispensación. Tampoco se trata de registrar un diagnóstico médico establecido por enfermería, ya que el diagnóstico de la infección no corresponde a su ámbito de actuación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802c") }, {"long_answer": "La guía permite a la enfermera acreditada modificar el tratamiento antibiótico en el marco del protocolo mediante el cambio de la pauta, la prórroga, la interrupción temporal y la finalización del tratamiento, de acuerdo con criterios previamente consensuados. No se limita a la administración y el seguimiento del tratamiento prescrito. En cambio, no puede prescribir antibióticos de segunda línea al margen del protocolo, ni realizar cambios basados exclusivamente en su decisión personal, ya que toda actuación debe ajustarse a las guías acordadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97802d") }, {"long_answer": "La actuación enfermera según esta guía se limita a la infección urinaria no complicada en mujeres adultas. Por ello, la presencia de signos o síntomas que sugieren una infección complicada, como fiebre o dolor lumbar, o la atención a una población distinta, como varones, embarazadas o menores, obligan a derivar al médico. La primera consulta en atención primaria y la paciente sin factores de riesgo con síntomas leves son precisamente el escenario de aplicación de la guía, y la bacteriuria asintomática no es objeto de tratamiento en este contexto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978031") }, {"long_answer": "El ejercicio físico regular no figura en la guía como factor que incremente la incidencia de infección urinaria; por tanto, es la opción correcta en esta pregunta negativa. En cambio, la guía sí señala que la incidencia aumenta con la edad avanzada, por cambios anatómicos, hormonales y funcionales, con la comorbilidad, como la diabetes o las alteraciones urológicas, y con la institucionalización, por la mayor frecuencia de dependencia, incontinencia y uso de sondas vesicales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978035") }, {"long_answer": "Los protocolos y guías de actuación que se deriven de la guía general deben definir, como mínimo, la población diana a la que se aplican, los medicamentos que la enfermera puede indicar y dispensar, el tipo de intervenciones que puede realizar y los criterios de derivación al médico, de modo que la actuación sea segura y homogénea. No pueden limitarse a la administración de medicamentos prescritos por el médico, ni a aspectos administrativos de dispensación en farmacia, ni a listados de productos sanitarios sin incluir medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978036") }, {"long_answer": "La autonomía de las enfermeras en el manejo de la infección urinaria no complicada se apoya en la aplicación de protocolos consensuados de forma multidisciplinar y validados, que delimitan su actuación y garantizan la seguridad de la paciente y la coordinación con el resto del equipo. Esa autonomía no implica una prescripción libre sin protocolo, no consiste en derivar de forma inmediata a atención especializada sin intervenir, y va más allá de la mera administración de antibióticos indicados por el médico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978037") }, {"long_answer": "La guía establece que la enfermera puede finalizar el tratamiento antimicrobiano cuando se ha completado la pauta indicada, cuando la paciente rechaza continuarlo o cuando procede adecuarlo tras conocer el resultado del antibiograma. Suspenderlo al desaparecer los síntomas, sin tener en cuenta la duración prevista, favorece las recaídas y las resistencias. No se requiere una solicitud expresa del médico para cada finalización, y cumplir 3 días de tratamiento no es por sí mismo un criterio de finalización si la pauta indicada es diferente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97803d") }, {"long_answer": "El Real Decreto 1302/2018 establece que los supuestos en los que se precisa la validación médica previa a la indicación enfermera de medicamentos sujetos a prescripción médica deben figurar en los protocolos y guías de práctica clínica y asistencial, elaborados y validados conforme a lo previsto en la norma. No se recogen en órdenes ministeriales generales, ni en los reglamentos internos de cada centro sanitario, ni en la normativa autonómica, ya que los protocolos y guías son el instrumento común que garantiza la homogeneidad en todo el SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978043") }, {"long_answer": "La exigencia de que las actuaciones de enfermería en la indicación y dispensación de medicamentos garanticen la continuidad asistencial y la seguridad del paciente responde al principio de colaboración interprofesional, que implica que médicos y enfermeras actúen de forma coordinada mediante protocolos y guías consensuados. El principio de legalidad se refiere al sometimiento a la norma, el de eficiencia administrativa a la gestión de recursos, y la educación continua se relaciona con la formación de los profesionales, pero ninguno de ellos expresa esta finalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804a") }, {"long_answer": "La modificación del artículo 7 introducida por el Real Decreto 1302/2018 establece que solo de manera excepcional, cuando los avances científicos lo requieran en relación con medicamentos de especial complejidad, podrá exigirse a las enfermeras una formación complementaria para su indicación. No se vincula a criterios de viabilidad económica, no se limita al ámbito pediátrico y no establece una formación obligatoria cada dos años, sino que se reserva para supuestos concretos que la justifiquen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804b") }, {"long_answer": "La disposición transitoria única del Real Decreto 1302/2018 permite que las enfermeras y enfermeros que, hasta su entrada en vigor, venían realizando estas funciones conforme a la normativa autonómica puedan continuar aplicando los protocolos y guías de acuerdo con la normativa que los habilitó, garantizando la continuidad de la atención mientras se adaptan al nuevo marco. Por tanto, no deben cesar inmediatamente, no necesitan una reevaluación por el Ministerio de Sanidad para continuar, y no se exige supervisión médica directa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97804c") }, {"long_answer": "El Real Decreto no establece un régimen sancionador propio para el incumplimiento de los requisitos de indicación y dispensación de medicamentos por enfermería, por lo que las posibles infracciones quedan sujetas a la normativa general aplicable, como la legislación sobre medicamentos y la sanitaria. No se contempla en la norma la suspensión de la acreditación durante un año, ni multas con pérdida definitiva de la licencia, ni la inhabilitación penal o la retirada del título profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978055") }, {"long_answer": "Para los profesionales procedentes de otros Estados miembros de la Unión Europea o de terceros países, el acceso a la acreditación se garantiza siempre que justifiquen el cumplimiento de los requisitos de acreditación regulados en el artículo 9, en las mismas condiciones que el resto de profesionales, una vez que su título les permite ejercer en España. No se exige una homologación adicional específica para la acreditación, no es obligatorio un curso de adaptación del Ministerio, y no se trata de un proceso automático sin evaluación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca978057") }, {"long_answer": "La sentencia del Tribunal Constitucional 76/2018 declaró inconstitucionales algunos preceptos del Real Decreto 954/2015 que atribuían al Estado la acreditación de las enfermeras y otros aspectos de ejecución, por invadir las competencias de las Comunidades Autónomas, lo que obligó a modificar la norma mediante el Real Decreto 1302/2018 para que la acreditación corresponda a los órganos autonómicos. Por tanto, no exigió que solo el Ministerio emitiera acreditaciones, no estableció la prescripción exclusiva de médicos y no impuso sanciones a las comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6c") }, {"long_answer": "En el cribado de cáncer de cérvix, la tasa de aceptación de la colposcopia tiene un estándar aceptable del 90%, lo que significa que al menos nueve de cada diez mujeres derivadas por un resultado alterado deben realizarse la colposcopia, ya que es la prueba que permite confirmar o descartar lesiones precursoras. Los valores del 70%, 80% y 85% son inferiores al estándar recomendado y supondrían que una proporción importante de mujeres con resultados anómalos quedaría sin completar el proceso diagnóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6e") }, {"long_answer": "En el programa de cribado de cáncer colorrectal se consideran exclusiones temporales las situaciones que hacen innecesario el cribado durante un tiempo determinado, como haberse realizado recientemente una colonoscopia completa documentada, de modo que la persona vuelve a ser elegible cuando finaliza el periodo establecido por el programa. La colectomía total y el diagnóstico previo de cáncer colorrectal son exclusiones definitivas, ya que la persona no se beneficia del cribado, y la enfermedad terminal irreversible también se considera una exclusión definitiva.", "option_3": "Personas con colonoscopia completa documentada reciente, excluidas temporalmente durante el intervalo establecido por el programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f6f") }, {"long_answer": "La población diana del programa de cribado de cáncer de mama está formada por las mujeres de 50 a 69 años, a las que se invita a realizarse una mamografía cada 2 años, ya que en este grupo de edad el beneficio del cribado en la reducción de la mortalidad está mejor establecido. El rango de 45 a 79 años excede la población diana definida en el documento, el de 30 a 65 años incluiría a mujeres jóvenes en las que el cribado poblacional no está indicado, y la ausencia de límite superior no se corresponde con el programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f75") }, {"long_answer": "El sistema de información contempla varios métodos para facilitar la introducción de datos: la carga mediante fichero en formato XML o XLS y la introducción manual a través de una interfaz web, de forma que cada programa pueda utilizar la vía que mejor se adapte a sus sistemas. No se limita a la vía manual, ni exclusivamente a la importación de bases de datos SQL. La importación directa sin validación previa no es aceptable, ya que los datos deben pasar controles de calidad que garanticen su coherencia y fiabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7b") }, {"long_answer": "Las causas de exclusión permanente de la población elegible en el cribado de cáncer de cérvix son aquellas en las que el cribado deja de tener sentido: la histerectomía total, el cáncer de cérvix previo, la ausencia congénita de cuello uterino, la enfermedad terminal o el fallecimiento durante la ronda. El embarazo puede retrasar la prueba, pero no excluye de forma permanente, y la ausencia de relaciones sexuales solo se considera en determinadas circunstancias. No responder a una invitación previa no excluye, y los antecedentes familiares no son motivo de exclusión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f7c") }, {"long_answer": "En las personas no vacunadas previamente frente a la hepatitis B, la pauta estándar consiste en 3 dosis a los 0, 1 y 6 meses, que proporciona una respuesta protectora en la gran mayoría de los vacunados. Las pautas de 2 dosis separadas 4 semanas o la dosis única con recuerdo a los 12 meses no son las recomendadas con carácter general. La pauta de 4 dosis a los 0, 1, 2 y 6 o 12 meses se reserva para situaciones especiales, como la necesidad de protección rápida o determinados grupos de riesgo, pero no es la pauta habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f81") }, {"long_answer": "En los menores con enfermedad hepática crónica se recomienda la vacunación frente a la hepatitis A, ya que una hepatitis aguda podría descompensar su hepatopatía. La pauta consiste en una dosis inicial seguida de un recuerdo a partir de los 6 meses, sin necesidad de determinar marcadores serológicos antes o después de la vacunación. No es cierto que no se recomiende por riesgo de rechazo hepático, al contrario, es un grupo prioritario. Las dosis anuales de refuerzo o las trimestrales durante un año no corresponden a ninguna pauta establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f84") }, {"long_answer": "Los menores de 9 años que se vacunan frente a la gripe por primera vez deben recibir 2 dosis separadas al menos 4 semanas en esa primera temporada, para conseguir una respuesta inmunitaria adecuada en un sistema inmunitario sin contacto previo con los antígenos; en las temporadas siguientes basta con una dosis anual. Una dosis única sin refuerzo es insuficiente la primera vez, la vacuna atenuada intranasal no es la primera opción en todos los casos y está contraindicada en algunos grupos de riesgo, y las dosis cada 6 meses no tienen fundamento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f85") }, {"long_answer": "En los niños menores de 10 años que han sufrido una enfermedad invasora por Haemophilus influenzae tipo b se recomienda administrar la vacuna aunque ya estuvieran vacunados, ya que la infección no siempre genera una inmunidad adecuada a estas edades y existe riesgo de reinfección. Los adolescentes sin patología previa no requieren revacunación. La indicación no se restringe a inmunodeprimidos mayores de 12 años, y la vacunación por asplenia no se limita a los adultos, ya que también se indica en la población infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f8b") }, {"long_answer": "La vacuna antigripal atenuada de administración intranasal contiene virus vivos y está contraindicada en los menores de 2 años, en las personas inmunodeprimidas y en los niños en tratamiento con salicilatos, por el riesgo de síndrome de Reye asociado a la infección por virus gripales. Las vacunas inactivadas inyectables pueden administrarse en todas estas situaciones a partir de los 6 meses de edad, y son precisamente las indicadas en estos grupos. Las vacunas adyuvadas y de alta dosis están autorizadas en personas mayores, por lo que no corresponden a la descripción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f90") }, {"long_answer": "En los niños con condiciones de riesgo, como asplenia o deficiencias del complemento, tras la pauta primaria de vacuna frente al meningococo B se recomienda una dosis de recuerdo al año y posteriormente dosis de recuerdo cada 5 años mientras persista el riesgo, debido a la disminución de los anticuerpos con el tiempo. Los recuerdos anuales sin límite no se recomiendan, limitarse a la pauta primaria dejaría a estos niños sin protección duradera, y vacunar solo tras una exposición no garantiza la protección en estos grupos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f91") }, {"long_answer": "La inmunización con el anticuerpo monoclonal frente al virus respiratorio sincitial se dirige, entre otros grupos de riesgo infantil, a los prematuros nacidos antes de las 35 semanas de gestación, que pueden recibirlo antes de cumplir los 12 meses de edad, por su mayor riesgo de bronquiolitis y hospitalización. Los niños sanos mayores de 2 años sin patologías previas no forman parte de los grupos de riesgo a los que se dirige esta inmunización. Los adolescentes con VIH sin inmunosupresión y los adultos mayores con insuficiencia renal no son destinatarios de esta estrategia.", "option_2": "Niños sanos mayores de 2 años sin patologías previas"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f97") }, {"long_answer": "En los menores con condiciones de riesgo para enfermedad meningocócica que no tienen infección por VIH (asplenia, déficit de complemento, tratamiento con eculizumab, trasplante de progenitores hematopoyéticos o antecedente de enfermedad meningocócica invasora), el calendario recoge una pauta de MenACWY de 2 dosis separadas por el intervalo mínimo establecido, seguida de una dosis de recuerdo a los 5 años mientras persista el riesgo. Una dosis única sin refuerzo no ofrece protección suficiente en estos grupos, no existe una pauta de 3 dosis mensuales con recuerdos anuales y la vacunación no solo no está desaconsejada, sino que está expresamente indicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9a") }, {"long_answer": "La asplenia anatómica o la disfunción esplénica grave aumentan de forma muy importante el riesgo de infecciones invasoras por bacterias encapsuladas, por lo que el calendario de grupos de riesgo recomienda vacunar frente a neumococo, Haemophilus influenzae tipo b y meningococo (MenACWY y MenB), además de la gripe anual. Limitarse solo a la vacuna antineumocócica o solo a la meningocócica dejaría sin cubrir otros patógenos encapsulados igualmente relevantes. La vacunación no está contraindicada en estos menores; al contrario, son uno de los grupos prioritarios, y no existe un supuesto riesgo inflamatorio que la desaconseje."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977f9b") }, {"long_answer": "El calendario de grupos de riesgo en la infancia indica valorar una pauta secuencial frente a neumococo (vacuna conjugada seguida de vacuna polisacárida cuando corresponde) en menores con enfermedades crónicas que aumentan el riesgo de enfermedad neumocócica invasora, como la cardiopatía, la enfermedad hepática, la respiratoria crónica, la diabetes o la enfermedad renal, además de las situaciones de inmunodepresión. No depende de que se administre la vacuna antigripal, no se limita a menores sanos, que siguen el calendario sistemático, y la inmunodepresión no contraindica las vacunas antineumocócicas, que son inactivadas y están especialmente indicadas en ese grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fa6") }, {"long_answer": "Las personas con enfermedad renal crónica avanzada, en prediálisis o en hemodiálisis tienen peor respuesta a la vacuna de la hepatitis B, por lo que el calendario recomienda una vacuna adyuvada con AS04 que contiene 20 μg de antígeno de superficie, en pauta de 4 dosis a los 0, 1, 2 y 6 meses, con control serológico posterior. Una dosis única de 10 μg sería insuficiente incluso en población sana. La vacuna de la hepatitis B es recombinante e inactivada, no de virus vivos atenuados, y la vacunación está claramente recomendada en este grupo por su riesgo de exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fac") }, {"long_answer": "En adultos con cáncer en tratamiento o con trasplante de órgano sólido, el calendario de grupos de riesgo recoge la administración de 1 dosis de dTpa para proteger frente a difteria, tétanos y tosferina, verificando además el estado de vacunación frente a tétanos y difteria y completando con Td si es necesario. La pauta de 4 dosis no corresponde a este grupo, y tampoco existe una pauta de 3 dosis separadas 6 meses. Al tratarse de una vacuna inactivada (toxoides y antígenos acelulares), la inmunosupresión no contraindica su uso, aunque la respuesta pueda ser menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fae") }, {"long_answer": "Según el calendario de vacunación en grupos de riesgo de 2025, los adultos con condiciones de riesgo deben recibir 1 dosis de vacuna frente a COVID-19 adaptada en cada temporada estacional, y las personas con alto grado de inmunosupresión pueden necesitar dosis adicionales. La estrategia actual no se basa en una dosis única administrada al inicio de la pandemia ni en pautas fijas de 3 dosis seguidas sin considerar el riesgo. Tampoco se limita al personal sanitario, que es un grupo más entre los recomendados junto a los mayores y las personas con condiciones de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977faf") }, {"long_answer": "El calendario de 2025 recomienda la vacunación frente a la hepatitis A en adultos con mayor riesgo de infección o de complicaciones, entre ellos las personas con infección por VIH, con enfermedad hepática crónica, el personal de laboratorio expuesto al virus y los hombres que tienen sexo con hombres, por el riesgo de transmisión sexual. La enfermedad cardiovascular avanzada no es una indicación específica. La edad mayor de 65 años, por sí sola, tampoco lo es, y el personal sanitario sin riesgo laboral específico no forma parte de los grupos diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb1") }, {"long_answer": "En las personas con infección por VIH no vacunadas previamente frente al virus del papiloma humano, el calendario recomienda la vacunación hasta los 45 años con una pauta de 3 dosis, independientemente de la edad, porque la inmunosupresión reduce la respuesta y las pautas reducidas no han demostrado protección suficiente en este grupo. La pauta de 1 dosis se reserva para población general joven sin condiciones de riesgo. Afirmar que no se recomienda vacunar es incorrecto, ya que es un grupo prioritario, y limitar la pauta de 2 dosis a menores de 30 años no corresponde a la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb3") }, {"option_3": "Personas con asplenia anatómica o funcional", "long_answer": "La triple vírica es una vacuna de virus vivos atenuados y está contraindicada en personas con inmunodepresión grave, como la infección por VIH con recuento de linfocitos CD4 inferior a 200/μl, por el riesgo de enfermedad por el virus vacunal. En cambio, los hombres que tienen sexo con hombres susceptibles deben vacunarse, las personas con asplenia pueden recibir vacunas vivas sin restricción porque su inmunidad celular está conservada, y el personal sanitario vacunado previamente con dos dosis no necesita más dosis, pero tampoco tiene contraindicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb5") }, {"long_answer": "La vacuna frente a herpes zóster de subunidades (HZ/su) se administra en 2 dosis. La pauta habitual separa ambas dosis 2 meses, pero en personas inmunodeprimidas o cuando interesa completar antes la protección, la segunda dosis puede adelantarse respetando un intervalo mínimo de 4 semanas (1 mes). Un intervalo de 2 semanas sería insuficiente para considerar válida la segunda dosis. Seis meses es el límite superior de la pauta recomendada, no el intervalo mínimo, y sí existe un intervalo establecido en ficha técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fb7") }, {"long_answer": "En adultos con cáncer, el calendario de grupos de riesgo actualizado para 2025 recomienda administrar 1 dosis de dTpa, que aporta protección frente a la tosferina además de reforzar la inmunidad frente a tétanos y difteria, revisando el estado vacunal previo. La pauta de 4 dosis de dTpa no corresponde a esta situación. La inmunosupresión no contraindica la vacuna, porque está compuesta por toxoides y antígenos acelulares inactivados. La pauta de 3 dosis de Td corresponde a la primovacunación de adultos no vacunados, no a la recomendación específica para este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc1") }, {"long_answer": "Según la tabla de vacunación acelerada, la vacuna de la hepatitis B requiere como mínimo 3 dosis: la segunda separada al menos 4 semanas de la primera y la tercera al menos 8 semanas (2 meses) de la segunda, con un mínimo de 16 semanas entre la primera y la tercera. Dos dosis separadas 8 semanas no completan la pauta estándar. La pauta de 4 dosis mensuales corresponde a situaciones especiales, como la hemodiálisis con vacunas adyuvadas, y no a la pauta mínima general. Una dosis única nunca es suficiente para considerar a una persona vacunada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc2") }, {"long_answer": "En lactantes que inician la vacunación frente a meningococo B entre los 2 y los 5 meses, la pauta recomendada consiste en dos dosis de primovacunación separadas al menos 2 meses y una dosis de recuerdo entre los 12 y 15 meses, siempre al menos 6 meses después de la última dosis. Una dosis única no genera protección suficiente a esta edad. La pauta de cuatro dosis mensuales no está recogida, y la vacunación sí se recomienda en este rango de edad, que es precisamente el de mayor incidencia de enfermedad meningocócica B."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc3") }, {"long_answer": "En menores de 7 años, las dos dosis de vacunas de virus vivos como la triple vírica y la varicela deben separarse al menos 4 semanas, y el documento de vacunación acelerada señala como preferible un intervalo de 8 semanas para optimizar la respuesta. Administrar ambas dosis el mismo día no es válido, porque la segunda dosis no cuenta. No existe un intervalo máximo de 2 semanas; la limitación es justo la contraria. Además, ambas vacunas requieren dos dosis para considerar completa la protección, por lo que sí existe una segunda dosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc5") }, {"long_answer": "En personas mayores de 7 años sin antecedentes documentados de vacunación, la vacunación frente a tétanos y difteria con Td consiste en 3 dosis de primovacunación (la segunda al menos 4 semanas después de la primera y la tercera al menos 6 meses después de la segunda) y 2 dosis de recuerdo posteriores hasta completar 5 dosis a lo largo de la vida. Dos dosis no completan la primovacunación. No se administran dosis anuales durante 5 años, y nunca se ponen varias dosis del mismo antígeno en una sola visita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc7") }, {"long_answer": "La serología frente a varicela se recomienda en adultos sin antecedentes fiables de haber pasado la enfermedad ni de haber recibido dos dosis de vacuna, para vacunar solo a quienes resulten susceptibles. No es necesaria en todos los adultos, ya que quienes tienen antecedentes de varicela o vacunación completa documentada se consideran inmunes. Tampoco tiene sentido realizarla precisamente en quienes tienen antecedentes de enfermedad, que no precisan vacuna. Afirmar que no se recomienda nunca es incorrecto, porque es la herramienta para identificar a los adultos susceptibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fc9") }, {"long_answer": "Una diferencia relevante entre ambas vacunas tetravalentes (DTPa-VPI) es el componente de tosferina: Infanrix-IPV contiene pertactina, igual que Infanrix Hexa, mientras que Tetraxim solo incluye toxoide pertúsico y hemaglutinina filamentosa, sin pertactina. Por eso la afirmación inversa es falsa. No es cierto que ambas compartan la misma adición de ácido paraaminobenzoico, y tampoco que carezcan de diferencias en antígenos o adyuvantes, ya que difieren tanto en los antígenos de tosferina como en la cantidad de adyuvante de aluminio y en la concentración de toxoide diftérico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fca") }, {"long_answer": "Ambas vacunas utilizan como adyuvante hidróxido de aluminio, pero en distinta cantidad: Infanrix-IPV contiene una cantidad mayor de aluminio por dosis que Tetraxim. No se emplea gel de sílice como adyuvante en ninguna de ellas. El fosfato de calcio no es el adyuvante de Tetraxim. Afirmar que no contienen adyuvantes es incorrecto, ya que las vacunas de toxoides necesitan sales de aluminio para potenciar la respuesta inmunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fcc") }, {"long_answer": "El documento concluye que Infanrix-IPV y Tetraxim tienen un perfil de seguridad bueno y muy similar, sin diferencias destacables en reacciones adversas locales ni sistémicas, lo que permite usarlas indistintamente en las condiciones establecidas. No hay datos de que Infanrix-IPV produzca más reacciones graves o más reacciones locales que Tetraxim. Tetraxim no está contraindicada en menores de 2 años; de hecho, tiene autorizada la primovacunación desde los 2 meses de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fcf") }, {"long_answer": "Según el documento de vacunación acelerada, Infanrix-IPV tiene autorizado su uso en primovacunación a partir de los 2 meses de edad en Bélgica y Luxemburgo, mientras que en España su ficha técnica solo recoge su uso como dosis de recuerdo. Este dato sirve de argumento para su posible uso fuera de ficha técnica en primovacunación en España. No está autorizada exclusivamente en España y Francia, y el documento no menciona Italia, Reino Unido, Alemania ni Suecia como países con esa autorización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977fd0") }, {"long_answer": "El Real Decreto 1015/2009, por el que se regula la disponibilidad de medicamentos en situaciones especiales, permite utilizar un medicamento en condiciones distintas a las autorizadas en su ficha técnica (uso fuera de indicación) de forma excepcional, justificada y con información al paciente. Es la norma que ampara el uso de Infanrix-IPV en primovacunación en España. No es cierto que esté prohibido. Una supuesta Ley de Sanidad de 2003 y una Directiva Europea de Vacunación de 2018 no regulan este supuesto."});
print(`\nParte terminada: ${ok} corregidas, ${del} borradas, ${warn} avisos.`);
